window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-cirurgia-med-cir-07"]={"block":"med:med-cirurgia-med-cir-07","label":"MED · MED CIR 07","count":406,"questions":[{"id":"med-cirurgia-med-cir-07-281095","number":"281095","sourceNumber":"281095","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente de 65 anos com diagnóstico de Mieloma Múltiplo. Sobre a Doença, é\nINCORRETO afirmar:","options":{"A":"Uma das manifestações mais comuns é dor óssea.","B":"O indivíduo com mieloma múltiplo pode desenvolver insuficiência renal.","C":"A pseudo-hiponatremia pode ser encontrada no mieloma.","D":"O nível de creatina plasmática está associada ao prognóstico.","E":"O depósito de amiloide constitui o fator essencial para o aparecimento da lesão renal associada\nà doença."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-217701","number":"217701","sourceNumber":"217701","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente, 24 anos, com lombalgia aguda de início súbito após esforço muscular\n(levantamento de uma caixa pesada). Nega dor\nirradiada ou sinais de alerta (red flags). Ao exame,\napresenta dor miofascial paravertebral e diminuição do arco de movimento. Exame neurológico\nnormal. Além de medidas analgésicas, qual a conduta?","options":{"A":"Ressonância magnética.","B":"Tomografia computadorizada.","C":"Radiografias.","D":"Apenas repouso e orientações."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-182619","number":"182619","sourceNumber":"182619","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente com proteína monoclonal sérica ? 3 g/dl e/ou células plasmáticas na medula\nóssea maior ou igual a 10% e ausência de anemia, insuficiência renal, hipercalcemia e lesões\nósseas líticas. O diagnóstico mais provável dessa condição é:","options":{"A":"Gamopatia monoclonal de significado indeterminado.","B":"Mieloma múltiplo indolente.","C":"Mieloma múltiplo.","D":"Leucemia de células plasmáticas."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-159053","number":"159053","sourceNumber":"159053","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente masculino de 40 anos, pedreiro, vem à consulta com queixa de dor lombar\niniciada há cinco dias, contínua, \"em pontada\", que piora no trabalho. Nega história de trauma ou\nexistência de outros sintomas. No exame, observa-se espasmo da musculatura paravertebral\nlombar; exame neurológico normal. A conduta mais adequada nesse caso é:","options":{"A":"Solicitar exame da proteína C reativa e radiografia simples da coluna lombar, associados à\nprescrição de analgésicos.","B":"Recomendar repouso no leito e compressas quentes, associados à prescrição de analgésicos.","C":"Prescrever associação de anti-inflamatórios e relaxantes musculares e encaminhar para um\nortopedista.","D":"Recomendar retorno gradual às atividades normais e prescrever analgésicos."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-135910","number":"135910","sourceNumber":"135910","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um paciente com quadro de dor tipo cólica ureteral há aproximadamente 7 dias\napresenta-se com ultrassonografia mostrando cálculo de 1,5 cm de diâmetro em ureter terminal\nassociado a hidronefrose à montante. Qual o melhor tratamento para esse paciente?","options":{"A":"Litotripsia extra-corpórea;","B":"Desbloqueio endoscópico do ureter e ureterolitotripsia;","C":"Observação;","D":"Cirurgia aberta."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-135982","number":"135982","sourceNumber":"135982","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"É o distúrbio inflamatório mais comum do esqueleto axial. Há uma predominância pelo\nsexo masculino. O início é insidioso de lombalgia que persiste por mais de 3 meses, acompanhada\nde rigidez matinal precoce e tipicamente melhorada pelo exercício. Ocorre em 20% dos indivíduos\nHLA-B27 positivos com um membro da família afetado. Qual a patologia em questão?","options":{"A":"Espondilite anquilosante","B":"Artrite reumatoide","C":"Artrite psoriásica","D":"Artrite enteropática"},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-66945","number":"66945","sourceNumber":"66945","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Em homens mais velhos com Hiperplasia Prostática Benigna, a trabeculação da bexiga\nrepresenta:","options":{"A":"Evidência de uma bexiga neurogênica;","B":"Hipetrofia do músculo;","C":"Aumento do colágeno no detrusor;","D":"Presença de divertículos vesicais."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-37089","number":"37089","sourceNumber":"37089","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A causa mais comum de insuficiência renal no Mieloma Múltiplo é:","options":{"A":"Síndrome de Fanconi do adulto.","B":"Amiloidose.","C":"Hiperuricemia.","D":"Infiltração por células neoplásicas.","E":"Hipercalcemia."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-158734","number":"158734","sourceNumber":"158734","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente de 50 anos, sexo feminino, foi internada com quadro de anorexia, náuseas,\nvômitos, fraqueza muscular, poliúria e polidipsia. Durante a investigação, foram evidenciados os\nseguintes resultados de exames: glicosúria, aminoacidúria, bicarbonatúria, hiperfosfatúria e\nhiperuricosúria. Qual a principal etiologia dessa síndrome em adultos?","options":{"A":"Doença de Wilson.","B":"Mieloma múltiplo.","C":"Saturnismo.","D":"Amiloidose.","E":"Cistinose."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-140208","number":"140208","sourceNumber":"140208","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Em relação à dor lombar, uma das patologias que mais incapacita os indivíduos em\nidade economicamente ativa, assinale a opção CORRETA:","options":{"A":"Para paciente com dor lombar unilateral irradiada para o flanco ipsilateral, sintomas urinários,\nfebre e dor a punho-percussão lombar, a\nprincipal hipótese\n\ndiagnóstica é discite infecciosa ou séptica.","B":"A maioria dos episódios de lombalgia é limitada e tem origem muscular (lombalgia mecânica ou\nidiopática).","C":"As dores na coluna sempre estão relacionadas ao reumatismo inflamatório.","D":"As artroses da coluna vertebral atingem apenas as pessoas em idade avançada.","E":"A maioria dos pacientes com dor lombar por hérnia de disco apresentam sintomas de\ncompressão medular e dor que evolui com disfunção esfincteriana e paraparesia."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-134898","number":"134898","sourceNumber":"134898","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Luciana, 33 anos, com dor abdominal de intensidade moderada, iniciada há 3 dias,\napós ?almoço de família? e dois episódios de vômitos e disúria. Tem dor moderada à palpação\ndo abdome, com descompressão dolorosa em ambas as fossas ilíacas. O próximo passo no\natendimento é:","options":{"A":"Tomografia de abdome.","B":"Ultrassonografia transvaginal.","C":"Lavado peritonial diagnóstico.","D":"Rotina radiológica de abdome agudo."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-109787","number":"109787","sourceNumber":"109787","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A depender da forma e tamanho do cálculo urinário, os pontos de MAIOR resistência na\npassagem pelo trajeto ureteral, e que\nprovocam cólica, são:","options":{"A":"Pelve renal, trajeto sobre o músculo psoas e Junção Ureterovesical (JUV).","B":"Pelve renal, cruzamento com os vasos ilíacos e músculo psoas.","C":"Cálice renal, trajeto sobre o músculo psoas e JUV.","D":"Pelve renal, cruzamento com os vasos ilíacos e JUV."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-362481","number":"362481","sourceNumber":"362481","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Doença inflamatória crônica que acomete, preferencialmente, a coluna vertebral. É mais\nfrequente no sexo masculino, no adulto jovem e HLA-B27. Quadro clínico de dor lombar de ritmo\ninflamatório. A evolução costuma ser ascendente, acometendo progressivamente a coluna dorsal e\ncervical. Assinale a alternativa que corresponde CORRETAMENTE à doença caracterizada\nanteriormente.","options":{"A":"Hérnia discal.","B":"Artrite psoriásica.","C":"Artrite reumatoide.","D":"Espondilite anquilosante."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-286716","number":"286716","sourceNumber":"286716","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem, 30 anos, queixa-se de dor lombar que persiste há 10 meses, com rigidez local\nprolongada, que piora com o repouso, resultando em dificuldade para sair da cama de manhã e\nnecessidade de rolar de lado, tentando não flexionar ou girar a coluna vertebral para diminuir a\ndor.\nAo analisar as radiografias de coluna lombossacra e bacia é provável observar:","options":{"A":"Osteófitos e redução dos espaços discais.","B":"Sacroileíte com irregularidade no contorno das articulações sacroilíacas e esclerose óssea de\nsacro e ilíaco.","C":"Destruição de corpo vertebral com fraturas em cunha.","D":"Osteoporose com fraturas por compressão de L3?L5."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-208392","number":"208392","sourceNumber":"208392","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Os nódulos de Heberden são características de:","options":{"A":"Artropatia de Jaccoud.","B":"Artrite psoriásica.","C":"Osteoartrite.","D":"Osteoartropatia hipertrófica."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-176033","number":"176033","sourceNumber":"176033","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"São características da lombalgia de ritmo inflamatório:","options":{"A":"Dor lombar aguda que piora com a atividade física e melhora após repouso prolongado.","B":"Dor lombar crônica que piora após o repouso prolongado e melhora com a atividade física.","C":"Dor lombar crônica que piora com a atividade física e melhora após o repouso, especialmente\npela manhã.","D":"Dor lombar crônica que não varia com repouso ou atividade física."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-129720","number":"129720","sourceNumber":"129720","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um homem com 52 anos continua a ter picos febris, apesar da cateterização\nsuprapúbica da bexiga e 36 horas de\ntratamento com antibióticos intravenosos de amplo espectro.\nA ultrassonografia transretal confirma um grande abscesso prostático. Qual é o melhor passo a\nseguir?","options":{"A":"Drenagem transretal.","B":"Drenagem transuretral.","C":"Aspiração com agulha percutânea.","D":"Aspiração com agulha transretal."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-129722","number":"129722","sourceNumber":"129722","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Qual o tratamento padrão ouro para cálculos coraliformes em adultos?","options":{"A":"Ureterorenoscopia flexível com litotripsia a laser.","B":"Pielolitotomia ampliada com múltiplas nefrotomias radiais.","C":"Nefrolitotomia anatrófica.","D":"Nefrolitotomia percutânea com litotripsia ultrassônica."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-108011","number":"108011","sourceNumber":"108011","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"São achados radiológicos da osteoartrite: I. Osteófitos; II. Erosões; III. Cistos\nsubcondrais; IV. Esclerose do osso subcondral.\nCom relação às afirmativas acima, é CORRETO\nafirmar que: (VER IMAGEM)","options":{"A":"Somente as afirmativas I, II e III são corretas.","B":"Somente as afirmativas II, III e IV são corretas.","C":"Somente as afirmativas I, III e IV são corretas.","D":"Somente as afirmativas I, II e IV são corretas."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":["question_bank/media/medcurso/med-cirurgia-med-cir-07/108011.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-81041","number":"81041","sourceNumber":"81041","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente do sexo masculino vem ao pronto atendimento queixando-se de dor\nabdominal intensa, tipo cólica, de início\nsúbito, em flanco direito e fossa ilíaca direita, irradiada para\na hemibolsa testicular direita. Não há sinais de irritação peritoneal. O exame de urina (EAS) revela\nhematúria microscópica, porém a Ultrassom (USG) abdominal não revelou alterações. Qual o\npróximo passo na investigação deste paciente e sua provável abordagem terapêutica?","options":{"A":"Tomografia computadorizada helicoidal; ureterolitotripsia endoscópica.","B":"Tomografia computadorizada; nefrectomia direita videolaparoscópica.","C":"Cistoscopia; antibioticoterapia.","D":"Urografia excretora; nefrectomia aberta.","E":"Radiografia simples de abdome; hidratação venosa e antiespasmódicos."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-81924","number":"81924","sourceNumber":"81924","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"O método de imagem mais sensível para o diagnóstico do abscesso renal é:","options":{"A":"A cintilografia com índio","B":"A cintilografia com gálio","C":"A urografia excretora","D":"A ultrassonografia","E":"A tomografia computadorizada"},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-60822","number":"60822","sourceNumber":"60822","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Assinale a alternativa CORRETA:","options":{"A":"Hipomagnesiúria é fator dificultador de litogênese.","B":"Hipernatriúria não é uma alteração metabólica litogênica.","C":"Hiperfosfatúria não é uma alteração metabólica lisogênica.","D":"Todo paciente com hiperuricosúria terá cálculo de ácido úrico.","E":"Medidas dietéticas são importantes para prevenir recidivas de cálculo renal."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-60827","number":"60827","sourceNumber":"60827","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Quanto às espondiloartrites, é CORRETO afirmar:","options":{"A":"Não existe um marcador genético.","B":"O acometimento ocular é raro, principalmente os casos de uveíte.","C":"No início da doença, o paciente costuma queixar-se de lombalgia tipo mecânica.","D":"Os anti-inflamatórios não hormonais devem ser utilizados desde o início do tratamento.","E":"O acometimento articular periférico cursa com oligoartrite, tendendo a poupar as ênteses."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-60918","number":"60918","sourceNumber":"60918","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A causa mais frequente de sintomas do trato urinário baixo nos homens idosos deve-se\nà (ao):","options":{"A":"Litíase vesical.","B":"Bexiga neurogênica.","C":"Carcinoma de bexiga.","D":"Contratura do colo vesical.","E":"Hiperplasia benigna da próstata."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-61523","number":"61523","sourceNumber":"61523","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Qual dos estudos a seguir substituiu a urografia excretora na avaliação dos cálculos\nrenais e atualmente é considerada o padrão-ouro neste âmbito?","options":{"A":"O raio X simples de abdome.","B":"A cintilografia renal.","C":"A tomografia de rins e vias urinárias sem contraste.","D":"A ultrassonografia de rins e vias urinárias.","E":"A ressonância magnética dos rins e vias urinárias."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-7487","number":"7487","sourceNumber":"7487","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"O tabagismo está presente na carcinogênese de vários tumores. Nas sequências\nabaixo qual a que contém apenas órgão/sedes em\nque o fumo é fator determinante no\naparecimento de canceres?","options":{"A":"Colo do útero, vesícula, pâncreas, pulmão, rins e bexiga.","B":"Boca, endométrio, pulmão, mama, estômago e intestino.","C":"Boca, esôfago, pâncreas, pulmão, rins e bexiga.","D":"Colo do útero, endométrio, fígado, vesícula biliar, faringe e pulmão.","E":"Todos os acima têm relação com o tabagismo."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-18061","number":"18061","sourceNumber":"18061","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Com relação aos pacientes com síndrome de Gardner e Peutz-Jeghers, é incorreto\nafirmar:","options":{"A":"Apresentam pré-disposição para câncer de cólon.","B":"Não estão associados à neoplasia de pâncreas.","C":"Devem ser submetidos a exames endoscópicos.","D":"Podem apresentar como sintomas dores abdominais e mudança de hábito alimentar.","E":"Podem cursar com sangramento digestivo."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-283849","number":"283849","sourceNumber":"283849","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Os sinais de alarme (red flags) na dor lombar aguda indicam a necessidade de\ninvestigação adicional com exames de imagem específicos. A alternativa que contém um achado\nque é considerado um dos sinais de alarme é","options":{"A":"tabagismo.","B":"cardiopatia.","C":"teste Phalen positivo.","D":"uso crônico de corticosteroides.","E":"uso crônico de anti-inflamatórios não hormonais."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-259765","number":"259765","sourceNumber":"259765","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente masculino, 55 anos, comparece à demanda espontânea com queixa de dor\nlombar iniciada há 1 semana durante a qual\nmanteve repouso relativo, pois já tinha passado por\ncrises semelhantes, mas que resolviam apenas com repouso e uso de relaxantes musculares. No\nentanto, dessa vez, resolveu buscar atendimento, pois além da persistência da dor tem sentido\ndormência na perna direita. Nega alterações urinárias ou intestinais ou dormência perineal. Ao\nexame, apresenta Lasègue positivo à direita e diminuição da força de dorsiflexão do pé direito. Qual\na conduta indicada nesse caso?","options":{"A":"Fisioterapia e retorno em 3 meses.","B":"Encaminhar para serviço de emergência.","C":"Anti-inflamatório oral e retorno em 1 semana.","D":"Corticoide de depósito e retorno em 1 mês."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-234007","number":"234007","sourceNumber":"234007","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente, sexo masculino, 55 anos, portador de lombalgia cro?nica meca?nica\ninespeci?fica, ha? dois anos, com episo?dios\npouco frequentes de piora intermitente da dor.\nOntem, compareceu a? UPA com dor intensa, em choque, e pontadas (EVN10 de 10) na regia?o\nlombar com irradiac?a?o para ambas as pernas que apareceu apo?s levantamento de um peso no\ntrabalho. Nega trauma. Foi prescrito analge?sico sem melhora significativa e retornou para casa.\n\nHoje, acordou com retorno da intensidade da dor em 10, queixando-se de impossibilidade de andar\ne perda da contine?ncia urina?ria. Tem\nhisto?rico de transtorno depressivo grave tratado ha? dois\nanos. Atualmente sem medicac?o?es. Foi asma?tico e fez utilizac?a?o de corticoides por via oral,\ncronicamente, por cerca de 15 anos. Ao exame fi?sico, apresenta-se imo?vel no leito, intensa dor\na? mi?nima mobilizac?a?o, forc?a difi?cil de quantificar (pela presenc?a de dor intensa),\nsensibilidade alterada em territo?rio de L4?L5 e L5?S1, reflexos patelar e aquileu abolidos\nbilateralmente. Toque retal sugere hipotonia esfincteriana. Lasègue cla?ssico positivo\nbilateralmente. LEGENDA: EVN: Escala Visual Nume?rica de dor. Qual a conduta mais apropriada\npara o caso?","options":{"A":"Solicitar, imediatamente, transfere?ncia regulada para servic?o ciru?rgico tercia?rio\nespecializado.","B":"Solicitar ressona?ncia magne?tica de coluna lombar, analgesia e manter na observac?a?o da\nUPA.","C":"Solicitar PSA, PCR, tomografia computadorizada e encaminhar para ambulato?rio especializado.","D":"Solicitar ressona?ncia magne?tica de coluna lombar e encaminhar para ambulato?rio\nespecializado."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-234037","number":"234037","sourceNumber":"234037","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente, 72 anos, sexo masculino, comparece ao ambulatório de Clínica Médica com\nqueixa de dores ósseas difusas, particularmente na coluna. Ao exame físico, apresenta-se algo\nhipocorado e com fácies de dor. Traz alguns exames laboratoriais: hemoglobina 11,2 g/dl (VR:\n13?16 g/dl); cálcio iônico 1,5 mmol/L (VR: 1,15?1,32 mmol/L); creatinina 1,6 mg/dl (VR: 0,8?1,2\nmg/dl); fosfatase alcalina 64 U/L (VR: 50?200 U/L), além de radiografias da coluna evidenciando\nlesões osteolíticas difusas. LEGENDA: VR: Valor de Referência. Considerando a principal hipótese\ndiagnóstica, qual dos exames a seguir deve ser solicitado?","options":{"A":"PSA total.","B":"Cintilografia óssea.","C":"Densitometria mineral óssea.","D":"Eletroforese de proteínas séricas."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-172976","number":"172976","sourceNumber":"172976","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente do sexo feminino, 45 anos, trabalha como empregada doméstica, queixa-se\nde dor lombar crônica, de caráter mecânico,\nsem sinais de alarme, com exacerbação há 02\nsemanas. Relaciona a dor ao trabalho. Ao exame físico, apresenta sobrepeso, dor difusa à\npalpação da região lombar paravertebral sem irradiação. Ausência de pontos-gatilhos. Restante do\nexame físico sem alterações. Além da perda de peso, o que deve constar no plano terapêutico da\npaciente?","options":{"A":"Prescrição de analgésico opioides.","B":"Realização de exercício físico aeróbico e alongamento.","C":"Prescrição de antidepressivos por pelo menos 6 meses.","D":"Afastamento das atividades laborais até melhora do quadro álgico."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-102168","number":"102168","sourceNumber":"102168","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Eugênia, 56 anos de idade, procura seu Médico de Família por estar sofrendo dores em\nseus joelhos. Essa dor é mais frequente ao\nacordar e/ou quando fica algum tempo sentada e que\ngeralmente dura entre 20 e 25 minutos. Ao exame físico, ela mede 162 cm e pesa 80 kg. Os\njoelhos tem diminuição de mobilidade articular e sem sinais de flogose, mas você observa atrofia do\nquadríceps femoral. Ela traz um Raio-X realizado que o médico da UPA solicitou. Qual é a melhor\nopção para o tratamento farmacológico inicial dessa paciente? (VER IMAGEM).","options":{"A":"Anti-TNF via oral.","B":"Corticosteroides via oral.","C":"Salicilato em baixas doses.","D":"Acetaminofeno em altas doses."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":["question_bank/media/medcurso/med-cirurgia-med-cir-07/102168.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-81287","number":"81287","sourceNumber":"81287","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem de 65 anos, diabético tipo I, apresenta história de piora da lombalgia que vem\ntendo há 06 meses. A dor se inicia ao\ndeambular, com irradiação para ambas as pernas e nádegas,\nexacerbada também durante a ortostase prolongada. Relata que a dor é aliviada quando sentado\nou inclinando a coluna para frente. Sinal de Lasègue negativo. Baseando-se nesse conjunto de\ndados, o diagnóstico mais provável e o exame subsidiário recomendado para investigação\ndiagnóstica são:","options":{"A":"Espondiloartrite; HLA B27.","B":"Hérnia discal; tomografia axial computadorizada.","C":"Fratura patológica dos corpos vertebrais; densitometria óssea.","D":"Estenose do canal vertebral lombar; ressonância magnética."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-65742","number":"65742","sourceNumber":"65742","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Mulher de 50 anos tem história de fraqueza, lombalgia e edema generalizado nos\núltimos três meses. Ao exame físico,\napresenta edema de membros inferiores (++/4+). Os exames\niniciais mostram: anemia; hipercalcemia = 12 mg/dl; hipoalbuminemia = 2,0 g/dl; hiperuricemia = 11\nmg/dl; creatinina = 1,3 mg/dl. Sumário de urina: densidade 2015, proteína (+++/4+). Raios X da\ncoluna e crânio: lesões ósseas líticas em saca-bocados. Ultrassonografia renal: rins de tamanhos\naumentados sem anormalidades morfológicas. Assinale a alternativa que melhor traduz o\ncomprometimento renal da paciente:","options":{"A":"Nefropatia glomerular por depósitos de sais de urato de sódio.","B":"Nefropatia tubular secundária à produção excessiva de cadeias leves.","C":"Nefropatia glomerular por lesão mínima secundária à patologia de base.","D":"Nefropatia tubular por hipercalcemia com distúrbio da concentração urinária.","E":"Nefropatia glomerular por acúmulo de cadeias leves monoclonais circulantes."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-51281","number":"51281","sourceNumber":"51281","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem de 67 anos consultou com seu médico de família. Ao realizar o toque retal, o\nmédico observou uma próstata aumentada, tensa e sem sulco mediano. Posterior ultrassonografia\nabdominal mostrou o aumento da próstata fazendo protrusão no interior da bexiga e trabeculação\nvesical. Qual a hipótese diagnóstica mais provável?","options":{"A":"Hiperplasia de próstata com obstrução urinária baixa.","B":"Hiperplasia de próstata sem obstrução urinária baixa.","C":"Carcinoma de próstata com obstrução urinária baixa.","D":"Hiperplasia de próstata e prostatismo sem obstrução urinária baixa."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-30860","number":"30860","sourceNumber":"30860","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Qual a principal causa etiológica de lombalgia em trabalhadores em idade produtiva?","options":{"A":"Fratura traumática.","B":"Osteoartrose.","C":"Hérnia de disco.","D":"Espondilolistese.","E":"Musculoligamentar."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-37047","number":"37047","sourceNumber":"37047","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um homem de 37 anos, trabalhador da construção civil, apresenta dor lombar há 6\nmeses, recorrente. Qual a causa mais provável?","options":{"A":"Espondilite anquilosante.","B":"Osteoartrose.","C":"Hérnia de disco.","D":"Lesão musculoligamentar."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-7284","number":"7284","sourceNumber":"7284","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A mais antiga associação entre risco ocupacional por exposição a um agente\ncancerígeno foi assinalada por Pott que estudou o:","options":{"A":"câncer de pulmão em trabalhadores de minas de urânio.","B":"câncer de saco escrotal em limpadores de chaminés.","C":"câncer de bexiga em operários de indústrias de anilina.","D":"mesotelioma nos expostos ao asbesto.","E":"câncer cutâneo com a exposição a raios-X."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-7271","number":"7271","sourceNumber":"7271","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A primeira medida a ser adotada diante de um paciente com hipercalcemia secundária\nao câncer espinocelular de pulmão é:","options":{"A":"zoledronato 4 mg IV.","B":"calcitonina 200 unidades S.C., de 8/8h.","C":"furosemida 20 mg IV.","D":"expansão volêmica com soro fisiológico 0,9%.","E":"quimioterapia antineoplásica baseada em cisplatina."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-6909","number":"6909","sourceNumber":"6909","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A maioria dos tumores benignos do fígado são assintomáticos e são achados\nincidentais em ultrassonografia de abdome.\nPara diagnóstico diferencial de tumores sólidos, faz-se\nnecessário a realização de exames contrastados como tomografia computadorizada e ressonância\nmagnética. Um nódulo de 5 cm com hipercaptação de contraste na fase arterial e com uma cicatriz\ncentral em uma mulher de 40 anos é altamente sugestivo de:","options":{"A":"Adenoma hepático.","B":"Hemangioma.","C":"Hiperplasia nodular focal.","D":"Carcinoma fibrolamelar.","E":"Hamartoma."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-6911","number":"6911","sourceNumber":"6911","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Sobre o câncer gástrico precoce, NÃO é correto:","options":{"A":"Pode apresentar metástase.","B":"Pode invadir a camada muscular.","C":"Corresponde a 30% dos cânceres gástricos do Japão.","D":"Pode ser curado a partir da ressecção endoscópica.","E":"Pode acometer grande extensão da mucosa do órgão."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-6971","number":"6971","sourceNumber":"6971","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente, 70 anos, tabagista, com diagnóstico de DPOC. Há dois meses vem\napresentando piora da tosse, episódios de\nhemoptise, anorexia e perda de peso. Exame físico:\nsibilos no hemitórax esquerdo. Raio-X de tórax: massa tumoral próxima ao hilo esquerdo. Foi\nsubmetido à broncoscopia com biópsia da massa. Dentre os tipos histológicos abaixo qual o mais\nprovável?","options":{"A":"Carcinoma de células escamosas.","B":"Carcinoma bronquíolo-alveolar.","C":"Carcinoma de grandes células.","D":"Tumor carcinoide.","E":"Hamartoma."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-17821","number":"17821","sourceNumber":"17821","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Durante investigação de paciente com dor torácica e tosse, identificou-se massa\nmediastinal anterior. Qual o mais provável diagnóstico?","options":{"A":"Linfoma","B":"Tumor neurogênico","C":"Tumor mesenquimal","D":"Tumor de células germinativas","E":"Timoma"},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-239278","number":"239278","sourceNumber":"239278","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um paciente de 75 anos de idade procurou atendimento por diminuição do volume\nurinário e intolerância aos esforços,\nassociada a dor torácica ventilatório-dependente e a dor lombar\nde forte intensidade. Realizou exames de laboratório, que evidenciaram: hemoglobina = 8,6 g/dl,\nhematócrito = 25%, leucócitos = 6.600/mm3, sem particularidades no diferencial, plaquetas = 190\nmil/mm3, creatinina = 4,51 mg/dl, potássio = 6,3 mEq/L, cálcio sérico corrigido = 13 mg/dl, ureia =\n109 mg/dl, reserva alcalina = 12 U/L. Ao exame físico, o paciente encontrava-se em regular estado\ngeral, hipocorado, com presença de sopro sistodiastólico 2+/4+, murmúrio vesicular reduzido em\n1/3 inferior direito, edema em membros inferiores 3+/4+, abdome sem particularidades e\n\npercussão-punho-lombar (PPL) negativo, PA = 180 mmHg X 90 mmHg, FC = 97 bpm, SatO2 = 92%\nem ar ambiente. Considerando esse caso\nclínico e os conhecimentos médicos correlatos, julgue o\nitem a seguir. A lombalgia, nesse paciente, provavelmente se deve a lesões ósseas de\ncaracterísticas líticas, associadas à hipótese diagnóstica principal.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-135033","number":"135033","sourceNumber":"135033","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"No próximo item é apresentado um caso clínico seguido de uma assertiva a ser julgada.\nUm paciente foi admitido no pronto-socorro\npor apresentar dor lombar intensa, náuseas e vômitos.\nNo exame físico, não foram detectados sinais de irritação peritoneal no paciente. Os exames\nlaboratoriais revelaram EAS com hematúria +/4+ e leucograma normal. A tomografia\ncomputadorizada da região abdominal do paciente mostrou cálculo renal de 4 mm no terço superior\ndo ureter direito, com discreta hidronefrose à direita. Nesse caso, seria correto submeter o\npaciente\na hidratação vigorosa, analgesia, acompanhamento laboratorial e realização de exames de imagem\nseriados para avaliar alteração da hidronefrose.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-79646","number":"79646","sourceNumber":"79646","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem, 45 anos, apresenta intenso quadro de dor lombar com irradiação para a região\nescrotal. Com base no sintoma descrito, assinale a alternativa que apresenta o exame mais\nadequado a ser realizado.","options":{"A":"Hemograma.","B":"Enzimas hepáticas.","C":"Amilase sérica.","D":"Raio X de abdômen.","E":"Sedimentação urinária."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-88623","number":"88623","sourceNumber":"88623","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"No que se refere à leucemia, à osteoporose pós-menopáusica e à litíase renal, julgue o\nitem a seguir. A litíase renal pode estar associada às situações de aumento da excreção urinária de\nalgumas substâncias, como na hipercalciúria e na hiperoxalúria, ou às situações de diminuição da\nexcreção renal de outras substâncias, como na hipocitratúria.","options":{"A":"CERTO.","B":"ERRADO."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-64708","number":"64708","sourceNumber":"64708","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem, 28 anos, saudável, desenvolveu subitamente dor abdominal, predominante em\nflancos, com irradiação para região inguinal, associado à hematúria, sem febre ou disúria. O exame\nfísico não apresentou alterações. Na análise de urina, foi evidenciado um pH de 7; densidade de\n1,015; 1+ de hematúria e ausência de proteínas; glicose ou cetona. O paciente, após alguns dias,\neliminou um cálculo com 0,3 cm de diâmetro que, após análise química, evidenciou ser de oxalato\nde cálcio. Com base nisso, assinale a alternativa que apresenta a doença de base, causadora do\ncálculo renal, que possui maior possibilidade de estar presente neste paciente.","options":{"A":"Cistite aguda.","B":"Diabetes mellitus.","C":"Gota.","D":"Hiperparatireoidismo primário.","E":"Hipercalciúria idiopática."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-7543","number":"7543","sourceNumber":"7543","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um paciente de 40 anos de idade vem apresentando confusão mental ocasional,\nsudorese profusa e palpitações nas últimas oito\nsemanas. Avaliado pelo seu médico que solicitou\nglicose plasmática de jejum (resultado 45 mg/dl - VN 70 a 99 mg/dl) e peptídeo C (elevado). Em\nrelação a essa situação hipotética, assinale a alternativa que contém o diagnóstico mais provável.","options":{"A":"Insuficiência hepática.","B":"Baixa ingestão alimentar.","C":"Etilismo crônico.","D":"Insulinoma.","E":"Sintomas autônomos sem hipoglicemia verdadeira."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-352381","number":"352381","sourceNumber":"352381","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um homem de 57 anos de idade com histórico de Doença Pulmonar Obstrutiva Crônica\ne hipertensão arterial bem controlada com\nlosartana 100 mg por dia, e que deixou de fumar há 2\nanos após 50 anos de tabagismo (50 maços-ano), apresenta-se no ambulatório com uma queixa de\ndor lombar crônica persistente há 2 anos. Ele relata ter sofrido uma queda da própria altura durante\no banho, que resultou em uma dor intensa e súbita, acompanhada por uma limitação significativa\ndos movimentos. Isso o levou a se afastar do trabalho por um período de 7 dias. Embora tenha\nretomado suas atividades laborais, continua a experimentar dor lombar constante que, por vezes, o\nacorda durante a noite. O paciente menciona ter buscado assistência em múltiplos\n\nprontos-socorros, onde recebeu apenas tratamento sintomático. Ele faz uso de anti-inflamatórios,\nque proporcionam algum alívio, mas não resolvem o\nquadro. Além disso, recorre ao tramadol\nesporadicamente. Embora relate ocasional tosse, foi sua significativa piora na dor lombar na última\nsemana que o levou a procurar atendimento médico particular. Nesse atendimento particular, foram\nsolicitados exames complementares, um de imagem e um laboratorial, cujos resultados estão\napresentados abaixo. Considerando o quadro clínico exposto bem como os exames\ncomplementares e seus diagnósticos diferenciais, julgue o item a seguir. Um dos diagnósticos\ndiferenciais para o caso é câncer com metástase óssea.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-352382","number":"352382","sourceNumber":"352382","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um homem de 57 anos de idade com histórico de Doença Pulmonar Obstrutiva Crônica\ne hipertensão arterial bem controlada com\nlosartana 100 mg por dia, e que deixou de fumar há 2\nanos após 50 anos de tabagismo (50 maços-ano), apresenta-se no ambulatório com uma queixa de\ndor lombar crônica persistente há 2 anos. Ele relata ter sofrido uma queda da própria altura durante\no banho, que resultou em uma dor intensa e súbita, acompanhada por uma limitação significativa\ndos movimentos. Isso o levou a se afastar do trabalho por um período de 7 dias. Embora tenha\nretomado suas atividades laborais, continua a experimentar dor lombar constante que, por vezes, o\nacorda durante a noite. O paciente menciona ter buscado assistência em múltiplos\n\nprontos-socorros, onde recebeu apenas tratamento sintomático. Ele faz uso de anti-inflamatórios,\nque proporcionam algum alívio, mas não resolvem o\nquadro. Além disso, recorre ao tramadol\nesporadicamente. Embora relate ocasional tosse, foi sua significativa piora na dor lombar na última\nsemana que o levou a procurar atendimento médico particular. Nesse atendimento particular, foram\nsolicitados exames complementares, um de imagem e um laboratorial, cujos resultados estão\napresentados abaixo. Considerando o quadro clínico exposto bem como os exames\ncomplementares e seus diagnósticos diferenciais, julgue o item a seguir. O exame laboratorial\nclássico acima é eletroforese com típico componente monoclonal em região gama.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-352404","number":"352404","sourceNumber":"352404","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um homem de 57 anos de idade com histórico de Doença Pulmonar Obstrutiva Crônica\ne hipertensão arterial bem controlada com\nlosartana 100 mg por dia, e que deixou de fumar há 2\nanos após 50 anos de tabagismo (50 maços-ano), apresenta-se no ambulatório com uma queixa de\ndor lombar crônica persistente há 2 anos. Ele relata ter sofrido uma queda da própria altura durante\no banho, que resultou em uma dor intensa e súbita, acompanhada por uma limitação significativa\ndos movimentos. Isso o levou a se afastar do trabalho por um período de 7 dias. Embora tenha\nretomado suas atividades laborais, continua a experimentar dor lombar constante que, por vezes, o\nacorda durante a noite. O paciente menciona ter buscado assistência em múltiplos\n\nprontos-socorros, onde recebeu apenas tratamento sintomático. Ele faz uso de anti-inflamatórios,\nque proporcionam algum alívio, mas não resolvem o\nquadro. Além disso, recorre ao tramadol\nesporadicamente. Embora relate ocasional tosse, foi sua significativa piora na dor lombar na última\nsemana que o levou a procurar atendimento médico particular. Nesse atendimento particular, foram\nsolicitados exames complementares, um de imagem e um laboratorial, cujos resultados estão\napresentados abaixo. Considerando o quadro clínico exposto bem como os exames\ncomplementares e seus diagnósticos diferenciais, julgue o item a seguir. O paciente em questão\npode apresentar uma emergência que curse como seguinte achado eletrocardiográfico (DII longo\nem 10mm/mV; 25mm/s):","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-352403","number":"352403","sourceNumber":"352403","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um homem de 57 anos de idade com histórico de Doença Pulmonar Obstrutiva Crônica\ne hipertensão arterial bem controlada com\nlosartana 100 mg por dia, e que deixou de fumar há 2\nanos após 50 anos de tabagismo (50 maços-ano), apresenta-se no ambulatório com uma queixa de\ndor lombar crônica persistente há 2 anos. Ele relata ter sofrido uma queda da própria altura durante\no banho, que resultou em uma dor intensa e súbita, acompanhada por uma limitação significativa\ndos movimentos. Isso o levou a se afastar do trabalho por um período de 7 dias. Embora tenha\nretomado suas atividades laborais, continua a experimentar dor lombar constante que, por vezes, o\nacorda durante a noite. O paciente menciona ter buscado assistência em múltiplos\n\nprontos-socorros, onde recebeu apenas tratamento sintomático. Ele faz uso de anti-inflamatórios,\nque proporcionam algum alívio, mas não resolvem o\nquadro. Além disso, recorre ao tramadol\nesporadicamente. Embora relate ocasional tosse, foi sua significativa piora na dor lombar na última\nsemana que o levou a procurar atendimento médico particular. Nesse atendimento particular, foram\nsolicitados exames complementares, um de imagem e um laboratorial, cujos resultados estão\napresentados abaixo. Considerando o quadro clínico exposto bem como os exames\ncomplementares e seus diagnósticos diferenciais, julgue o item a seguir. Exames como\nimunofixação de proteínas séricas e de urinas de 24 horas bem como dosagem de imunoglobulinas\npodem auxiliar no diagnóstico do quadro em tela.","options":{"A":"CERTO","B":"ERRADO"},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-307105","number":"307105","sourceNumber":"307105","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um paciente de 64 anos de idade vem apresentando dor dorsal, com cefaleia, turvação\nvisual, vertigem, zumbido e dispneia. Quando\nsolicitados exames, observaram-se uma anemia\nnormocrômica e normocítica, trombopenia e leucopenia. Na biópsia de medula óssea, realizada\npela hematologia, foram constatados mais de 10% de plasmócitos clonais; proteína M elevada no\nsoro, além de hipercalcemia. Na tomografia de crânio, há relato de lesões em saca-bocado em\nossos do crânio. Nesse caso, o diagnóstico mais provável é:","options":{"A":"Gamopatia monoclonal.","B":"Leucemia de células plasmáticas.","C":"Amiloidose primária.","D":"Plasmocitomas isolados medulares.","E":"Mieloma múltiplo."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-274594","number":"274594","sourceNumber":"274594","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Durante o tratamento farmacológico, o médico pode vir a prescrever analgésicos que\nsão utilizados para reduzir e aliviar dores.\nConsiderando os dois grupos principais de analgésicos e\nsuas subdivisões, quanto aos opioides fortes, é CORRETO afirmar:","options":{"A":"Incluem somente a Morfina e a Fentanila.","B":"O Sulfato e o Cloridrato de Morfina podem ser utilizados por VO, retal, IM, SC, IV, espinal ou\nintraventricular.","C":"Estabilizada a dose, a Morfina deve ser substituída pela deliberação controlada ou por fármacos\nde ação curta, reservando-se a Morfina de ação\nprolongada.","D":"A Metadona pode ser empregada no tratamento da dor aguda no doente com câncer e não da\ndor não decorrente de neoplasia."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-274597","number":"274597","sourceNumber":"274597","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Considerando os vários exames complementares que ajudam na elucidação e\ndiagnóstico da dor do paciente, o tipo de\nexame complementar que permite melhor visualização de\ntodas as estruturas do tronco e dos elementos que compõem a coluna vertebral é:","options":{"A":"Ressonância magnética.","B":"Tomografia computadorizada.","C":"Radiografia óssea.","D":"Exame ultrassonográfico."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-263374","number":"263374","sourceNumber":"263374","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um paciente com 47 anos de idade, motorista de ônibus, comparece ao ambulatório da\natenção secundária relatando início de dor lombar baixa há 2 semanas, a qual se irradia para\nmembros inferiores. Ele nega ter sofrido queda e/ou trauma local. Devido à intensidade da dor,\nprocurou atendimento em emergência na época, tendo recebido medicação endovenosa e\norientação para acompanhamento ambulatorial para investigação. O paciente afirma que possui dor\nainda incapacitante, a qual piora ao se sentar e ao ficar em pé, mas que melhora com o repouso.\n\nEssa dor possui irradiação pela região posterior da coxa e perna, chegando até a planta do pé à\ndireita. Também relata diminuição da\nsensibilidade no dorso do pé direito. Ao realizar exame físico,\napresentou teste de elevação do membro inferior estendido positivo à direita quando realizando a\n40 graus, além de hipoestesia em região de dorso do pé direito, com reflexos sem alterações e sem\nperda de força muscular. A conduta imediata adequada para o caso é","options":{"A":"receitar opioide a curto prazo e orientar o paciente a retornar ao trabalho conforme intensidade\nda dor.","B":"prescrever anti-inflamatórios, relaxante muscular e início de exercícios para fortalecimento\nlombar.","C":"encaminhar o paciente para cirurgia imediata para descompressão.","D":"receitar corticosteroide sistêmico e repouso por 14 dias."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-263428","number":"263428","sourceNumber":"263428","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um homem com 64 anos de idade é encaminhado ao ambulatório para investigação de\nanemia, detectada nas últimas semanas durante investigação de quadro de fadiga, cansaço e\ndores ósseas. Ao exame físico, paciente apresenta-se em regular estado geral, hipocorado, não\nhavendo outras anormalidades. Os exames complementares realizados recentemente revelaram o\nseguinte: hemoglobina = 10g/dl (valor de referência: 13 a 17 g/dl); hematócrito = 28% (valor de\nreferência: 40 a 52%); volume corpuscular médio = 88 fl (valor de referência: 80 a 100 fl);\nleucometria e contagem plaquetária normais; ureia = 60 mg/dl (valor de referência: 20 a 40 mg/dl);\ncreatinina = 1,3 mg/dL (valor de referência: 0,7 a 1,2 mg/dl); e cálcio sérico = 11,8 mg/dl (valor\nde\nreferência: 8,0 a 10,5 mg/dl). Os exames laboratoriais realizados no dia do atendimento\napresentam: ureia = 88 mg/dl; creatinina = 2,4 mg/dL e cálcio sérico = 12,0 mg/dl; proteinograma\nsérico: albumina = 3,1 g/dl (valor de referência: 3,5 a 5,5 g/dl), e globulina = 8,2 g/dl (valor de\nreferência: 1,5 a 2,5 g/dl). Nesse caso, o diagnóstico, a partir dos dados clínicos e\nlaboratoriais, é\nde:","options":{"A":"Gamopatia monoclonal associada a mieloma múltiplo.","B":"Gamopatia policlonal associada a síndrome hemolítico-urêmica.","C":"Inversão albumina/globulina por cirrose hepática complicada com síndrome hepatorrenal.","D":"Hipoalbuminemia decorrente de síndrome nefrótica por nefropatia membranosa associada a\nsíndrome hiper-IgG."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-111289","number":"111289","sourceNumber":"111289","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um paciente de 65 anos de idade, sexo masculino, apresenta-se queixando-se de dor\nem cólica, iniciando-se em flanco direito e\nirradiando-se para fossa ilíaca direita e bolsa escrotal\nesquerda, de início há 2 horas, com aumento contínuo de intensidade. Nega febre. Refere disúria\ndiscreta e urina de cor escura e odor característico. Não tem antecedentes familiares relevantes e,\ncomo antecedente pessoal importante, refere ter tido elevação de ácido úrico constatado em exame\nde rotina, mas não ter tomado nenhuma providência quanto a isso. Eventualmente, apresenta\nartralgia e já teve artrite em hálux esquerdo, não sabendo informar em que consistiu o tratamento,\nmas houve regressão do quadro. O exame físico revela sinal de Giordano positivo à direita, fáscie\nde dor intensa, gemente, consciente, anictérico. PA = 140/90 mmHg e FC = FP = 110 bpm. Sem\noutros achados. Com relação ao caso apresentado, os exames complementares mais bem\nindicados são:","options":{"A":"EAS e hemograma completo, somente.","B":"EAS, urocultura e urografia excretora.","C":"EAS e urocultura, somente.","D":"EAS, hemograma completo e tomografia\ncomputadorizada.","E":"EAS, hemograma completo e ressonância magnética."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-75564","number":"75564","sourceNumber":"75564","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem com 38 anos de idade, pedreiro, vem à Unidade Básica de Saúde com relato\nde dor lombar contínua há uma semana, aos\nesforços acentuados, a qual não causa limitação de\nsuas atividades diárias. Informa, com bastante firmeza, diminuição da sensibilidade na face lateral\nda perna esquerda. Ao exame físico apresenta dor à digitopressão lombar com teste de Lasègue\nnegativo bilateralmente. A conduta a ser adotada na sequência deve ser:","options":{"A":"prescrever anti-inflamatórios não esteróides e fisioterapia.","B":"solicitar ressonância nuclear magnética da coluna vertebral.","C":"prescrever infiltração com corticoesteroides.","D":"afastar o paciente do trabalho por 30 dias.","E":"solicitar cintilografia de coluna vertebral."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-283886","number":"283886","sourceNumber":"283886","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem de 65 anos procura o consultório médico referindo progressiva fadiga nos\núltimos 6 meses. Traz estes exames realizados há 30 dias: hemoglobina: 9 g/dl; creatinina: 2,5\nmg/dl; eletroforese de proteínas: Qual o provável diagnóstico?","options":{"A":"Gamopatia monoclonal de significado incerto (MIGUS).","B":"Macroglobulinemia de Waldenstrom.","C":"Mieloma múltiplo.","D":"Amiloidose.","E":"Sepse urinária."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-220286","number":"220286","sourceNumber":"220286","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Mulher de 55 anos se queixa de dor no joelho direito ao subir e descer as escadas da\nsua casa, principalmente no final do dia. O\nsintoma que ocorreu há 1 ano, tem se tornado mais\nintenso e frequente e a faz evitar escadarias. Relata dificuldade ao iniciar movimentos após\nperíodos de inatividade que melhora à medida que insiste no movimento. Nega calor, rubor ou\nedema nessa articulação ou outras quaisquer. Ao exame físico, há crepitações e limitação dos\nmovimentos ativos e passivos no joelho direito, além de derrame articular (sinal da tecla presente).\nEm relação a essa doença, assinale a alternativa CORRETA:","options":{"A":"Os joelhos, os cotovelos, os punhos, os ombros e os tornozelos são as articulações mais\nacometidas.","B":"A doença não cursa com rigidez matinal nas articulações acometidas.","C":"A instabilidade nos movimentos articulares por causa de atrofia muscular pode ocorrer.","D":"Os sintomas e os achados radiográficos guardam correlação clínico-radiológica."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-188005","number":"188005","sourceNumber":"188005","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem, 70 anos, procura o ambulatório de clínica médica com queixa de cansaço e\ndor lombar há 6 meses. Antecedentes pessoais: Hipertensão arterial com uso regular das\nmedicações. Trouxe exames complementares: Hemograma: Hemoglobina: 8,0 g/dL / VCM 83 /\nLeucócitos: 5.200/mm3 (Bastonestes 0%, Segmentados 67%, Eosinófilos 3%, Basófilos 0%,\n\nLinfócitos: 28%, Monócitos: 2%)) Plaquetas 250.000/mm3. Ureia: 120 mg/dL. Creatinina: 6,8 mg/dL,\nSódio: 140 mEq/L, Potássio: 4,2 mEq/L, Cálcio iônico: 13,1 mg/dL. Urina tipo 1: normal. Radiografia\nde coluna lombar: lesões líticas de L1 a L4. Que exame complementar deverá ser solicitado na\nsequência para definição diagnóstica?","options":{"A":"Dosagem de ferro sérico e ferritina.","B":"Eletroforese de proteínas séricas e urinária.","C":"Ressonância Magnética de coluna lombar.","D":"Eletroneuromiografia.","E":"Biópsia renal."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-188024","number":"188024","sourceNumber":"188024","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Mulher, 43 anos de idade dá entrada no pronto-socorro com dor em flanco direito de\nmoderada intensidade irradiada para fossa ilíaca direita associada a náuseas e vômitos.\n\nTemperatura axilar de 37.9°C e estável hemodinamicamente. No exame físico, apresenta defesa à\npunho-percussão lombar direita. Hemograma com leucocitose e neutrófilos com desvio. Radiografia\nsimples de abdome sugere cálculo em topografia de ureter direito confirmado com ultrassonografia.\nQual é a conduta indicada?","options":{"A":"Orientar hidratação oral vigorosa, analgesia oral e retorno ambulatorial.","B":"Antibioticoterapia intravenosa até resultado de urocultura.","C":"Antibioticoterapia intravenosa, descompressão e drenar trato urinário superior.","D":"Hidratação venosa, controle da dor e possível intervenção cirúrgica.","E":"Controle da dor e litotripsia extracorpórea na mesma internação."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-187996","number":"187996","sourceNumber":"187996","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem, 58 anos, obeso, com queixa lombociatalgia de intensidade leve a moderada\nhá 4 semanas Exame físico sem sinais de\ndéficit neurológico e com força muscular grau V nos\nmembros inferiores. Levando em consideração a principal hipótese diagnóstica qual é a conduta a\nser tomada?","options":{"A":"Perda de peso, fisioterapia, analgésicos e relaxantes musculares com reavaliação em 4\nsemanas.","B":"Solicitar ressonância magnética.","C":"Indicar cirurgia de fusão com aloenxerto ósseo e placa de titânio e parafusos.","D":"Indicar cirurgia de laminotomia.","E":"Indicar cirurgia de hemilaminectomia."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-155361","number":"155361","sourceNumber":"155361","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Em relação ao Mieloma Múltiplo (MM), assinale a alternativa CORRETA:","options":{"A":"É uma neoplasia benigna, de origem hematopoiética, caracterizada pela proliferação clonal de\nplasmócitos na medula óssea, que, na maioria dos casos, secretam proteína monoclonal detectável\nno sangue ou urina.","B":"Corresponde a aproximadamente 0,2% dos tumores malignos e a até 5% das neoplasias\nhematológicas.","C":"É mais frequente em mulheres do que em homens, e em brancos (caucasianos) do que em\nnegros.","D":"Mais de 90% dos casos ocorrem após os 50 anos, com pico de incidência no ocidente entre 60 e\n70 anos de idade.","E":"No Brasil, a doença ocorre mais tardiamente (a idade mediana dos pacientes ao diagnóstico é\nde 80 anos)"},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-111567","number":"111567","sourceNumber":"111567","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem de 69 anos é internado numa enfermaria de clínica geral. Os dados de\nanamnese mais relevantes são: prostração,\núltima evacuação há uma semana, náuseas, poliúria,\ncefaleia e dificuldade em reconhecer os familiares. À propedêutica física, observam-se: mucosas\nressecadas e descoradas, além de delirium. Os exames mostram: áreas líticas em calota craniana\ne eritrócitos em roulleaux. É provável que à biópsia de medula óssea, detecte-se aumento\nsignificativo no número de","options":{"A":"células de Reed-Sternberg.","B":"mieloblastos.","C":"linfoblastos.","D":"neutrófilos hipersegmentados.","E":"plasmócitos."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-111577","number":"111577","sourceNumber":"111577","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"São características da cólica nefrética, EXCETO:","options":{"A":"é mais comum durante a noite ou no início da manhã.","B":"a ausência de hematúria microscópica exclui o seu diagnóstico.","C":"é abrupta e afeta o paciente quase sempre em situação de repouso.","D":"é marcante a ausência de fatores de melhora ou piora","E":"apesar de intermitente, os ciclos de dor não respeitam um padrão de aparecimento."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-106460","number":"106460","sourceNumber":"106460","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente 60 anos, tabagista, deu entrada no PS apresentando quadro de retenção\nurinária. Refere história de hematúria macroscópica há 1 dia. Qual a conduta inicial?","options":{"A":"Hidratação venosa e solicitar EAS para afastar infecção urinária.","B":"Solicitar hemograma e coagulograma. Pedir parecer do urologista.","C":"Realizar sondagem vesical com sonda de 3 vias e iniciar irrigação vesical.","D":"Realizar sondagem vesical com sonda de 2 vias e solicitar PSA total.","E":"Nenhuma das alternativas acima."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-106462","number":"106462","sourceNumber":"106462","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Para o diagnóstico, na suspeita de cálculo ureteral, o melhor exame é:","options":{"A":"Ressonância magnética.","B":"Tomografia computadorizada.","C":"Radiografia simples.","D":"Ultrassonografia.","E":"Cintilografia renal."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-43999","number":"43999","sourceNumber":"43999","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente de 45 anos com dor lombar à direita há 4 meses. Nega perda de peso, febre e\nhematúria. Há 03 dias evoluiu com piora da dor e está no Pronto-Socorro. Na investigação realizou\nraio X de abdome e tórax normais; laboratorialmente apresentou hemoglobina = 12,5; leucograma =\n6500 sem desvio; plaquetas = 190.000; EAS com pH 5,0 e hematúria sem piúria com urocultura\nnegativa. Foi realizada ainda tomografia computadorizada de abdome e pelve com focos\nhiperdensos dispersos no sistema coletor renal bilateralmente, medindo em média 1,0 cm sem\nhidronefrose. Recebeu analgesia com alívio total da dor. Qual a hipótese diagnóstica e a melhor\nconduta de tratamento do cálculo?","options":{"A":"Cálculo renal de oxalato de cálcio ? litotripsia extracorpórea.","B":"Cálculo renal de estruvita ? nefrolitotripsia percutânea.","C":"Cálculo renal de fosfato de cálcio ? litotripsia extracorpórea.","D":"Cálculo renal de ácido úrico ? alcalinização da urina, aumento da diurese.","E":"Cálculo renal de oxalato de cálcio ? alcalinização da urina, aumento da diurese."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-363984","number":"363984","sourceNumber":"363984","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Qual anormalidade cromossômica no Mieloma Múltiplo é altamente sensível à ação do\ninibidor de BCL2 venetoclax?","options":{"A":"Translocação t (14; 16).","B":"Translocação t (11; 14).","C":"Ganho do cromossomo 1 (+1q).","D":"Deleção do 17p del (17p)."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-330076","number":"330076","sourceNumber":"330076","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente, 70 anos, sexo masculino, com dor articular acompanhada de alterações no\nexame físico na articulação, como edema,\ncalor, eritema, dor espontânea e derrame articular.\n\nDentre os diagnósticos abaixo, o mais apropriado é:","options":{"A":"Febre reumática.","B":"Artrite reativa.","C":"Lúpus eritematoso.","D":"Osteoartrite."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-311894","number":"311894","sourceNumber":"311894","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Mônica de 27 anos, dá entrada na emergência queixando-se de dor intensa, tipo cólica,\nacometendo região lombar direita, irradiada para flanco direito, de início súbito, há 4 horas.\n\nG3P3A0, D.U.M desconhece. Tem dislipidemia e obesidade. O exame físico revela pressão arterial\nde 100x70mmHg, frequência cardíaca de 85bpm, T.ax\n37° C. Dor à palpação de flanco direito, com\nsinal de Giordano presente à direita. O hemograma apresenta 5.630 leucócitos/mm³, 2% de\nbastonetes, Ureia 35mg/dl. EAS com 8.000 leucócitos/mL e 50.000 hemácias/mL. Foi solicitava\ntomografia de abdome que revelou cálculo de 3mm em ureter distal a 2cm da junção ureterovesical.\nApós analgesia, houve controle da dor. A conduta deve ser.","options":{"A":"indicar instalação de cateter duplo.","B":"indicar litotripsia extracorpórea por ondas de choque.","C":"iniciar terapia expulsiva medicamentosa.","D":"indicar litotripsia transureteroscópica."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-314100","number":"314100","sourceNumber":"314100","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Após obstrução do trato urinário superior, há desregulação dos canais de água de\naquaporina no túbulo proximal, alça descendente e ducto coletor, o que pode contribuir para a\npoliúria em longo prazo. Várias outras mudanças funcionais com a obstrução podem ocorrer. Na\nobstrução do trato urinário, sabe-se que","options":{"A":"a excreção de potássio após o alívio da obstrução ureteral bilateral é maior do que após a\nobstrução ureteral unilateral porque, na obstrução bilateral, há retenção de sódio, água, ureia e\noutras substâncias osmóticas e aumento do fator natriurético atrial.","B":"a recuperação da função renal após o alívio da obstrução é afetada pela duração, grau, idade do\npaciente, função renal basal, complacência do sistema coletor e infecção.","C":"a obstrução ureteral pode resultar em diminuições prolongadas na capacidade de concentração,\nalcalinização urinária e transporte de eletrólitos muito depois de a obstrução ser liberada.","D":"o crescimento renal compensatório diminui progressivamente com o aumento da idade. O rim\naumenta com o aumento de néfrons e do número de glomérulos após o nascimento."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-294255","number":"294255","sourceNumber":"294255","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A dor lombar baixa, ou lombalgia, é a maior representante das síndromes dolorosas da\ncoluna vertebral, seguida da cervicalgia. O fator que favorece ou corrobora para o aparecimento\ndessa condição clínica é:","options":{"A":"o maior nível educacional do paciente.","B":"o índice de massa corporal menor que 30 kg/m².","C":"o uso de bebidas alcoólicas.","D":"a falta de atividade física."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-294261","number":"294261","sourceNumber":"294261","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"De acordo com Matsuno et al. (1984), Brown et al. (1987), McLellan et al. (2002),\nShukla et al. (2005) e Rubenwolf et al\n(2016), por relato histórico, pode-se deduzir que a maioria\ndos megaureteres sem refluxo segue um curso benigno e se resolve espontaneamente nos\nprimeiros anos de vida). Tal constatação foi confirmada por Ranawaka e Hennayake (2013) que, a\npartir de estudo observacional prospectivo, mostrou que a resolução completa e o tempo de\nresolução foram inversamente relacionados ao diâmetro ureteral. Por outro lado, os pacientes com\ndiâmetros ureterais >10 mm eram mais propensos a complicações, como ITUs febris recorrentes,\nformação de cálculos e dor abdominal, com apenas 17% resolvendo completamente e um total de\n21% deles exigindo intervenção cirúrgica. Nesse contexto, a cirurgia no caso de megaureter\nprimário obstrutivo deve ser considerada quando os pacientes são sintomáticos e têm","options":{"A":"infecções do trato urinário recorrentes.","B":"dilatação persistente contínua na ultrassonografia.","C":"função renal diferencial <30%.","D":"diminuições significativas na função renal diferencial ?10% em exames sequenciais."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-295351","number":"295351","sourceNumber":"295351","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Os rins são pares de órgãos retroperitoneais ovoides, marrom-avermelhados, situados\nna parte posterior do abdome em cada lado da\ncoluna vertebral. Os rins estão nos músculos psoas;\nassim, os eixos longitudinais dos rins são oblíquos, com os polos superiores mais mediais e\nposteriores do que os polos inferiores. Portanto, durante o acesso renal percutâneo, o polo inferior\ndo rim encontra-se lateralmente e anteriormente em relação ao polo superior. Além disso, o aspecto\nmedial de cada rim é girado anteriormente em um ângulo de aproximadamente 30 graus. Sobre os\naspectos anatômicos do rim, sabe-se que:","options":{"A":"a fáscia de Gerota envolve o rim e a glândula adrenal em todos os aspectos, exceto\nsuperiormente, onde permanece aberta.","B":"de anterior para posterior, as estruturas hilares renais são a artéria renal, veia renal, pelve\nrenal\ne veia segmentar posterior.","C":"as áreas medulares são piramidais, localizadas mais centralmente e separadas por segmentos\ndo córtex, as colunas de Bertin.","D":"cada pirâmide renal termina lateralmente em uma papila. Cada papila é coberta por um cálice\nmenor. Um grupo de cálices menores se junta para formar um cálice principal."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-295359","number":"295359","sourceNumber":"295359","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Qual dessas doenças não faz parte do grupo de gamopatias monoclonais?","options":{"A":"Síndrome POEMS.","B":"Agamaglobulinemia ligada ao X.","C":"Amiloidose de cadeias leves.","D":"Macroglogulinemia de Waldenstrom."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-316321","number":"316321","sourceNumber":"316321","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A positividade para o antígeno HLA B27 indica o seguinte diagnóstico:","options":{"A":"Tireoidite de Hashimoto","B":"Espondilite anquilosante","C":"Artrite reumatoide","D":"Granulomatose de Wegener"},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-315795","number":"315795","sourceNumber":"315795","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente de 32 anos procura atendimento médico devido a dor abdominal de forte\nintensidade, de início há aproximadamente\n3 dias com piora nas últimas horas. Relata que a dor\ninicia-se em dorso, a direita, irradia para a fossa ilíaca direita, e é associada a episódios de\nvômito\ne sudorese nos períodos mais intensos. Nega febre. Nega trauma. Relata que a dor é associada a\nhiporexia e disúria. Mantém diurese espontânea. Tem antecedentes de cirurgia na infância devido a\ntumor de Wilms. Nega outras comorbidades. Ao exame físico: regular estado geral, fáscies de dor,\ncorado, hidratado, eupneico, anictérico, acianótico, afebril. Sem alterações cardiopulmonares.\n\nAbdome com ruídos, flácido, depressível, sem sinais de irritação peritoneal, mais doloroso à\npalpação de fossa ilíaca direita, com punho percussão negativa das lojas renais. Durante a\ninvestigação realizou exames séricos que evidenciaram leucocitose: 16.000/mm3 (VR:\n\n4.000-10.000/mm3), creatinina: 3,5mg/dl (VR: 0,7-1,3mg/dl), ureia: 115 mg/dl (VR: 13-43 mg/dl),\nproteína C reativa: 59 mg/dl (VR: < 1mg/dl).\nFoi realizado também o exame de imagem abaixo, sem\ncontraste endovenoso. A principal hipótese diagnóstica é:","options":{"A":"Apendicite aguda.","B":"Ureterolitíase obstrutiva.","C":"Nefrolitíase.","D":"Pancreatite aguda."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-315796","number":"315796","sourceNumber":"315796","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente de 32 anos procura atendimento médico devido a dor abdominal de forte\nintensidade, de início há aproximadamente\n3 dias com piora nas últimas horas. Relata que a dor\ninicia-se em dorso, a direita, irradia para a fossa ilíaca direita, e é associada a episódios de\nvômito\ne sudorese nos períodos mais intensos. Nega febre. Nega trauma. Relata que a dor é associada a\nhiporexia e disúria. Mantém diurese espontânea. Tem antecedentes de cirurgia na infância devido a\ntumor de Wilms. Nega outras comorbidades. Ao exame físico: regular estado geral, fáscies de dor,\ncorado, hidratado, eupneico, anictérico, acianótico, afebril. Sem alterações cardiopulmonares.\n\nAbdome com ruídos, flácido, depressível, sem sinais de irritação peritoneal, mais doloroso à\npalpação de fossa ilíaca direita, com punho percussão negativa das lojas renais. Durante a\ninvestigação realizou exames séricos que evidenciaram leucocitose: 16.000/mm3 (VR:\n\n4.000-10.000/mm3), creatinina: 3,5mg/dl (VR: 0,7-1,3mg/dl), ureia: 115 mg/dl (VR: 13-43 mg/dl),\nproteína C reativa: 59 mg/dl (VR: < 1mg/dl).\nFoi realizado também o exame de imagem abaixo, sem\ncontraste endovenoso. A conduta mais adequada para este caso é:","options":{"A":"Apendicectomia.","B":"Nefrolitotomia percutânea.","C":"Ureterolitotripsia endoscópica com derivação urinária por cateter.","D":"Antibioticoterapia sistêmica e hemodiálise."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-274740","number":"274740","sourceNumber":"274740","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente masculino, de 25 anos dá entrada na emergência apresentando quadro de dor\ntipo cólica em região lombar direita, intensa (9/10 na escala de dor), irradiada para flanco\ndireito há\n2 dias. Ao exame físico apresenta regular estado geral, desidratado leve, hipocorado (+/4).\n\nFrequência cardíaca 109 bpm, temperatura axilar 38ºC. Os exames de laboratório revelaram\n\n16.000 leucócitos com 7% de bastonetes. O resultado da tomografia apresenta cálculo de 0,9 cm\nem terço médio do ureter direito com moderada\nhidronefrose a montante. A melhor conduta do\nplantonista deve ser:","options":{"A":"prescrever ciprofloxacino e antagonista alfa-adrenérgico e dar alta ao paciente com\nencaminhamento para agendamento de consulta com urologista.","B":"prescrever tansulosina e dar alta ao paciente com encaminhamento ao nefrologista.","C":"internar o paciente, iniciar antibioticoterapia venosa e solicitar avaliação do urologista com\nurgência.","D":"prescrever cefalexina por 7 dias e encaminhar ao ambulatório de urologia."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-277400","number":"277400","sourceNumber":"277400","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Quanto à avaliação clínica da lombalgia, pode-se afirmar, EXCETO:","options":{"A":"Para todos os pacientes, as principais questões a serem consideradas quando da avaliação\nclínica só podem ser respondidas após a\nrealização de exames complementares como RX,\ntomografia computadorizada ou ressonância magnética para a confirmação diagnóstica","B":"Para a maioria dos pacientes, as principais questões a serem consideradas quando da avaliação\nclínica podem ser respondidas após anamnese e\nexame físico detalhados","C":"É necessário considerar a existência de fatores psicológicos ou sociais que possam amplificar\nou prolongar a dor","D":"É necessário identificar comprometimento neurológico que requeira avaliação cirúrgica."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-281808","number":"281808","sourceNumber":"281808","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A medicação administrada por via oral para disfunção erétil (DE) atende a muitos dos\natributos da \"terapia ideal\", que incluem conveniência, simplicidade e não invasividade (Morales et\nal., 1995). As terapias orais estão cada vez mais em demanda para atender ao objetivo terapêutico\nde eficácia clínica também. Sobre os inibidores da fosfodiesterase tipo 5 (PDE5), sabe-se que:","options":{"A":"bloqueiam a ação catalítica da enzima que degrada o cGMP, o efetor a jusante do óxido nítrico\nmediador da ereção, que então facilita o sinal de mecanismos de transdução do relaxamento do\nmúsculo liso do corpo cavernoso.","B":"aumentam, mas não induzem a resposta erétil, e a indução da ereção peniana requer a\nliberação de óxido nítrico das terminações nervosas penianas e do músculo liso peniano sob a\ninfluência da estimulação sexual.","C":"as estruturas químicas do sildenafil e da apomorfina são semelhantes, ao contrário do vardenafil,\ne essa diferença explica algumas distinções\nfenomenológicas observadas entre esses agentes.","D":"o tadalafil possui uma meia-vida de eliminação mais curta do que os outros três inibidores da\nPDE5. Esta característica sugere uma janela terapêutica mais curta oferecida por essa droga."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-273133","number":"273133","sourceNumber":"273133","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"No tratamento da dor, muitas vezes a melhor opção, por ser mais acessível às\ncondições do paciente, é a farmacoterapia.\nConsiderando as classes de fármacos, a alternativa que\nse encontra em consonância com o grupo de medicamentos denominados analgésicos é:","options":{"A":"Nos casos de dor aguda, ao passo que a dor é controlada, a substituição do ?regime de horário?\npelo regime de uso ?quando necessário? é\nmenos apropriada.","B":"A via retal deve ser priorizada por ser mais natural e, habitualmente, menos complicada.","C":"A sua administração deve ser realizada ?se necessário? e não no esquema ?de horário?,\nprincipalmente se a dor não for constante.","D":"Analgésicos de liberação contínua e prolongada devem ser empregados em casos de dor\ncrônica."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-258176","number":"258176","sourceNumber":"258176","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente de 72 anos, do sexo feminino, assintomática, em exame de rotina notado com\npico monoclonal de 3,8 g/dl em gamaglobulina. Apresenta creatina sérica de 1,4 mg/dl, cálcio sérico\nde 8,1 mg/dl, tomografia de corpo todo de baixa intensidade normal, mielograma com infiltração\nplasmocitária de 18%, relação de cadeias leves livres kappa/lambda: 120. Segundo o International\nMyeloma Working Group, trata-se de:","options":{"A":"Síndrome de POEMS.","B":"Pico monoclonal de significado indeterminado.","C":"Mieloma múltiplo indolente.","D":"Mieloma múltiplo ativo."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-258179","number":"258179","sourceNumber":"258179","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Pacientes com diagnóstico de mieloma múltiplo, que apresentam depósitos no rim de\nproteínas com características de fibrilas amiloide do tipo AL e coradas com vermelho congo. Esses\npacientes apresentam clinicamente com mais frequência:","options":{"A":"acidose tubular renal.","B":"lesão renal aguda.","C":"doença renal crônica.","D":"síndrome nefrótica."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-274811","number":"274811","sourceNumber":"274811","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A dor lombar é uma das queixas mais comuns da prática clínica. São fatores de risco\npara este quadro:","options":{"A":"idade avançada e sono inadequado.","B":"trabalho estressante e tabagismo.","C":"obesidade e alimentação rica em gorduras.","D":"sedentarismo e dislipidemia."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-265911","number":"265911","sourceNumber":"265911","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Várias substâncias quando supersaturadas na formação da urina podem culminar na\nformação de cálculos renais. Sabe-se que a tomografia computadorizada é um método de imagem\ncom alta sensibilidade para diagnóstico de nefrolitíase, EXCETO nos cálculos formados por:","options":{"A":"Indinavir.","B":"Oxalato de cálcio.","C":"Ácido úrico.","D":"Estruvita."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-241688","number":"241688","sourceNumber":"241688","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Mulher de 61 anos, apresenta dor e limitação de movimento em articulações\ninterfalangeanas distais das mãos, de forma\nprogressiva, há cerca de quatro anos. Refere ainda,\nnodulações nos dedos, mais proeminentes no 3º dedo da mão, bilateralmente. História de artralgia\nno joelho esquerdo, sem sintomas sistêmicos, comorbidades ou traumas articulares. Considerando\na imagem, o diagnóstico mais provável é:","options":{"A":"artrite psoriásica.","B":"artrite reativa.","C":"artrite reumatoide.","D":"gota tofácea crônica.","E":"osteoartrite primária."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":["question_bank/media/medcurso/med-cirurgia-med-cir-07/241688.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-247404","number":"247404","sourceNumber":"247404","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Durante um plantão em um pronto-socorro chega uma paciente de 35 anos com quadro\nde cólica nefrética à direita associado à\nfebre de 39ºC. Foi solicitada uma tomografia que\nevidenciou um cálculo 2 cm na pelve renal direita com hidronefrose à montante. O exame\nlaboratorial apresentou uma leucocitose de 18.000 leucócitos com 8% de bastões. Qual é a melhor\nconduta do plantonista no momento?","options":{"A":"Prescrever ciprofloxacina por 10 dias e encaminhar ao ambulatório da urologia.","B":"Prescrever norfloxacina, internar e solicitar a avaliação de um urologista.","C":"Prescrever ceftriaxona, internar e solicitar a avaliação de um urologista.","D":"Prescrever tansulosina, analgesia e encaminhar ao ambulatório da urologia."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-247405","number":"247405","sourceNumber":"247405","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Durante um plantão em um pronto-socorro chega uma paciente de 35 anos com quadro\nde cólica nefrética à direita associado à\nfebre de 39ºC. Foi solicitada uma tomografia que\nevidenciou um cálculo 2 cm na pelve renal direita com hidronefrose à montante. O exame\nlaboratorial apresentou uma leucocitose de 18.000 leucócitos com 8% de bastões. Indique o\ntratamento urológico correto após o primeiro atendimento.","options":{"A":"Passar um cateter duplo J e tratar o cálculo em um segundo tempo.","B":"Nefrolitotripsia percutânea e passagem de cateter duplo J.","C":"Litotripsia extracorpórea.","D":"Ureterorrenolitotripsia flexível e passagem de cateter duplo J."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-232222","number":"232222","sourceNumber":"232222","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A urofluxometria é recomendada para uma investigação especializada ou é necessária\nantes do tratamento invasivo da hiperplasia\nprostática benigna e/ou obstrução intravesical. A\nurofluxometria envolve o registro eletrônico da taxa de fluxo urinário ao longo do curso da micção.\nÉ\num exame urodinâmico comum e não invasivo. Os resultados da urofluxometria não são\nespecíficos para as causas dos sintomas. Por exemplo, uma taxa de fluxo anormalmente baixa\npode ser causada por uma obstrução (por exemplo, hiperplasia prostática benigna, estenose\nuretral, estenose meatal) ou por hipocontratilidade do detrusor. Na avaliação de paciente com\nsintomas do trato urinário inferior por urofluxometria,","options":{"A":"a taxa de pico fluxo identifica mais especificamente os pacientes com obstrução intravesical do\nque a taxa de fluxo média. As taxas de\nfluxos não têm boa acurácia se o volume avaliado for\ninferior de 125 a 150 mL.","B":"o registro da taxa de fluxo é o melhor teste urodinâmico não invasivo para detectar obstrução do\ntrato urinário inferior. As evidências atuais são suficientes para recomendar valor de corte para\nadequar a terapia.","C":"a taxa de pico de fluxo diminui com o avanço da idade e com o aumento do volume urinado.\n\nAtualmente, é recomendada correção da taxa de pico de fluxo de acordo com a idade e com o\nvolume urinado.","D":"a taxa de pico de fluxo inferior a 15 mL/s não diferencia obstrução intravesical de\ndescompensação da bexiga (ou hipoatividade\ndo detrusor). Embora exista uma incerteza\nconsiderável, os pacientes com uma taxa de pico de fluxo maior que 10 mL/s parecem ter piores\nresultados de tratamento após a prostatectomia do que os pacientes com uma taxa de pico de fluxo\nmenor que 10 mL/s"},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-248933","number":"248933","sourceNumber":"248933","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Na nefrolitíase, cálculos de oxalato de cálcio são os mais comuns. Constitui uma\nmedida potencialmente útil na prevenção desses cálculos:","options":{"A":"dieta restrita em cálcio visando reduzir a calciúria","B":"diurético de alça para aumentar o fluxo urinário","C":"suplementação de vitamina C","D":"restrição de sódio da dieta"},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-248935","number":"248935","sourceNumber":"248935","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um paciente dá entrada no pronto-socorro com história de febre e dor lombar. Após 3\ndias de antibioticoterapia, a febre persiste, associada a queda do estado geral. Uma\nultrassonografia evidencia a presença de hidronefrose leve e cálculo ureteral distal do lado\nesquerdo. Nesse caso, a conduta indicada deve ser:","options":{"A":"colocação de cateter duplo J","B":"terapia medicamentosa expulsiva","C":"ureterolitotripsia endoscópica","D":"ureterolitotomia laparoscópica"},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-229874","number":"229874","sourceNumber":"229874","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Doenças reumatológicas têm, de forma geral, uma predileção pelo sexo feminino, à\nEXCEÇÃO de:","options":{"A":"LES.","B":"espondiloartropatias soronegativas.","C":"Fibromialgia.","D":"artrite reumatoide."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-214958","number":"214958","sourceNumber":"214958","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Uma mulher de 24 anos apresenta, há 2 dias, dor lombar à direita, intermitente, sem\nposição de melhora ou fator desencadeante e acompanhada de náuseas e vômitos. Há 1 dia,\napresenta urina escura, disúria, polaciúria, febre, mal-estar e perda do apetite. Ao exame físico,\nencontra-se em regular estado geral e com T = 39°C. O(s) provável(is) diagnóstico(s) e o(s)\nexame(s) complementar(es) que devem ser feitos são, respectivamente:","options":{"A":"pielonefrite aguda; urina tipo I e raio x de abdome","B":"pielonefrite ascendente; hemograma e urina tipo I","C":"litíase urinária e pielonefrite aguda; tomografia computadorizada","D":"litíase urinária e pielonefrite ascendente; hemograma e uretrocistoscopia"},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-214963","number":"214963","sourceNumber":"214963","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um paciente dá entrada no pronto-socorro com história de febre e dor lombar. Após 3\ndias de antibioticoterapia, a febre persiste, associada a queda do estado geral. Uma\nultrassonografia evidencia a presença de hidronefrose leve e cálculo ureteral distal do lado\nesquerdo. Nesse caso, a conduta indicada deve ser:","options":{"A":"colocação de cateter duplo J","B":"terapia medicamentosa expulsiva","C":"ureterolitotripsia endoscópica","D":"ureterolitotomia laparoscópica"},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-216651","number":"216651","sourceNumber":"216651","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Na fisiopatologia da formação dos cálculos urinários, verifica-se que:","options":{"A":"A urease produzida pelas bactérias é um fator de risco para formação de cálculos.","B":"Hiperuricemia é o distúrbio metabólico mais comum.","C":"Hipoparatireoidismo primário representa 5% dos casos.","D":"Hipercalciúria idiopática é uma causa rara de formação de cálculos."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-216666","number":"216666","sourceNumber":"216666","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem de 35 anos chega ao pronto-socorro com quadro de cólica nefrética de forte\nintensidade associada a náuseas e vômitos há 3 horas. Foi submetido a tomografia\ncomputadorizada de abdome, que constatou um cálculo de 5 mm no ureter distal à direita, cerca de\n2 cm da junção ureterovesical e com uma hidronefrose acentuada a montante. Exames\nlaboratoriais sem sinais de infecção. Qual a melhor conduta neste caso?","options":{"A":"Tratamento cirúrgico imediato devido à hidronefrose acentuada.","B":"Medicar com anti-inflamatórios e propor terapia expulsiva medicamentosa.","C":"Medicar com anti-inflamatórios e antibiótico pelo alto risco de sepse.","D":"Tratamento cirúrgico imediato devido ao tamanho do cálculo."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-201682","number":"201682","sourceNumber":"201682","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Para prevenir litíase urinária, recomenda-se que os pacientes:","options":{"A":"Consumam líquidos suficientes para produzir 1,5 L de urina/dia.","B":"Evitem o uso de água carbonatada, que pode conferir algum risco para formação de cálculos\nurinários.","C":"Adotem dieta reduzida em sódio combinada com restrição proteica animal e uso moderado de\ncálcio que pode diminuir os episódios de cálculos em cerca de 50%.","D":"Evitem os sucos cítricos, principalmente os de limão e laranja."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-217046","number":"217046","sourceNumber":"217046","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem de 35 anos apresenta cólica nefrética. A radiografia mostra um cálculo de 1,1\ncm. Em relação a esse caso, assinale a alternativa correta.","options":{"A":"Tratamento conservador com hidratação e analgésicos não deverá produzir bons resultados.","B":"Necessariamente, o sumário de urina deverá estar alterado com a presença de hematúria ou\npiúria.","C":"Os níveis de ureia e creatinina devem ser alterados.","D":"Se for corretamente tratado, a possibilidade de recorrência existe, porém é baixa.","E":"Caso ocorra obstrução total sem resposta ao tratamento clínico, a cirurgia para a retirada do\ncálculo é a melhor opção terapêutica."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-202707","number":"202707","sourceNumber":"202707","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Ao exame físico do aparelho osteoarticular compõe-se da realização de vários testes e\nmanobras específicas, com o objetivo de auxiliar o diagnóstico clínico. Nesse contexto, o teste de\nPatrick-Fabere é utilizado para a avaliação de:","options":{"A":"Doença da sacroilíaca contralateral.","B":"Contratura do músculo reto femoral.","C":"Deformidade em flexão do quadril.","D":"Fraqueza do músculo glúteo médio."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-201705","number":"201705","sourceNumber":"201705","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Leia o caso clínico a seguir. Homem de 38 anos queixa-se de lombalgia, que teve início\nhá cinco dias. Segundo o paciente, a dor\ncomeça na região lombar, à direita, desce pela nádega,\nface posterior da coxa e da perna, calcanhar, borda externa do pé, até o 5° pododáctilo direito. Ao\nexame físico, observam-se diminuição da força de flexão plantar do pé direito e diminuição do\nreflexo aquileu direito. Nesse caso, a raiz acometida é a:","options":{"A":"L3.","B":"L4.","C":"L5.","D":"S1."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-215393","number":"215393","sourceNumber":"215393","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"O megaureter significa ureter dilatado e considera-se quando o diâmetro ureteral atinge\nlimite superior a 7mm. Assinale a alternativa INCORRETA.","options":{"A":"No megaureter, independentemente da etiologia, o peristaltismo está completamente\nprejudicado pela ineficácia da coaptação das paredes\nureterais, impedindo a propulsão do\nconteúdo urinário.","B":"A estase urinária predispõe a infecções repetidas do trato urinário, desenvolvimento de litíase e\ndeterioração do parênquima renal.","C":"O uso da ultrassonografia antenatal sistemática permitiu a melhora no diagnóstico precoce do\nmegaureter, o que até então somente era diagnosticado em crianças com infecção do trato urinário.","D":"A resolução espontânea e a diminuição da dilatação são de ocorrência rara nos casos de\nmegaureter, principalmente quando há diagnóstico antenatal."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-182484","number":"182484","sourceNumber":"182484","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um paciente dá entrada no pronto-socorro com história de febre e dor lombar. Após 3\ndias de antibioticoterapia, a febre persiste, associada a queda do estado geral. Uma\nultrassonografia evidencia a presença de hidronefrose leve e cálculo ureteral distal do lado\nesquerdo. Nesse caso, a conduta indicada deve ser:","options":{"A":"colocação de cateter duplo J","B":"terapia medicamentosa expulsiva","C":"ureterolitotripsia endoscópica","D":"ureterolitotomia laparoscópica"},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-173568","number":"173568","sourceNumber":"173568","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente do sexo masculino, de 78 anos, completamente assintomático, com\ndiagnóstico de mieloma múltiplo, com\nhemoglobina de 14 g/dL, leucócitos de 9.000/uL, plaquetas\nde 160.000/uL, cálcio iônico normal, creatinina de 1,0, inventário ósseo normal, mielograma com\n66% de plasmócitos, relação de cadeias Kappa/Lambda (Free Light Chain) de 120,0, proteína M de\n4,0 g/dL. Segundo o International Myeloma Working Group, qual é a conduta indicada?","options":{"A":"Ressonância magnética para completar estadiamento.","B":"Corticoterapia isolada.","C":"Observação e seguimento.","D":"Quimioterapia tripla."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-186452","number":"186452","sourceNumber":"186452","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A doença que se caracteriza por acometer idosos, causar dores ósseas e insuficiência\nrenal, com lesões líticas em radiografias é\na(o):","options":{"A":"Síndrome de Fanconi.","B":"Granulomatose de Wegener.","C":"Mieloma múltiplo.","D":"Doença de Behçet."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-182451","number":"182451","sourceNumber":"182451","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um homem de 35 anos, branco, apresenta lombossacralgia inflamatória há 1 ano. Há 1\nmês, teve episódio de uveíte anterior e artrite transitória do joelho direito e do tornozelo\nesquerdo. A\nradiografia de sacroilíacas revela sacroileíte bilateral e simétrica. O ecocardiograma demonstra\ninsuficiência aórtica moderada. O provável diagnóstico é:","options":{"A":"síndrome de Reiter","B":"febre reumática aguda","C":"espondilite anquilosante","D":"lúpus eritematoso sistêmico"},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-187605","number":"187605","sourceNumber":"187605","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Doença urológica caracterizada pela dor peniana, área nodular e contratura durante e\nereção é","options":{"A":"Le Petit.","B":"Le Peyronie.","C":"Las Casas.","D":"Leffort."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-173574","number":"173574","sourceNumber":"173574","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A lei de Weigert-Meyer está relacionada com uma enfermidade que acomete","options":{"A":"o epidídimo.","B":"a vesícula seminal.","C":"o ducto deferente.","D":"o ureter."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-150756","number":"150756","sourceNumber":"150756","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Os achados de exame físico na hérnia de disco cervical que comprime a raiz de C7\napresentam diminuição:","options":{"A":"Do reflexo do bíceps.","B":"De força do músculo deltoide.","C":"De força do músculo bíceps.","D":"Do reflexo do tríceps."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-160502","number":"160502","sourceNumber":"160502","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Lombalgia aguda é uma das maiores causas de procura por assistência médica em\npronto-socorro. Além de uma completa anamnese, devemos solicitar como exame complementar a\nradiografia de coluna lombar em caso de","options":{"A":"paciente com mais de 40 anos.","B":"parestesia de membros superiores associada.","C":"perda de peso maior que 10 kg em 2 meses.","D":"mais de uma visita ao médico em menos de 30 dias pelo mesmo motivo."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-160476","number":"160476","sourceNumber":"160476","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Chris Weidman, lutador de artes marciais mistas (MMA), tornou-se campeão mundial de\npeso médio ao derrotar Anderson Silva por\nnocaute técnico, em 2013. Perdeu o cinturão ao ser\nderrotado por Luke Rockhold e, na véspera de sua revanche, ficou impedido de lutar devido a uma\nlesão no pescoço, que posteriormente fora diagnosticada como hérnia de disco cervical já extrusa e\ncomprimindo a raiz nervosa adjacente. Na situação da hérnia de disco cervical que comprime a raiz\nde C6, pode ser encontrado no exame físico do paciente:","options":{"A":"parestesia na face medial do antebraço.","B":"hipoestesia do dedo mínimo.","C":"fraqueza do bíceps.","D":"diminuição do reflexo do tríceps."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-156993","number":"156993","sourceNumber":"156993","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Na espondilite anquilosante, a manifestação extra-articular mais comum é:","options":{"A":"Uveíte anterior.","B":"Fibrose pulmonar.","C":"Amiloidose.","D":"Estenose aórtica."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-160497","number":"160497","sourceNumber":"160497","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Mulher de 25 anos chega ao PS com cólica nefrética à esquerda. Foi medicada, com\nmelhora dos sintomas, e encaminhada para exame ultrassonográfico, que evidenciou: cálculo de 7\nmm impactado ao nível de ureter distal à esquerda, abaixo do cruzamento dos vasos ilíacos, com\nimportante uretero-hidronefrose à montante. Por não ter melhora do quadro álgico, optou-se por\ntratamento cirúrgico. Nesse caso, qual a melhor opção terapêutica?","options":{"A":"Litotripsia extracorpórea por ondas de choque.","B":"Ureterolitotomia sem implante de cateter duplo J.","C":"Ureterolitotripsia endoscópica rígida com implante de cateter duplo J.","D":"Ureterolitotomia com implante de cateter duplo J."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-150210","number":"150210","sourceNumber":"150210","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Em qual das situações apresentadas a seguir está dispensada a resolução cirúrgica\nimediata?","options":{"A":"Torção testicular.","B":"Priapismo de baixo fluxo.","C":"Retenção urinária por estenose uretral.","D":"Priapismo de alto fluxo."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-150250","number":"150250","sourceNumber":"150250","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente do sexo masculino, de 23 anos, apresentou cólica nefrética. Ultrassonografia\nmostrou cálculo de 0,4 cm em ureter médio direito,\nalém de vários microcálculos calicinais,\nbilateralmente. Qual é a mais provável causa metabólica da formação desses cálculos?","options":{"A":"Hiperuricosúria.","B":"Hipomagnesiúria.","C":"Hipercalciúria secundária.","D":"Hipercalciúria primária."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-150739","number":"150739","sourceNumber":"150739","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem de 52 anos, obeso, apresenta dor na nádega esquerda, que irradia para a face\nposterior e externa da coxa, face externa da perna, tornozelo (em bracelete), região dorsal do pé e\nhálux. Ao exame físico, observa-se déficit motor à extensão do hálux esquerdo, com reflexo patelar\ne aquileu preservados. Nesse caso, a raiz comprometida é a:","options":{"A":"S1.","B":"L5.","C":"L4.","D":"L1."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-160484","number":"160484","sourceNumber":"160484","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Uma questão frequentemente negligenciada nos consultórios é a saúde sexual dos\npacientes. Sobre o manejo desta, sabe-se que:","options":{"A":"Antidepressivos são medicações de escolha para o tratamento da ejaculação precoce.","B":"O desejo hipoativo na população maior que 60 anos é esperado e não necessita de abordagem\nespecífica.","C":"Embora relevante, para evitar constrangimentos, o tema da saúde sexual só deve ser abordado\napós iniciativa do paciente.","D":"O sildenafil tem como contraindicação o paciente com história de IAM prévio, uso de nitrato atual\nou hipertensão grau 2."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-157333","number":"157333","sourceNumber":"157333","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"As disfunções sexuais são problemas que ocorrem em uma ou mais das fases do ciclo\nde resposta sexual, por falta, excesso, desconforto e/ou dor na expressão e no desenvolvimento\ndessas fases, manifestando-se de forma persistente ou recorrente. Sobre as disfunções sexuais,\nassinale a alternativa CORRETA.","options":{"A":"O desejo sexual hipoativo é a aversão e esquiva ativa do contato sexual com um parceiro,\nenvolvendo fortes sentimentos negativos suficientes para evitar a atividade sexual.","B":"Anorgasmia ou disfunção orgásmica é quando ocorre grande retardo ou ausência do orgasmo\nde maneira persistente ou recorrente após uma\nfase normal de excitação sexual. A mulher ou o\nhomem com anorgasmia pode aproveitar plenamente as outras fases do ato sexual, isto é, tem\ndesejo, aproveita as carícias e se excita, porém, algo bloqueia o orgasmo; no homem há a\nausência ou retardo da ejaculação.","C":"O vaginismo ocorre quando há incapacidade persistente ou recorrente de adquirir ou manter\numa resposta de excitação sexual, com\nlubrificação-turgescência vaginal ou dificuldade de ter ou\nmanter uma ereção adequada, conhecida como disfunção erétil, até a conclusão da atividade\nsexual.","D":"A falha na fase de excitação sexual ou falha de resposta genital é a dor genital que ocorre\ndurante a relação sexual. Pode ocorrer em\nhomens, mas é mais comum em mulheres. Embora a\ndor seja mais frequente durante o ato sexual, também pode ocorrer antes ou após o intercurso da\nrelação sexual.","E":"A dispareunia é uma contração involuntária, não desejada, da musculatura da vagina que ocorre\nquando a penetração é tentada ou quando a\nmulher imagina que possa vir a ter um ato sexual com\npenetração. A penetração pode tornar-se impossível ou dolorosa."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-150278","number":"150278","sourceNumber":"150278","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"O antígeno HLA com o alelo B27 tem risco relativo entre 90 a 100% na enfermidade:","options":{"A":"Hepatite ativa crônica.","B":"Espondilite anquilosante.","C":"Artrite reumatoide.","D":"Diabetes do tipo 1."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-140620","number":"140620","sourceNumber":"140620","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Leonardo, 28 anos, bancário, procurou a emergência com fortes dores na região\nlombar. Feito o dignóstico clínico radiológico\nde dor lombar aguda, foram excluídos os sinais de\nalarme como compressão radicular e outros. O tratamento deve ser com:","options":{"A":"antidepressivos tricíclicos e derivados de opióide.","B":"repouso no leito por 1 a 3 dias e progressão para programa de exercícios físicos.","C":"corticoides e analgésico.","D":"fisioterapia com calor profundo e afastamento das atividades por 2 semanas."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-138230","number":"138230","sourceNumber":"138230","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Sobre a litíase urinária, deve-se considerar o seguinte:","options":{"A":"a frequência é relativamente comum, pois 80% dos cálculos urinário contém cálcio em sua\ncomposição primária, mais comumente oxalato de cálcio.","B":"a associação de sepse urinária com cálculos ureterais obstrutivos é inexistente.","C":"os exames de imagem são essenciais ao diagnóstico de litíase renal ou ureteral. O mais\nsensível e específico deles é a ultrassonografia.","D":"a expulsão espontânea de cálculos é rara, mesmo os cálculos menores que 5 mm têm\ntratamento eminentemente cirúrgico."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-129905","number":"129905","sourceNumber":"129905","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A litrotripsia extracorpórea por ondas de choque (LECO) contribuiu para a mudança do\ntratamento da litíase urinária após a década de 1980. Tendo em vista essa técnica, pode-se afirmar\no seguinte:","options":{"A":"a mensuração da distância entre a pele e o cálculo, realizada por meio de tomografia\ncomputadorizada, tem pouca influência no resultado.","B":"a utilização de frequência maior de impulsos concorre para melhor qualidade de fragmentação.","C":"a LECO é um procedimento minimamente invasivo, que pode ser utilizado até mesmo em\ncoagulopatias.","D":"as crianças submetidas a tratamento com LECO devem ter proteção pulmonar."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-136876","number":"136876","sourceNumber":"136876","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"O Mieloma Múltiplo (MM) é uma neoplasia hematológica caracterizada pela proliferação\nclonal de plasmócitos malignos no\nmicroambiente de medula óssea associado ao surgimento de\nproteína monoclonal sérica e/ou urinária e presença de disfunção de órgãos-alvo. Sobre o MM,\nsabe-se que:","options":{"A":"a doença óssea no MM consiste em lesões líticas em saca-bocado, osteopenia ou fraturas e o\nmétodo padrão para diagnosticar essas lesões é a ressonância nuclear magnética.","B":"para o diagnóstico de MM é necessário apenas a presença da proteína monoclonal sérica e/ou\nurinária.","C":"a eletroforese de proteínas é um estudo fundamental para detecção da proteína monoclonal no\nsoro ou na urina e a ausência de pico monoclonal não exclui o diagnóstico.","D":"o MM é precedido por uma fase de gamopatia monoclonal de significado indeterminado (GMSI)\nou de mieloma assintomático, na qual já\ndeve ser instituído tratamento quimioterápico de forma a\nprevenir evolução da doença."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-127936","number":"127936","sourceNumber":"127936","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A hiperplasia prostática benigna (HPB) representa uma das doenças mais frequentes\ndo homem. Nessa patologia:","options":{"A":"Hormônios androgênico tem influência insignificante tanto com relação à causa quanto ao seu\ndesenvolvimento","B":"O aumento do volume da próstata e o tônus aumentado da musculatura lisa do órgão são os\nresponsáveis exclusivos pelos sintomas urinários","C":"A intensidade dos sintomas miccionais é diretamente proporcional ao volume prostático","D":"O tratamento pode ser tanto clínico quanto cirúrgico. No tratamento cirúrgico, o padrão-ouro é a\ncirurgia endoscópica, em que a ressecção transuretral da próstata é a forma clássica"},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-137040","number":"137040","sourceNumber":"137040","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem de 58 anos com diagnóstico de osteoartrite de joelhos por critérios clínicos e\nradiográficos e IMC de 33 kg/m2. Nesse caso, qual a melhor medida terapêutica a longo prazo?","options":{"A":"AINES COX-2 seletivos.","B":"Injeções intra-articulares de corticoesteroide.","C":"Sulfato de glicosamina e condroitina.","D":"Perda de peso significativa."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-103671","number":"103671","sourceNumber":"103671","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"São procedimentos urológicos aplicáveis por videolaparoscopia, EXCETO:","options":{"A":"Crurorrafia diafragmática.","B":"Criptorquidia.","C":"Refluxo vesicoureteral.","D":"Prostatectomia simples."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-101232","number":"101232","sourceNumber":"101232","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A Hiperplasia Prostática Benigna (HPB) representa uma das doenças mais frequentes\ndo homem. Altamente prevalente, é considerada\npor muitos pesquisadores uma condição natural e\ninexorável do envelhecimento masculino (Urologia Brasil ? Sociedade Brasileira de Urologia, 2013).\nNessa patologia,","options":{"A":"hormônios androgênicos têm influência insignificante tanto em relação à causa quanto ao\ndesenvolvimento da doença.","B":"o aumento do volume da próstata e o tônus aumentado da musculatura lisa do órgão são os\nresponsáveis exclusivos pelos sintomas urinários.","C":"a intensidade dos sintomas miccionais é diretamente proporcional ao volume prostático.","D":"o tratamento pode ser tanto clínico como cirúrgico. No tratamento cirúrgico, o padrão-ouro é a\ncirurgia endoscópica, em que a ressecção transuretral de próstata é a forma clássica."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-79539","number":"79539","sourceNumber":"79539","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A respeito da avaliação do exame parcial de urina, qual é a alternativa CERTA?","options":{"A":"A identificação de cristais de oxalato de cálcio no exame do sedimento urinário é um dado\npatognomônico de doença renal.","B":"A presença de cilindros hemáticos traz forte sugestão de doença glomerular renal.","C":"A presença de eritrócitos, independente de eventuais alterações morfológicas, não permite a\ndeterminação do possível foco do sangramento do trato urinário.","D":"A leucocitúria é quase sempre indicativa de infecção urinária, afastando a possibilidade de\ndoenças granulomatosas renais como a sarcoidose.","E":"Chama-se microalbuminúria a excreção de albumina menor que 100 mg, identificável pelas tiras\nreagentes mais sensíveis."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-78068","number":"78068","sourceNumber":"78068","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A fisiopatologia da litíase urinária é multifatorial. Obesidade e distúrbios metabólicos\ntêm correlação importante na formação de cálculos\nurinários. Assim,","options":{"A":"as dietas com alto teor de proteínas e carboidratos alteram os parâmetros urinários e podem\naumentar o risco de formação de cálculos.","B":"a síndrome metabólica está associada com maior pH urinário.","C":"o paciente obeso tem maior propensão para cálculos de estruvita.","D":"a cirurgia bariátrica moderna pode aumentar significativamente o risco global de formação de\nlitíase urinária."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-78084","number":"78084","sourceNumber":"78084","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"No tratamento de Hiperplasia Prostática Benigna (HPB):","options":{"A":"Os alfabloqueadores adrenérgicos alteram a história natural de retenção urinária em homens\ncom sintomas do trato urinário inferior e\npróstata aumentada.","B":"Os efeitos adversos associados com finasterida e dutasterida, que podem ser particularmente\nproblemáticos nos idosos, são vertigem e hipotensão ortostática.","C":"Os portadores de HPB com retenção urinária, infecções urinárias recorrentes, insuficiência renal\ne hematúria recorrente podem desenvolver\nconsequências fatais se não forem tratados\ncirurgicamente.","D":"Os inibidores de fosfodiesterase tipo 5 não têm papel na terapia da HPB e podem ter efeito\ndeletério sobre os sintomas urinários."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-78082","number":"78082","sourceNumber":"78082","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"No diagnóstico de mieloma múltiplo, todos os critérios de lesão de órgão-alvo\nenglobam-se em:","options":{"A":"plasmócitos > 10% em medula óssea e pico monoclonal > 3,0 g/dl.","B":"anemia, hipoalbuminemia, pico monoclonal.","C":"anemia, creatinina acima de 2,0, hipercalcemia, lesões osteolíticas.","D":"anemia, aumento de DHL, hipercalcemia e pico monoclonal > 3,0 g/dl."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-83644","number":"83644","sourceNumber":"83644","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Uma paciente com cólica nefrética há 15 dias. Apresenta ecografia urinária com cálculo\nde 1,5 cm de diâmetro situado a ureter\nterminal complicado por hidronefrose. Qual o tratamento\nindicado?","options":{"A":"Cirurgia aberta.","B":"Litotripsia extracorpórea.","C":"Conduta expectante.","D":"Bicarbonato para dissolver o cálculo.","E":"Retirada endoscópica com fragmentação a laser."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-90014","number":"90014","sourceNumber":"90014","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Que estratégia de tratamento da calculose renal está incorreta:","options":{"A":"Alta ingesta de líquidos para todos os tipos de cálculos.","B":"Nefrolitotomia percutânea para cálculos de estruvita.","C":"Terapia com alopurinol para cálculos de ácido úrico.","D":"Terapia com citrato de potássio para cálculos de oxalato de cálcio.","E":"Terapia com Piridoxina para cálculos de cistina."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-85374","number":"85374","sourceNumber":"85374","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Qual dos antirretrovirais a seguir está mais envolvido no desenvolvimento de cálculo\nrenal?","options":{"A":"Zidovudina.","B":"Lapinavir.","C":"Saquianavir.","D":"Indinavir."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-63205","number":"63205","sourceNumber":"63205","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Que condição sistêmica NÃO está associada ao risco aumentado de formação de\ncálculos renais.","options":{"A":"Acidose tubular renal.","B":"Cirurgia bariátrica.","C":"Diabetes mellitus.","D":"Gota.","E":"Hipoparatireoidismo."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-62714","number":"62714","sourceNumber":"62714","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"O termo rizartrose denomina a forma de osteoartrite que acomete a articulação:","options":{"A":"interfalângica distal do quinto dedo.","B":"acromioclavicular.","C":"carpometacarpofalângica do primeiro dedo.","D":"talocalcanear."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-61781","number":"61781","sourceNumber":"61781","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A espondilite anquilosante é uma espondiloartropatia que pode ter acometimento\noftalmológico. A uveíte na espondilite anquilosante tem as seguintes características:","options":{"A":"Intermediária, aguda, bilateral.","B":"Anterior, crônica, bilateral.","C":"Posterior, aguda, unilateral.","D":"Anterior, aguda, unilateral.","E":"Posterior, crônica, unilateral."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-61841","number":"61841","sourceNumber":"61841","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um paciente de 60 anos, masculino, é internado para investigação de síndrome\nconsumptiva e quadro de paraparesia de\nmembros inferiores. Ausência de linfonodomegalias ao\nexame físico. Nos exames de investigação: Hb: 9.0 g/dl; Ht: 27%, sem outras anormalidades no\nhemograma; cálcio: 11,4 mg/dl; fósforo: 4,5 mg/dl; ureia: 67 mg/dl; creatinina: 3,4 mg/dl;\nsorologias\npara HIV e hepatites negativas. TC de tórax revelou lesões ósseas líticas em costelas. TC de\nabdome normal, RN de coluna evidenciou lesão expansiva em nível de L4-L5. Qual conduta será\ncapaz de definir a principal hipótese diagnóstica deste paciente?","options":{"A":"Punção liquórica.","B":"Cintilografia de paratireoides.","C":"Avaliação prostática.","D":"Mielograma.","E":"Cintilografia óssea."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-62752","number":"62752","sourceNumber":"62752","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Qual das doenças abaixo é causa de hematúria glomerular na infância?","options":{"A":"Hipercalciúria.","B":"Hiperuricosúria.","C":"Síndrome de Alport.","D":"Nefrolitíase."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-47305","number":"47305","sourceNumber":"47305","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um paciente com mieloma múltiplo, em tratamento quimioterápico, apresenta trombose\nvenosa profunda recente em veia femoral\ndireita. O quadro sugere efeito do uso de:","options":{"A":"bortezomibe","B":"ácido zoledrônico","C":"ciclofosfamida","D":"talidomida"},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-51098","number":"51098","sourceNumber":"51098","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Cláudio, um senhor de 45 anos de idade, refere dor aguda intensa em flanco direito e\nurina avermelhada há alguma horas. O exame físico não mostrou anormalidades e o exame de\nurina evidenciou hematúria. A radiografia do abdome revela um cálculo em rim direito. A urografia\nrevelou que o cálculo não está causando obstrução. Estudos laboratoriais adicionais mostraram\nníveis de cálcio e fosfato normais e uma urocultura subsequente foi negativa. Qual o tipo de cálculo\nque mais provavelmente causou esta condição no senhor Cláudio?","options":{"A":"cálculo de oxalato de cálcio.","B":"cálculo de ácido úrico.","C":"cálculo de xantina.","D":"cálculo de estruvita.","E":"cálculo de cistina."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-53581","number":"53581","sourceNumber":"53581","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Qual dos exames abaixo é mais acurado no diagnóstico etiológico da cólica renal?","options":{"A":"Urografia excretora.","B":"Ultrassonografia.","C":"Tomografia computadorizada com ou sem contraste.","D":"Ressonância Nuclear Magnética.","E":"EAS."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-35620","number":"35620","sourceNumber":"35620","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Mulher de 68 anos apresenta astenia e dor lombar há 8 meses. Na última semana,\nhouve queda do estado geral, obstipação, dor\nabdominal e vômito. A paciente apresenta-se\ndesidratada e com confusão mental. Os exames laboratoriais mostram lesões líticas nas vértebras\nlombares, anemia, elevação dos níveis séricos de creatinina, cálcio, ácido úrico e globulinas. A\nfosfatase alcalina é normal. O exame que confirmará a principal hipótese diagnosticada é:","options":{"A":"Dosagem do paratormônio.","B":"Mamografia.","C":"Cintilografia óssea.","D":"Bioquímica do liquor.","E":"Mielograma."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-34008","number":"34008","sourceNumber":"34008","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Na doença óssea em mieloma múltiplo:","options":{"A":"A superexpressão de RANK-L pelos plasmócitos neoplásicos sobrepuja a capacidade inibitória\nda osteoprotegerina e promove, assim, aumento da\natividade dos osteoblastos.","B":"Os inibidores da osteólise bloqueiam a progressão\n\ndas fraturas patológicas, dores ósseas e hipercalcemia em até 70%.","C":"O exame mais sensível para lesões osteolíticas é o PET/PET-CT.","D":"A infusão endovenosa mensal de inibidores da osteólise é recomendada por três anos, pois,\nalém deste limite, seu uso está associado à osteonecrose de mandíbula."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-22976","number":"22976","sourceNumber":"22976","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Analise o caso a seguir para responder à seguinte questão. Uma paciente do sexo\nfeminino, com 46 anos, adentra em unidade\nde emergência com quadro de dor tipo pontada, de\ninício súbito e forte intensidade em andar superior do abdome, associada a vômitos. Na história\nclínica referiu episódios recorrentes de dor tipo cólica em hipocôndrio direito há cerca de dois\nanos.\nAo exame físico apresentava abdome depressível, porém doloroso à palpação profunda em todo o\nandar superior, com presença de equimose em flancos. Qual o diagnóstico provável para o caso\ndescrito?","options":{"A":"Colecistite litiásica","B":"Úlcera péptica perfurada","C":"Úlcera péptica tenebrante","D":"Pancreatite aguda"},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-27154","number":"27154","sourceNumber":"27154","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"O medicamento eficaz no gerenciamento da cólica ureteral é:","options":{"A":"Betanecol","B":"Prostaglandina F2a","C":"Fisostigmina","D":"Indometacina","E":"Efedrina"},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-11089","number":"11089","sourceNumber":"11089","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Qual das manobras propedêuticas abaixo, quando positiva, melhor representa o\nacometimento inflamatório das articulações sacroilíacas?","options":{"A":"Lasêgue.","B":"Finkelstein.","C":"Phalen.","D":"Volkmann.","E":"N.d.a."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-250232","number":"250232","sourceNumber":"250232","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem de 65 anos, diagnóstico prévio de insuficiência cardíaca congestiva (fração de\nejeção: 35%), internada devido perda de peso (10 kg/6 meses), anemia e dor lombar. Apresenta os\nseguintes exames: Hb: 8g/dL, hematócrito: 24 %, Cr: 3 mg/dL, Ur: 100 mg/dL, AST: 45 U/L, ALT: 38\nU/L. À radiografia de coluna lombar: osteopenia difusa e fraturas parciais de L3 e L4 por\nencunhamento. Após 3 dias de internação, teve dor abdominal importante e anúria, laboratório com\ncálcio total: 17 mg/dL e albumina: 3,2 g/dL. Sobre o caso clínico, assinale a alternativa CORRETA:","options":{"A":"Eletroforese de proteínas séricas e urinárias, mielograma e biópsia de medula óssea podem\najudar a esclarecer o diagnóstico hematológico.","B":"A conduta mais adequada para a hipercalcemia deste paciente é a hidratação vigorosa.","C":"8% de plasmócitos na medula óssea confirma a principal hipótese diagnóstica.","D":"A etiologia mais provável da hipercalcemia em questão é o uso de diurético tiazídico."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-176236","number":"176236","sourceNumber":"176236","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente do sexo masculino com 59 anos de idade, com histórico de dor lombar\npersistente e anemia normocítica e\nnormocrômica, foi submetido à TC de coluna lombar que\nmostrou diversas lesões líticas em segmentos torácicos e lombossacrais. A eletroforese de\nproteínas séricas revelou pico monoclonal nas gamaglobulinas, mais especificamente de IgG. A\nbiópsia de medula óssea revelou 12% de plasmócitos clonais. O paciente nega dispneia, mesmo\naos esforços, e tem ecocardiograma normal. O TRATAMENTO DE ESCOLHA nessa situação é:","options":{"A":"Quimioterapia isolada com melfalan.","B":"Quimioterapia isolada com lenalidomida.","C":"Transplante autólogo de medula óssea.","D":"Apenas controle de sintomas e complicações da doença de base.","E":"Plasmaféreses de repetição."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-62597","number":"62597","sourceNumber":"62597","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente do sexo masculino, 42 anos, com história de cólicas nefréticas de repetição há\n6 anos, vem à consulta com os seguintes\nexames: creatinina plasmática = 0,9 mg/dl; cálcio sérico =\n9,1 mg/dl e urina de 24 horas com volume de 1.800 ml; cálcio urinário = 386 mg/dia (valor de\nreferência = até 300 mg/dia) e citratúria de 579 mg/dia (valor de referência = acima de 320 mg/dia).\nTodas as medidas abaixo podem ser utilizadas no tratamento, EXCETO:","options":{"A":"Ingestão hídrica maior que dois litros ao dia.","B":"Diurético tiazídico.","C":"Aumento da ingestão de sucos cítricos, como suco de laranja ou limão.","D":"Restrição moderada da ingestão de sal e proteínas de origem animal.","E":"Restrição de ingestão diária de cálcio (< 500 mg/dia)."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-342389","number":"342389","sourceNumber":"342389","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Cálculos no trato urinário são uma causa comum de visitas ao pronto-socorro. Sobre o\ntema, marque a opção INCORRETA.","options":{"A":"cálculos de fosfato amônio-magnésio (estruvita) estão relacionados com a infecção urinária\ncrônica com bactérias produtoras de urease.","B":"cálculos de ácido úrico são muitas vezes radiotransparentes na radiografia simples e se formam\nna urina ácida.","C":"cálculos de urato ácido de amônio representam a variedade mais comum.","D":"cálculos de cistina são causados por um erro inato do metabolismo (homocistinúria,\nnormalmente homozigota).","E":"a causa metabólica mais comum encontrada em formadores de cálculos de cálcio é a\nhipercalciúria absortiva."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-342402","number":"342402","sourceNumber":"342402","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"São fatores de risco gerais para o desenvolvimento de cálculos urinários EXCETO:","options":{"A":"Hipercalciúria","B":"Hiperuricosúria","C":"Cistinúria","D":"Hipercitratúria","E":"Hiperoxalatúria"},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-342403","number":"342403","sourceNumber":"342403","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Assinale a opção que reúne bactérias que participam na formação dos cálculosde\nestruvita.","options":{"A":"E. coli e Clamídia","B":"E. coli e Proteus","C":"Estafilococos e Klebsiella","D":"E. coli e Estafilococos","E":"Proteus e Klebsiella"},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-281500","number":"281500","sourceNumber":"281500","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente de 45 anos, portador de dor lombar crônica há 2 anos, após pegar peso no\ntrabalho. No episódio inicial apresentou limitação funcional e ficou afastado do trabalho por 10\ndias.\nVoltou ao trabalho, porém mantendo dor lombar contínua que piora aos movimentos e melhora com\nrepouso, com irradiação para nádegas e membros inferiores. Exame neurológico normal. Sem\nfebre. Ressonância magnética da coluna lombar evidencia protrusões discais em L4-L5 e L5-S1,\nsem conflito radicular. A principal hipótese diagnóstica é:","options":{"A":"Espondilite anquilosante.","B":"Lombalgia mecânica.","C":"Estenose canal lombar.","D":"Osteoartropatia hipertrófica.","E":"Hérnia discal."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-252417","number":"252417","sourceNumber":"252417","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"O diagnóstico diferencial de lombalgia é amplo e muitas vezes pode ser realizado sem\npropedêutica armada e considerando história clínica e exame físico bem apurado. Assinale a opção\nonde há correspondência coerente entre o sinal de alerta em lombalgia e a causa potencial para tal\nachado.","options":{"A":"Febre e perda de peso - causas inflamatórias","B":"Rigidez matinal maior que 1 hora - causas traumáticas","C":"Dor com maior intensidade à noite - osteoartrite","D":"Diminuição da força muscular - espondilite ou epifisite","E":"Anestesia em sela - compressão da cauda equina"},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-154375","number":"154375","sourceNumber":"154375","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente 72 anos, masculino, tem anemia, insuficiência renal, hipercalcemia e lesões\nósseas líticas, com presença de proteína monoclonal por imunofixação. Qual deve ser o\ndiagnóstico?","options":{"A":"Adenocarcinoma de próstata metastático.","B":"Mieloma múltiplo.","C":"Adenocarcinoma de pulmão metastático.","D":"Neoplasia maligna de rim metastática.","E":"Tumor de paratireoide metastático."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-160448","number":"160448","sourceNumber":"160448","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um paciente de 55 anos é encaminhado à hematologia para investigação de mieloma\nmúltiplo. Ele está assintomático e os exames laboratoriais mostram (Conforme imagem do caderno\nde questões): Sobre esse cenário clínico, assinale a afirmativa verdadeira.","options":{"A":"Trata-se de um mieloma múltiplo assintomático (smoldering mieloma).","B":"A terapia de indução mais moderna consiste em pulsos isolados de dexametasona.","C":"O paciente apresenta mieloma múltiplo estágio IIB (dois-B).","D":"Há indicação para uso parenteral de pamidronato.","E":"O transplante heterólogo de medúla óssea é o tratamento mais eficaz."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-160425","number":"160425","sourceNumber":"160425","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um homem de 40 anos apresenta dor lombar, forte intensidade, que piora ao pegar\npeso e alivia com repouso. Não há irradiação\nnem outros sintomas associados. O paciente é\nporteiro e nega outras comorbidades. A conduta mais apropriada é:","options":{"A":"Prescrever anti-inflamatórios não esteroidais e reavaliar após 7 a 14 dias.","B":"Prescrever corticoide intramuscular de depósito.","C":"Solicitar ressonância magnética da coluna.","D":"Solicitar hemograma, VHS e radiografia da coluna.","E":"Solicitar tomografia computadorizada da coluna."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-132844","number":"132844","sourceNumber":"132844","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Sobre o tratamento metabólico da litíase urinária, marque a alternativa INCORRETA:","options":{"A":"Reposição oral de cálcio está indicada nos casos de hiperoxalúria.","B":"Terapia com diurético tiazídico é uma importante alternativa em boa parte dos casos de\nhipercalciúria.","C":"Reduzida ingesta de sódio, cálcio e proteína animal, bem como alta ingesta hídrica são\nrecomendações gerais importantes para a doença.","D":"Pacientes com cálculo de ácido úrico podem ser tratados como citrato de potássio.","E":"Aumento da ingesta de limonada tem se mostrado uma boa alternativa em pacientes com\nhipocitratúria."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-103898","number":"103898","sourceNumber":"103898","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A dor associada à obstrução do trato urinário aguda é resultado de:","options":{"A":"Natriurese compensatória.","B":"Diminuição do fluxo sanguíneo medular.","C":"Distensão do sistema coletor ou cápsula renal.","D":"Aumento do fluxo sanguíneo renal.","E":"Prostaglandinas."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-87522","number":"87522","sourceNumber":"87522","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem, 27 anos, com lombalgia, pior pela manhã, atenuada progressivamente com o\ndecorrer do dia, presente há 5 semanas. Sem outras queixas. Nega artrite ou artralgia periférica.\nTeste de Schober mostrou expansão da distância marcada em 3 cm à flexão anterior do tronco. Ao\nfazer inspiração máxima, o paciente aumenta em 7 cm o diâmetro torácico. É CORRETO afirmar:","options":{"A":"Se ele tiver uma radiografia ou RNM de articulações sacroilíacas confirmando sacroileíte grau 2\nou maior bilateralmente estará confirmado o\ndiagnóstico de espondilite anquilosante;","B":"Pode-se dar o diagnóstico de espondilite anquilosante, já neste momento, apenas com base em\ncritérios clínicos;","C":"É necessária a positividade do HLA-B27 para o diagnóstico de espondilite anquilosante.","D":"O diagnóstico de espondilite anquilosante não pode ser confirmado sem que o paciente tenha\npelo menos 3 meses de dor.","E":"Está excluída a hipótese de espondilite anquilosante para esse paciente."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-65582","number":"65582","sourceNumber":"65582","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A \"LECO\" é indicada nos seguintes cálculos renais:","options":{"A":"\"menor ou igual a\" 20 mm.","B":"\"menor ou igual a\" 40 mm.","C":"\"menor ou igual a\" 60 mm.","D":"\"menor ou igual a\" 80 mm.","E":"Nenhuma das anteriores."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-362827","number":"362827","sourceNumber":"362827","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem, negro, 60 anos, sem patologias prévias, vem para consulta com quadro de dor\nóssea principalmente em região lombar, associado com fratura patológica evidenciada a radiografia\nde coluna lombossacra. Traz exames laboratoriais prévios com anemia, elevação de creatinina e\nhipercalcemia. O diagnóstico mais provável é:","options":{"A":"mieloma múltiplo.","B":"hipoparatireoidismo.","C":"intoxicação por vitamina D.","D":"hiperparatireoidismo terciário."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-308309","number":"308309","sourceNumber":"308309","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Em relação ao Mieloma Múltiplo, é correto afirmar:","options":{"A":"É comum o surgimento de hepatoesplenomegalia e linfonodomegalias com a progressão da\ndoença.","B":"É uma doença de adulto jovem, entre 20 e 40 anos, frequente no sexo masculino.","C":"Anemia, insuficiência renal, lesões líticas e hipercalcemia fazem parte do quadro\nclínico-laboratorial.","D":"É necessário realizar biópsia de linfonodo e eletroforese de hemoglobina para diagnóstico."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-313384","number":"313384","sourceNumber":"313384","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Mulher, 28 anos, com câncer de colo uterino estádio IIIB em quimioterapia é admitida\nno plantão de ginecologia com quadro de\noligúria associado com náuseas e dor lombar bilateral. Ao\nexame físico apresenta-se com PA 150x90mmHg, FC 90 bpm, emagrecida e sem edemas.\n\nPalpação abdominal algo dolorosa difusamente, sem massas palpáveis. Exames laboratoriais\ndemostram uréia de 110 mg/dL e creatinina de 9\nmg/dL. Traz tomografia de 1 semana atrás com\nhidronefrosebilateral moderada. A conduta deverá ser:","options":{"A":"Tentativa de implante de cateter pigtail ureteral bilateralmente;","B":"Sondagem vesical e hidratação com quantificação dodébito urinário;","C":"Contatar a nefrologia para hemodiálise de urgênciadevido clínica de uremia;","D":"Teste de estresse com furosemida 1 mg/kg equantificar diurese em 2 horas."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-313409","number":"313409","sourceNumber":"313409","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem, 28 anos, caminhoneiro, vem para consulta com queixa de dor lombar crônica\ncom piora progressiva no último semestre. A\ndor é pior ao acordar acompanhada de rigidez lombar,\nmas melhora com atividade física. Ao exame físico, o teste de Schober encontra-se alterado. Qual é\no exame mais importante para auxiliar no diagnóstico?","options":{"A":"Anti-CCP.","B":"HLA-B27.","C":"Anti-DNAds.","D":"Cromogranina A."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-288125","number":"288125","sourceNumber":"288125","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente do sexo masculino, 35 anos, sem comorbidades, procura uma Unidade de\nPronto Atendimento (UPA) referindo queixas de\ndor lombar à esquerda com irradiação para fossa\nilíaca esquerda e testículo, associada a náuseas e vômitos há 12 horas. Ao exame físico,\napresenta-se com fácies de dor, sudorese, acianótico, anictérico, em posição antálgica; sinais\nvitais\nnormais; pulsos cheios, perfusão periférica preservada. Sistema cardiopulmonar sem alterações.\n\nAbdome com dor à palpação em flanco e fossa ilíaca esquerda, ruídos hidroaéreos preservados.\nSinal de Giordano positivo à esquerda.\nRealizados exames séricos e de imagem na urgência.\n\nApresentou hematúria microscópica (exame de urina tipo I) e ultrassonografia de vias urinárias\nmostrando hidronefrose leve à esquerda, sem\nevidências de cálculos ou lesões no sistema coletor\nurinário. Bexiga de paredes lisas, sem cálculos. Nesse caso, pela melhor sensibilidade diagnóstica,\nqual exame está indicado?","options":{"A":"Uretrocistografia Miccional","B":"Ressonância Magnética Nuclear de vias urinárias","C":"Tomografia Computadorizada de Abdome Total sem contraste","D":"Cintilografia Renal Dinâmica"},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-274108","number":"274108","sourceNumber":"274108","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Masculino, 45 anos, trabalhador da construção civil, relata que após carregar alguns\nsacos de cimento apresentou súbita lombalgia,\ncom dor irradiada para parte póstero lateral da coxa\ne perna até o tornozelo. Ao exame físico, identificada perda de reflexo Aquileu. Considerando a\nhipótese diagnóstica de hérnia de disco, qual é o disco e a raiz nervosa acometida?","options":{"A":"L2-L3; L3","B":"L4-L5; L5","C":"L3-L4; L4","D":"L5-S1; S1"},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-267296","number":"267296","sourceNumber":"267296","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Em relação aos cálculos ureterais, é CORRETO afirmar:","options":{"A":"Caso a obstrução persista após 6 semanas, está indicada a cirurgia.","B":"A maioria é expelida espontaneamente.","C":"São dois os pontos mais comuns de obstrução no trajeto ureteral.","D":"Cólica renal grave que diminui muito no dia seguinte é indicativo da migração do cálculo."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-283986","number":"283986","sourceNumber":"283986","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem, 28 anos, caminhoneiro, vem para consulta com queixa de dor lombar crônica\ncom piora progressiva no último semestre. A\ndor é pior ao acordar acompanhada de rigidez lombar\nmas melhora com atividade física. Ao exame físico o teste de Schober encontra-se alterado. Qual\nexame mais importante para auxiliar no diagnóstico?","options":{"A":"Anti-CCP","B":"HLA-B27","C":"Anti-DNAds","D":"Cromogranina A"},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-254171","number":"254171","sourceNumber":"254171","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"São achados característicos da Osteoartrite, EXCETO:","options":{"A":"Fator Reumatoide positivo","B":"Esclerose subcondral","C":"Rigidez matinal","D":"Nódulos de Heberden"},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-254178","number":"254178","sourceNumber":"254178","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Assinale a alternativa com o medicamento mais eficaz para terapia expulsiva de cálculo\nureteral.","options":{"A":"Nifedipina","B":"Alopurinol","C":"Doxazosina","D":"Hidroclorotiazida"},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-251306","number":"251306","sourceNumber":"251306","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Qual a melhor conduta para um paciente que você faz o diagnóstico clínico de\nlombalgia mecânica?","options":{"A":"Prescrever AINES por 3 dias e repouso por 2 dias;","B":"Solicitar radiografia de coluna lombar e, se resultado normal, prescrever AINES por 5 dias e\nrepouso por 3 dias;","C":"Orientar postura correta, atividade física regular, prescrever AINES por 5 dias e repouso por 3\ndias;","D":"Prescrever AINES, solicitar radiografia de coluna lombar e encaminhar ao ortopedista."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-217935","number":"217935","sourceNumber":"217935","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"M.J.S, 35 anos de idade, sexo masculino, procura a UBS por uma dor de início súbito\nhá 3 dias, de leve intensidade, em região\nlombar. Nega queda ou trauma direto na coluna, refere\nque dormiu bem e amanheceu com dores na região. Não estava usando nenhum medicamento.\nSeu médico de família prescreveu paracetamol 500 mg a cada seis horas se houvesse dor. Em\nrelação à prescrição de analgésicos para dor em adultos, é CORRETO afirmar que:","options":{"A":"O ideal é usar o primeiro analgésico prescrito na dose máxima antes de associar outro\nanalgésico. A dose máxima de paracetamol é 1 g, três vezes ao dia.","B":"Se não melhorar com a dose máxima de paracetamol, pode-se substituí-lo por ibuprofeno,\niniciando na dose máxima.","C":"A conduta está correta, pois, na escala de analgesia, essa medicação é recomendada como\nprimeira escolha adequada para iniciar a analgesia na maioria das pessoas com dor leve a\nmoderada.","D":"Nesse caso, deve-se indicar sempre um anti-inflamatório não-esteróide como primeira escolha."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-185216","number":"185216","sourceNumber":"185216","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente de 34 anos com queixa de dor lombar, na região glútea e nas coxas há 15\ndias. Trabalhador braçal em frigorífico. Histórico clínico sem outras anormalidades. Apresenta\nsensibilidade, reflexos, mobilidade, trofismo e força muscular dos membros inferiores normais. A\nmanobra de Lasègue a direita, elevação do membro inferior a 60 graus na posição supina, refere\ndor na região lombar. No teste de carga axial, a compressão vertical sobre a cabeça do paciente\ndesencadeia dor lombar. Assinale a alternativa CORRETA em relação ao manejo deste caso:","options":{"A":"Solicitar ressonância magnética da coluna lombar para investigar os sinais de compressão\nradicular identificados no exame físico.","B":"Solicitar radiografia de coluna lombar para afastar fratura e/ou artrose.","C":"Solicitar radiografia de coluna lombar e VHS para descartar infecção ou neoplasia.","D":"Solicitar exames complementares não é necessário pela suspeita de lombalgia inespecífica\naguda.","E":"Recomendar repouso por 30 dias e fisioterapia pois tais medidas aceleram a recuperação."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-185238","number":"185238","sourceNumber":"185238","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Mulher, 50 anos, diabética, queixa de dor nos joelhos há 3 anos. Inicialmente a dor era\ninsidiosa e aliviava com o repouso, agora persistente e refratária aos analgésicos, com rigidez\nmatinal de 20 minutos e rigidez articular fugaz após curtos períodos de repouso. Instabilidade do\njoelho especialmente ao descer escadas. No exame com crepitação nos joelhos e sinais de\nderrame articular. Radiografia mostra proliferação das margens ósseas, diminuição do espaço\narticular e esclerose óssea subcondral. Sobre o caso, assinale a alternativa CORRETA em relação\nao diagnóstico e tratamento, respectivamente:","options":{"A":"Osteoartrite, exercícios aeróbicos e contra resistência.","B":"Osteoartrite, corticoides sistêmicos.","C":"Artrite reumatoide, imunomoduladores.","D":"Artrite reumatoide, anti-inflamatórios não esteroides.","E":"Gota, alopurinol e colchicina."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-167827","number":"167827","sourceNumber":"167827","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A nefrolitíase é uma das afecções mais comuns do trato urinário, com aumento de\nincidência nos últimos anos. Sobre a nefrolitíase, assinale a afirmativa correta.","options":{"A":"Ocorre com maior frequência em mulheres, com proporção de 2:1 quando comparada aos\nhomens.","B":"A maior incidência ocorre entre a terceira e quinta décadas de vida.","C":"A maioria dos cálculos é de origem vesical.","D":"Os cálculos formados por ácido úrico são os mais comuns, correspondendo a 70% - 80% dos\ncasos."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-167802","number":"167802","sourceNumber":"167802","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A manobra de Patrick-Faber, que consiste na flexão, seguida de abdução e rotação\nexterna forçada da coxa, é utilizada na\navaliação","options":{"A":"da compressão do ciático homolateral.","B":"das raízes lombares contralaterais.","C":"da coxofemoral homolateral.","D":"da sínfise púbica."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-158149","number":"158149","sourceNumber":"158149","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Considerando a etiologia dos cálculos renais, é cálculo radiolúcido:","options":{"A":"Oxalato de cálcio.","B":"Estruvita.","C":"Ácido úrico.","D":"Cistina."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-159429","number":"159429","sourceNumber":"159429","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem, enfermo, 79 anos, queixa-se de dor lombar aguda com início há quase 3\nsemanas. Refere ainda, insônia e perda de peso de 5 kg nos últimos 8 meses. Nega melhora da\ndor após uso de anti-inflamatórios não hormonais, derivados morfínicos e repouso no leito. A\nhipótese diagnóstica mais provável é:","options":{"A":"Comprometimento metastático da coluna lombar.","B":"Estenose do canal medular.","C":"Fratura vertebral por osteoporose senil.","D":"Lombalgia mecânica."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-156508","number":"156508","sourceNumber":"156508","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"I.N.G., 65 anos, sexo masculino, vinha em investigação devido à anemia e astenia de\ninício há cerca de 6 meses, no entanto, evoluiu com quadro de náuseas, vômitos e hiporexia\nassociado à oligúria e queda da própria altura. Radiografia de crânio com evidência de lesões\nlíticas. Exames laboratoriais demonstram elevação das escórias nitrogenadas, além de elevação de\ncálcio, ácido úrico e globulinas, com fosfatase alcalina normal. Qual é o melhor exame para\nconfirmar a principal hipótese diagnóstica?","options":{"A":"Mielograma.","B":"Biópsia Renal.","C":"Cintilografia óssea.","D":"Dosagem de Paratormônio."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-98034","number":"98034","sourceNumber":"98034","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente de 45 anos, sexo masculino, é atendido em pronto atendimento apresentando\ndor em cólica de grande intensidade, início\nsúbito, originada no flanco esquerdo, propagando-se\npara a região inguinal homolateral. Foi realizado raio X simples de vias urinárias que não\napresentou alterações. O exame de urina mostrou pH urinário igual a 5,8. Após realização de\nultrassom de abdome total, é confirmada a hipótese de nefrolitíase. A composição provável do\ncálculo e a orientação inicial devem ser:","options":{"A":"Cálculo de ácido úrico; alcalinização da urina com suplementação oral de bicabornato.","B":"Cálculo de oxalato de cálcio; diminuir ingestão de cálcio.","C":"Cálculo de estruvita; suplementação oral de magnésio.","D":"Cálculo de fosfato de cálcio; suplementação oral com citrato de potássio, mantendo pH urinário\ninferior a 7,0."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-75386","number":"75386","sourceNumber":"75386","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A sacroileíte e o envolvimento da coluna vertebral, com soldadura dos corpos vertebrais\ne presença de sindesmófitos, produzindo um\naspecto de ?coluna em bambu? e ?postura de\nesquiador?, são sugestivos de:","options":{"A":"Espondilite anquilosante.","B":"Síndrome de Reiter.","C":"Artrite Psoriática.","D":"Artrite reumatoide juvenil."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-57608","number":"57608","sourceNumber":"57608","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"NÃO constitui fator de risco associado a nefrolitíase idiopática, responsável pela\nmaioria\ndos cálculos sintomáticos:","options":{"A":"Ingestão elevada de proteínas.","B":"Ingestão elevada de cloreto de sódio.","C":"Hiperuricosúria.","D":"Ingestão elevada de cálcio.","E":"Acidose tubular renal tipo 1."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-274870","number":"274870","sourceNumber":"274870","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"C.O.B., masculino, 40 anos, sem comorbidades, deu entrada no pronto-socorro com\nquadro de dor tipo cólica com irradiação\npara fossa ilíaca direita e bolsa escrotal, sem melhora com\nuso de analgésicos. Nega febre e alteração de jato urinário. Ao exame: PA 120 x 80 mmHg; Fc 90\nbpm; Fr 18 irpm. Abdome com RHA presentes e Giordano positivo à direita. Exames laboratoriais:\nCreatinina 1,8; Ureia 45; Hb 16; Ht 48%; leucócitos de 8.000 com 0% de bastões; Urina 1 hemácias\n35 p/c leucócitos 05 p/c nitrito negativo; PCR 30. Tendo esse caso clínico como referência, assinale\na alternativa CORRETA:","options":{"A":"Trata-se de uma cólica nefrética, sendo necessária a realização de exame de imagem para\nmelhor investigação diagnóstica.","B":"A analgesia deve ser feita com anti-inflamatórios endovenosos para melhor manejo da dor.","C":"Devido à presença de Giordano positivo no exame físico, afirma-se que o paciente apresenta\npielonefrite associada, necessitando de antibióticos ainda no pronto-socorro.","D":"A disfunção renal é secundária ao uso crônico de anti-inflamatórios.","E":"Trata-se de um abdome agudo por apendicite, necessitando de centro cirúrgico com urgência."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-239613","number":"239613","sourceNumber":"239613","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"O acometimento ósseo pelo mieloma múltiplo - MM é característico da doença,\npodemos apenas concordar que:","options":{"A":"São lesões líticas que afetam predominantemente o esqueleto axial (crânio, coluna e gradil\ncostal) e as áreas proximais dos membros superiores e inferiores.","B":"São lesões blasticas que afetam predominantemente o esqueleto axial (crânio, coluna e gradil\ncostal) e as áreas proximais dos membros superiores e inferiores.","C":"São lesões líticas que afetam raramente o esqueleto axial (crânio, coluna e gradil costal) e as\náreas proximais dos membros superiores e inferiores.","D":"São lesões líticas que afetam predominantemente o esqueleto axial (crânio, coluna e poupam os\ngradis costais) e as áreas proximais dos membros superiores e inferiores."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-239615","number":"239615","sourceNumber":"239615","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A identificação da doença mieloma múltiplo - MM em seu estágio inicial e o\nencaminhamento ágil e adequado para o atendimento especializado dão à Atenção Básica um\ncaráter essencial para um melhor resultado terapêutico e prognóstico dos casos. A maioria dos\npacientes apresenta-se com sinais e sintomas de infiltração plasmocitária (óssea ou de outros\nórgãos) ou lesão renal por deposição de proteína monoclonal tumoral. As manifestações clínicas\nmais comuns ao diagnóstico são listadas abaixo, qual dos itens apresenta erro?","options":{"A":"Doença óssea - Dor óssea principalmente em tórax e coluna induzida pela movimentação (60%).","B":"Doença óssea evoluindo com déficit motor ou sensitivo, fraturas patológicas, redução da altura.","C":"Insuficiência renal - Edema, oligúria, uremia, elevação de creatinina (48%).","D":"A insuficiência renal é secundária principalmente à nefropatia obstrutiva devido a cilindros de\ncadeia pesada monoclonal (proteína de Bence Jones) que se depositam nos túbulos contornados\ndistais e coletores, conhecida como ?rim do mieloma?, e à hipocalcemia."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-239616","number":"239616","sourceNumber":"239616","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"No mieloma múltiplo - MM, plasmócitos monoclonais geralmente representam mais de\n10% das células nucleadas da medula óssea;\nno entanto 4% dos pacientes com MM sintomático\ntêm plasmocitose abaixo de 10%. Não podemos aceitar que:","options":{"A":"Isto pode ser consequência da infiltração focal por células do MM ou de problema de coleta da\nmedula óssea, principalmente quando realizado apenas mielograma.","B":"A infiltração corresponde a 50% em média.","C":"Se houver proteína-M elevada (maior que 5g/dL) ou sintomas sugestivos de hiperviscosidade,\nnão é recomendável a medida da viscosidade\nsérica.","D":"Deve-se repetir a coleta em local, preferivelmente com biópsia de medula óssea (BMO)."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-243749","number":"243749","sourceNumber":"243749","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Sobre litíase urinária e cólica nefrética, pode-se afirmar que:","options":{"A":"Hioscina é suficiente para alívio do quadro de dor.","B":"Dor de início na região lombar reforça o diagnóstico de litíase renal.","C":"A maioria dos casos de litíase renal é resolvida com litotripsia extracorpórea.","D":"O principal determinante da eliminação espontânea é a largura do cálculo urinário."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-220241","number":"220241","sourceNumber":"220241","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem, 72 anos, obesidade grau 2, com queixa de dor lombar há 3 anos, progressiva,\nsem história de trauma. Dor com piora após\nmovimentação e certo alívio ao repouso. Piora do\nquadro nos últimos 2 meses, com persistência da dor ao repouso e sem melhora com uso diário de\nanalgésicos e anti-inflamatórios não esteroidais. Ao exame: dor a palpação lombar baixa,\nmobilidade lombo-sacra preservada, encurtamento dos músculos isquiotibiais, limitação importante\nda rotação interna e abdução do quadril esquerdo, manobra de Thomas (+), manobra de Yeoman\n\n(-), manobra de Laségue (-). A suspeita diagnóstica e exame adequado são:","options":{"A":"hérnia de disco, ressonância nuclear magnética.","B":"hérnia de disco, radiografia de coluna lombar.","C":"osteoartrose de quadril, ressonância nuclear magnética.","D":"osteoartrose de quadril, radiografia da bacia."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-187406","number":"187406","sourceNumber":"187406","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Assinale a assertiva CORRETA:","options":{"A":"Na lombalgia mecânica a dor geralmente se irradia para as coxas e apresenta evolução\ninsidiosa.","B":"A dor da hérnia discal geralmente inicia-se nas primeiras horas do dia, com quadro agudo,\nintenso, com irradiação da dor para um dos membros inferiores.","C":"No osteoma osteoide a dor ocorre durante o dia, à movimentação, devido à liberação de\nprostaglandinas pelas células tumorais nesse horário.","D":"No estreitamento do canal raquidiano a dor ao caminhar piora pricipalmete ladeira acima e\nmelhora ladeira abaixo, diferenciando da claudicação vascular.","E":"A dor de origem psicossomática apresenta-se com sensibilidade dolorosa profunda, sem\nalternância de localização."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-177064","number":"177064","sourceNumber":"177064","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Quais são os cálculos renais que estão associados à infecção urinária por Proteus sp.?","options":{"A":"Ácido úrico.","B":"Oxalato.","C":"Estruvita.","D":"Cistina."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-151643","number":"151643","sourceNumber":"151643","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Em relação à osteoartrose de joelhos, assinale a alternativa CORRETA:","options":{"A":"Fortalecimento muscular associado a alongamento são medidas que devem ser implantadas\ndesde o início do diagnóstico.","B":"Nos períodos de piora de dor articular devemos orientar repouso total da articulação acometida.","C":"O uso de anti-inflamatórios não esteroidais em altas doses em curtos períodos de tempo podem\nlevar à melhora prolongada destes pacientes.","D":"O uso de antiartrósicos como a diacereína associado a analgésicos simples como paracetamol\nnão costuma trazer benefícios em relação à dor\ndestes pacientes."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-151049","number":"151049","sourceNumber":"151049","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Em urologia um diagnóstico corriqueiro é o de nefrolitíase. Os distúrbios metabólicos\nque podem contribuir para a formação de cálculos\nrenais são, EXCETO:","options":{"A":"Hipercalciúria.","B":"Hiperuricosúria.","C":"Hipercitratúria.","D":"Hiperoxalaciúria."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-152351","number":"152351","sourceNumber":"152351","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente masculino, 5 anos de idade, tem antecedente de fulguração de válvula de\nuretra posterior ao nascer, e usa\nanticolinérgico e alfabloqueador desde o primeiro ano de vida.\nMãe refere que ainda não conseguiu tirar das fraldas. No último ano, teve 3 episódios de infecção\nurinária. Nos exames, constatou-se creatinina de 1,1, ureia de 70, potássio de 5,7 e bicarbonato de\n\n13. O estudo urodinâmico evidenciou capacidade cistométrica máxima de 100 mL, resíduo urinário\nde 60 mL, pressão de perda de 50 cm H?O, com\npresença de contrações não inibidas a partir de\n50 mL, e complacência diminuída. Qual é conduta MAIS correta para esse caso?","options":{"A":"Encaminhamento para transplante renal.","B":"Ampliação vesical associada à Mitrofanoff para cateterismo intermitente e à cirurgia de\ncontinência.","C":"Mitrofanoff para cateterismo intermitente.","D":"Ampliação vesical associada à Mitrofanoff para cateterismo intermitente"},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-151016","number":"151016","sourceNumber":"151016","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente de 75 anos com queixa de anemia e dor costal à direita. Radiografia de\ncostelas, crânio e coluna lombar evidenciando lesões líticas. Eletroforese de proteínas com pico\nmonoclonal. Considerando o diagnóstico mais provável, assinale a alternativa CORRETA:","options":{"A":"A dor decorrente da infiltração óssea piora principalmente à noite e deve ser tratada\ninicialmente\ncom uso de anti-inflamatórios.","B":"A proteinúria apresentada pelo paciente é à custa de cadeias leves e não de albuminúria.","C":"A hipergamaglobulinemia confere aos pacientes um aumento da resistência a infecções\nbacterianas e germes capsulados.","D":"A fosfatase alcalina é usualmente normal, mesmo com lesões ósseas extensas, por não haver\natividade osteoblástica."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-151041","number":"151041","sourceNumber":"151041","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A osteoartose é a causa de dor crônica mais comum no idoso. Predomina no sexo\nfeminino e pode afetar praticamente todas as articulações do corpo. Quais as articulações mais\nafetadas por esta doença?","options":{"A":"Joelhos, mãos e vértebras.","B":"Joelho, ombro e cotovelo.","C":"Ombro, mãos e vértebras.","D":"Artelhos, mãos e vértebras."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-107573","number":"107573","sourceNumber":"107573","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente, 72 anos, com queixa de dor em IFP e IFD das mãos, tendo sido encaminhada\npela unidade básica de saúde para avaliação no\nambulatório de reumatologia. Trouxe exames\nsolicitados anteriormente, entre os quais: (VER IMAGEM) Tendo essas informações, qual a\nprincipal hipótese diagnóstica?","options":{"A":"Febre reumática, visto ASLO aumentado.","B":"Lúpus eritematoso sistêmico, visto FAN 1/80 nuclear pontilhado fino.","C":"Artrite reumatoide, visto dor em mãos e fator reumatoide positivo.","D":"Osteoartrite de mãos, visto quadro clínico e perfil epidemiológico da paciente.","E":"Sobreposição de lúpus eritematoso sistêmico e artrite reumatoide."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":["question_bank/media/medcurso/med-cirurgia-med-cir-07/107573.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-106972","number":"106972","sourceNumber":"106972","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem de 43 anos, na sala de urgência, com dor abdominal intensa e dor torácica\nsubesternal há 12 horas (após ingestão de\ngrande quantidade de álcool em uma festa). Antes do\ninício da dor teve vários episódios de vômito. História prévia não é digna de nota e não usa\nmedicamentos. Ao exame clínico, encontra-se desconfortável e ansioso, temperatura de 38,8º C,\nfrequência cardíaca de 120/min, pressão arterial de 120/80 mmHg e frequência respiratória de\n32/min. Pulmões limpos bilateralmente, porém com diminuição dos murmúrios à esquerda.\n\nExame cardíaco revela taquicardia sem outros comemorativos. Abdome sensível à palpação\nepigástrica. Tem leucocitose de 26 mil/mm 3,\nECG de 12 derivações normais, RX de tórax com\nderrame pleural moderado à esquerda, pneumotórax e pneumomediastino à esquerda. Em se\ntratando de uma ruptura esofágica espontânea (Síndrome de Boerhaave), seu próximo passo é:","options":{"A":"Manejo das vias aéreas, respiração e circulação (ABC).","B":"Drenagem torácica à esquerda.","C":"Administração de fluidos e antibiótico de amplo espectro.","D":"Todas as alternativas acima."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-107669","number":"107669","sourceNumber":"107669","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente de 13 anos de idade é por você atendido no PS queixando-se de dor no\ntestículo esquerdo há +/- 2 horas, com início\nagudo. Nega febre, porém relata episódio semelhante\nhá +/- 2 meses com melhora espontânea. Qual a hipótese diagnóstica mais provável e exame\nindicado?","options":{"A":"Orquiepididimite viral - urina I e urocutura.","B":"Torção de testículo - ultrassom dopller colorido do testículo.","C":"Epididimite bacteriana - urina I e urocultura.","D":"Varicocele - ultrassom da bolsa escrotal.","E":"Hérnia encarcerada - ultrassom da bolsa escrotal."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-83450","number":"83450","sourceNumber":"83450","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente, 65 anos, masculino, com quadro de lombalgia há 2 meses, com piora à\nmovimentação. Refere que há 45 dias iniciou paraparesia e há 2 dias está com incapacidade de\nmovimentação de membros inferiores. Você está de plantão no pronto-socorro e faz o primeiro\natendimento do paciente. Escolha a conduta CORRETA:","options":{"A":"Trata-se de lombalgia crônica com sinais de gravidade. Deve-se internar o paciente e solicitar o\nTC de coluna lombar e torácica para\navaliação de compressão\n\nmedular.","B":"Deve-se solicitar TC de coluna lombar e, se normal, iniciar tratamento domiciliar com analgesia.","C":"Trata-se de lombociatalgia e deve-se realizar tratamento com AINE e fisioterapia.","D":"Deve-se considerar a hipótese diagnóstica de espondilite anquilosante, visto tratar-se de\nhomem com lombalgia crônica.","E":"Não é necessário realização de exames complementares, visto tratar-se de lombalgia aguda\ncuja principal etiologia é de origem mecânica."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-64961","number":"64961","sourceNumber":"64961","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"O plantonista de Clínica Médica é chamado para avaliar paciente masculino de 71 anos\ninternado na enfermaria de ortopedia por fratura de L2, sem sintomas compressivos, que está\napresentando anemia (Hb = 7,8 g/dl) e insuficiência renal (creatinina = 2,5 mg/dl). O paciente\nrefere lombalgia intensa e progressiva há seis meses tendo realizado vários tratamentos\nortopédicos sem melhora. Nos últimos dois meses, evolui com fraqueza importante e epistaxes\nrecorrentes. Ao exame físico, apresenta palidez cutâneo-mucosa +++/4+, taquicardia em repouso e\ndor à compressão esternal. O exame radiológico de coluna mostra diminuição de altura com\nacunhamento de várias vértebras lombares e torácicas. Quais achados adicionais são esperados\npara o caso?","options":{"A":"Hipocalcemia, hiperuricemia e pico monoclonal em gamaglobulinas na eletroforese de proteínas.","B":"Lesões em saca-bocados na calota craniana, hipercalcemia e pico policlonal em gamaglobulinas\nna eletroforese de proteínas.","C":"Hipoalbuminemia, hiperuricema e pico policlonal em gamaglobulinas na eletroforese de\nproteínas.","D":"Hipocalcemia, lesões em saca-bocados em calota craniana e aumento dos níveis de IgG sérica.","E":"Hipoalbuminemia, hipercalcemia e pico monoclonal em gamaglobulinas na eletroforese de\nproteínas."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-64874","number":"64874","sourceNumber":"64874","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Na hematúria macroscópica com coágulos, qual é atitude mais correta do plantonista\nclínico?","options":{"A":"Sondagem vesical e irrigação.","B":"Sondagem vesical somente.","C":"Vitamina K endovenosa.","D":"Solicitar ultrassom.","E":"Cirurgia endoscópica."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-45902","number":"45902","sourceNumber":"45902","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente de 60 anos procura atendimento no ambulatório queixando-se de dores\nósseas localizadas em 1/3 médio de úmero direito e\ndor lombar baixa com irradiação e parestesia\nem membro inferior esquerdo. Relata ainda adinamia, astenia, emagrecimento de 5 Kg, formação\nde hematomas em MMII. Nega febre ou adenomegalias. Trouxe exames: creatinina 1,9 mg/dl,\ncálcio 11 mg/dl, hemoglogina 9,6 g/100 ml, imunofixação com elevação de imunoglobulina G no\nsoro. Qual diagnóstico mais provável e qual exame ajudaria a confirmá-lo?","options":{"A":"Leucemia mieloide crônica e mielograma com hipocelularidade com hipoplasia mieloide.","B":"Leucemia linfocítica crônica e contagens linfocitárias absolutas acima de 2.000/µL no sangue\nperiférico.","C":"Linfoma de Hodgkin e biópsia de linfonodo com observação de grandes células anaplásicas.","D":"Macroglobulinemia de Waldenström e mielograma com infiltração de neutrófilos.","E":"Mieloma múltiplo e mielograma com 10% ou mais de células plasmáticas."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-45529","number":"45529","sourceNumber":"45529","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"No Mieloma Múltiplo, a causa mais comum de insuficiência renal se deve a:","options":{"A":"Infiltração de plasmócitos no rim.","B":"Hiperuricemia.","C":"Depósito de proteína monoclonal (amiloidose).","D":"Hipocalcemia.","E":"Nefrite intersitical aguda."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-22624","number":"22624","sourceNumber":"22624","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"O que causa a dor associada a um cálculo no ureter?","options":{"A":"Obstrução do fluxo urinário com distensão da cápsula renal","B":"Irritação da mucosa ureteral causada pelo cálculo.","C":"Peristalse ureteral excessiva em resposta à obstrução do cálculo.","D":"Irritação do ureter intramural.","E":"Extravasamento urinário de um fórnice do cálice com rotura."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-25691","number":"25691","sourceNumber":"25691","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Quando indicado a antibioticoterapia na pancreatite aguda grave, qual dos seguintes é\na primeira escolha?","options":{"A":"Imipenem","B":"Cefalotina","C":"Metronidazol","D":"Amicacina","E":"Ceftriaxone"},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-25743","number":"25743","sourceNumber":"25743","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Entre os seguintes tipos de infecção hospitalar, qual é a mais comum:","options":{"A":"Diarreia associada a antibióticos","B":"Bacteremia associada a cateter intravenoso","C":"Infecções de escaras","D":"Infecção do trato urinário","E":"Infecção de sítio cirúrgico"},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-330501","number":"330501","sourceNumber":"330501","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Mulher de 29 anos queixa-se de lombalgia esquerda iniciada no dia anterior, após a\nrealização de exercícios físicos intensos. Relata que a dor irradia pela região lateral da coxa\nesquerda até o pé e apresenta intensidade 4/10. Nega outros sintomas, incluindo febre,\nanormalidades intestinais ou urinárias. Nega comorbidades conhecidas. Ao exame físico, o teste de\nelevação da perna esquerda reproduz a dor do mesmo lado, e o teste com a perna direita não\ndesencadeia nenhuma dor. O exame neurológico não apresenta anormalidades. Assinale a\nalternativa que apresente a causa MAIS PROVÁVEL do quadro clínico apresentado por essa\npaciente e a conduta MAIS ADEQUADA:","options":{"A":"Estenose do canal vertebral; nenhuma propedêutica de imagem","B":"Estenose do canal vertebral; VHS e ressonância magnética da coluna lombar","C":"Hérnia discal; nenhuma propedêutica de imagem","D":"Hérnia discal; ressonância magnética da coluna lombar"},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-301223","number":"301223","sourceNumber":"301223","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Mulher de 76 anos apresenta emagrecimento, dor lombar, astenia e dispneia aos\nesforços. Desconhece comorbidades prévias, nega\ntabagismo, etilismo ou uso de medicamentos.\nAo exame, as mucosas estão descoradas; sem outras anormalidades. Exames de laboratório: Hb\n7,3 g/dl; LG 6.500/mm³; Plq 112.000/mm³; VHS 95 mm na primeira hora; creatinina 2,2 mg/dl; ureia\n47 mg/dl; cálcio total 10,6 g/dl; albumina sérica 2,0 g/dl; LDH 450 UI/L; BT 0,9 mg/dl. A\nhematoscopia revelou o seguinte achado: Considerando o diagnóstico mais provável para essa\npaciente, assinale a alternativa que apresenta o(s) exame(s) MAIS ADEQUADO(S) a ser(em)\nsolicitado(s) nesse momento:","options":{"A":"Eletroforese de proteínas séricas e urinárias.","B":"Endoscopias do trato digestivo alto e baixo.","C":"Pesquisa do cromossomo Philadelphia.","D":"Teste de fragilidade osmótica de eritrócitos."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-233828","number":"233828","sourceNumber":"233828","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um homem de 70 anos queixa-se de dor em queimação no pescoço e no braco\nesquerdo. Relata ainda urgência e esforço\nmiccional, jato urinário reduzido, sensação de\nesvaziamento vesical incompleto após micção, além de dificuldade para deambular. Nega\ncomorbidades ou uso de medicamentos. Ao exame físico, apresenta PA 120/70mmHg, FC 80bpm,\nFR 13irpm, SpO? em ar ambiente 97%. Encontra-se alerta, orientado, corado e anictérico. O exame\ndos membros superiores mostra fraqueza à flexão do cotovelo e à abdução do ombro esquerdos,\ncom hiporreflexia bicipital ipsilateral. A força nos membros inferiores está reduzida de forma\nsimétrica, observando-se bilateralmente espasticidade, hiperreflexia patelar e reflexo\n\ncutâneo-plantar extensor. Há perda da propriocepção. A marcha é espástica com passos altos e\nfortes. A propedêutica imediata MAIS INDICADA na investigação diagnóstica nesse caso é a:","options":{"A":"ressonância magnética da coluna cervical.","B":"ressonância magnética da coluna torácica.","C":"tomografia computadorizada da coluna lombar.","D":"tomografia computadorizada do crânio."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-233829","number":"233829","sourceNumber":"233829","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um homem de 70 anos queixa-se de dor em queimação no pescoço e no braco\nesquerdo. Relata ainda urgência e esforço\nmiccional, jato urinário reduzido, sensação de\nesvaziamento vesical incompleto após micção, além de dificuldade para deambular. Nega\ncomorbidades ou uso de medicamentos. Ao exame físico, apresenta PA 120/70mmHg, FC 80bpm,\nFR 13irpm, SpO? em ar ambiente 97%. Encontra-se alerta, orientado, corado e anictérico. O exame\ndos membros superiores mostra fraqueza à flexão do cotovelo e à abdução do ombro esquerdos,\ncom hiporreflexia bicipital ipsilateral. A força nos membros inferiores está reduzida de forma\nsimétrica, observando-se bilateralmente espasticidade, hiperreflexia patelar e reflexo\n\ncutâneo-plantar extensor. Há perda da propriocepção. A marcha é espástica com passos altos e\nfortes. Assinale o diagnóstico etiológico MAIS PROVÁVEL nesse caso.","options":{"A":"Esclerose lateral amiotrófica","B":"Espondilopatia compressiva","C":"Hidrocefalia de pressão normal.","D":"Mielopatia esquistossomótica"},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-141260","number":"141260","sourceNumber":"141260","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem de 30 anos com história recente de diarreia invasiva, caracterizada pela\npresença de sangue nas fezes e febre, evolui\ncom oligoartrite periférica e entesite falangeana. Qual\né o diagnóstico MAIS PROVÁVEL?","options":{"A":"Artrite reativa","B":"Artrite séptica","C":"Doença de Crohn","D":"Síndrome de Behçet"},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-71472","number":"71472","sourceNumber":"71472","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem de 27 anos comparece à consulta para avaliação de dor lombar persistente\nassociada à rigidez, que surgiram\ninsidiosamente há três anos. Os sintomas pioram com repouso\nprolongado. Tem história de episódio de inflamação aguda no olho esquerdo, que foi tratada por\noftalmologista. Ao exame, trata-se de homem negro com hipersensibilidade à palpação das\narticulações sacroilíacas e teste de Schober normal. Qual dos seguintes procedimentos poderia\nconfirmar o diagnóstico?","options":{"A":"Dosagem sérica do fator reumatoide.","B":"Pesquisa de HLA-B27.","C":"Radiografia das articulações sacroilíacas.","D":"Dosagem sérica do ácido úrico."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-60342","number":"60342","sourceNumber":"60342","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Em face da ressonância magnética abaixo reproduzida, esperar-se-iam os seguintes\nachados ao exame clínico de paciente com lombociatalgia aguda: (VER IMAGEM)","options":{"A":"Reflexo aquileu diminuído ou abolido, marcha na ponta dos pés dificultada.","B":"Reflexo aquileu diminuído ou abolido, marcha sobre os calcanhares dificultada.","C":"Reflexo aquileu preservado, marcha na ponta dos pés dificultada.","D":"Reflexo aquileu preservado, marcha sobre os calcanhares dificultada."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":["question_bank/media/medcurso/med-cirurgia-med-cir-07/60342.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-53321","number":"53321","sourceNumber":"53321","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem de 27 anos comparece à consulta para avaliação de dor lombar persistente,\nassociada à rigidez, que surgiu insidiosamente há três anos. Os sintomas pioram com repouso\nprolongado. Tem história de episódio de inflamação aguda no olho esquerdo, que foi tratada por\noftalmologista. Ao exame, trata-se de homem negro com hipersensibilidade à palpação das\narticulações sacroilíacas e teste de Schober normal. Qual dos seguintes procedimentos poderia\nconfirmar o diagnóstico?","options":{"A":"Dosagem sérica do fator reumatoide","B":"Pesquisa de HLA-B27","C":"Radiografia das articulações sacroilíacas","D":"Dosagem sérica do ácido úrico"},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-55330","number":"55330","sourceNumber":"55330","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente deu entrada no Pronto Atendimento queixando-se de dor em cólica, intensa,\niniciada no flanco D e, posteriormente,\nlocalizada no quadrante inferior direito do abdome,\nacompanhada de polaciúria e urina avermelhada. Radiografia simples do abdome mostrou imagem\nsugestiva de cálculo na projeção do ureter proximal, de 0,6 cm no seu maior diâmetro.\n\nUltrassonografia do trato urinário evidenciou discretas anormalidades pielocalicinais. O paciente\nfoi\ntratado com anti-inflamatório e analgésico, com alívio da dor. Qual seria, a seguir, a conduta mais\nacertada neste caso?","options":{"A":"Encaminhamento imediato para Litotripsia Extracorpórea por Ondas de Choque (LECO), dadas\nas dimensões do cálculo","B":"Encaminhamento imediato para ureterolitotomia a céu aberto, dada a localização do cálculo","C":"Tratamento conservador e observação por até 4 semanas antes de qualquer intervenção\nurológica, dada a possibilidade de eliminação espontânea do cálculo","D":"Estudo metabólico para diagnóstico do distúrbio primário da litogênese para tratamento clínico\nespecífico e posterior encaminhamento para LECO"},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-31490","number":"31490","sourceNumber":"31490","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem de 38 anos, metalúrgico. Queixa-se de dor lombar baixa que se estende para a\nregião das nádegas, de apresentação súbita pela manhã e com quatro dias de evolução. Nega\ntrauma, febre, emagrecimento. Sem outras queixas. Ao exame encontra-se afebril, corado, com\nsobrepeso (IMC = 27). O exame da coluna evidencia escoliose antálgica e dor à palpação da\nmusculatura paravertebral bilateral. Sem alteração da marcha, dos reflexos osteotendinosos\nprofundos e da força muscular nos membros inferiores. Em relação ao caso descrito, NÃO\npodemos afirmar:","options":{"A":"A orientação de repouso associada ao uso de acetaminofeno ou anti-inflamatório não hormonal\nestá bem indicada até o retorno do paciente.","B":"A persistência da dor por três meses, associada ao aumento da sua intensidade e\ndesenvolvimento de rigidez matinal, sugere o diagnóstico de espondiloartrite.","C":"Deve-se solicitar, nesta primeira consulta, radiografia de coluna lombar nas incidências\nanteroposterior e perfil para esclarecimento do diagnóstico.","D":"O exame clínico minucioso deste paciente tem acurácia elevada para definição etiológica de sua\nqueixa."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-369727","number":"369727","sourceNumber":"369727","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem de 54 anos apresenta quadro de dor lombar súbita, intensa, à esquerda, com\nGiordano positivo. Enfermagem refere que houve febre, está hipotenso e taquicardico. A tomografia\nmostra cálculo em ureter esquerdo com hidronefrose. A conduta apropriada neste momento é:","options":{"A":"Antibioticoterapia de largo espectro para gram negativo","B":"Ureterolitotripsia esquerda com colocação de duplo J + antibioticoterapia","C":"Ureterolitotripsia esquerda sem colocação de duplo J + antibioticoterapia","D":"Nefrostomia percutânea esquerda sem antibioticoterapia"},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-372268","number":"372268","sourceNumber":"372268","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Quanto a característica do cálculo urinário mais favorável para o tratamento com\nlitotripsia extracorpórea, assinale a alternativa CORRETA.","options":{"A":"Densidade 1000 ? 1300 unidades.","B":"Composição de cistina.","C":"Localização em cálice inferior.","D":"Localização em ureter médio.","E":"5 a 10 mm de diâmetro."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-340740","number":"340740","sourceNumber":"340740","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Alguns pacientes portadores de ureterolitíase distal se beneficiam da terapia médica\nexpulsiva conservadora. Assinale a alternativa com uma droga que tenha caráter expulsivo nestes\ncasos.","options":{"A":"Anlodipino.","B":"Clonidina.","C":"Enalapril.","D":"Tansulosina."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-340741","number":"340741","sourceNumber":"340741","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"O trato urinário é um local comum para anomalias congênitas de importância variada. A\nanomalia de fusão renal mais comum é:","options":{"A":"Ectopia renal cruzada.","B":"Rim ?em ferradura?.","C":"Rim ?em panqueca?.","D":"Rim pélvico ligado."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-311268","number":"311268","sourceNumber":"311268","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Assinale a alternativa que apresenta um critério de exclusão para o diagnóstico de\nMielite Transversa.","options":{"A":"Inflamação da medula espinhal demonstrada por pleocitose do liquor, lgG elevada ou captação\nde gadolínio.","B":"Áreas anormais de ausência de sinal na superfície medular na RM, compatível com malformação\narteriovenosa.","C":"História de neurite óptica clinicamente evidente.","D":"Evolução até o nadir clínico dentro de 4 horas a 21 dias desde o início dos sintomas."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-301021","number":"301021","sourceNumber":"301021","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um paciente com mieloma múltiplo recém-diagnosticado, mas ainda virgem de\ntratamento, dá entrada no pronto-socorro com\no seguinte quadro: rebaixamento do nível de\nconsciência, desidratação, distensão abdominal e redução dos ruídos hidroaéreos e insuficiência\nrenal aguda. Familiar relata que o quadro teve evolução progressiva nos últimos dias, sendo que,\nno início, o paciente estava apresentando diurese muito abundante, que posteriormente se reduziu,\nassociado ao agravamento dos outros sintomas. Qual é a provável etiologia do quadro?","options":{"A":"Síndrome de lise tumoral.","B":"Metástase para o sistema nervoso central.","C":"Hipercalcemia.","D":"Síndrome de hiperviscosidade."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-266560","number":"266560","sourceNumber":"266560","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente mulher de 25 anos com quadro de dor abdominal há cerca de 6 horas, iniciado\nem flanco direito e agora em fossa ilíaca\ndireita. Episódio de vômitos associado no início do quadro.\nNega passado mórbido e data da última menstruação há 20 dias. Não usa qualquer medicamento e\ntem relação protegida com seu namorado. Ao exame, dor importante em FID irradiado para raiz da\ncoxa e vagina. Sem irritação peritoneal neste momento. Exames mostraram: Hemograma:\nLeucócitos: 12.300/µL (S 75% B 4% M 15%), Hb: 14g/dl, plaquetas: 150.000. Amilase: 90 U/L (VR\n20?110 U/L) BHCG: negativo; Urina rotina: piócitos: 2 p/c; hemácias 50 p/c; nitrito negativo; flora\nnormal; RX tórax PA (ortostatismo): normal; RX abdômen ortostatismo e decúbito a seguir:\nConsiderando o caso descrito, é CORRETO afirmar que:","options":{"A":"A presença de leucocitose e apagamento da sombra do psoas apresentado na imagem\ncorrobora a suspeita de apendicite aguda nesse quadro clínico.","B":"O provável diagnóstico deve ser uma ureterolitíase direita apesar de não aparecer no Rx de\nabdômen.","C":"A suspeita desse caso deve ser uma gravidez ectópica rota.","D":"A presença do sinal de Rigler nesse Rx confirma diagnóstico de úlcera perfurada."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-260539","number":"260539","sourceNumber":"260539","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A manifestação extra-articular mais comum de espondilite anquilosante é:","options":{"A":"Uveíte anterior.","B":"Estenose aórtica.","C":"Amiloidose.","D":"Fibrose pulmonar."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-260542","number":"260542","sourceNumber":"260542","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"No mieloma múltiplo:","options":{"A":"Sem proteinúria, não há risco para desenvolvimento de insuficiência renal aguda.","B":"Hipercalcemia, eventualmente observada, seria secundária à insuficiência renal aguda.","C":"Há predisposição a infecções por bactérias encapsuladas devido a imunodeficiência humoral\npredominante.","D":"O principal achado do hemograma é a presença de plasmócitos."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-287635","number":"287635","sourceNumber":"287635","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Assinale a alternativa correta sobre a radiografia simples de abdome abaixo.","options":{"A":"Trata-se de uma urografia excretora: exame contrastado para fundamental para se avaliar\nanatomia do trato urinário superior e\n\ninferior","B":"Trata-se de uma cistouretrografia retrógrada miccional: exame contrastado útil nas avaliações de\nrefluxo vesicoureteral.","C":"Trata-se de uma pielografia ascendente: exame para se avaliar estenose da junção\nureteropiélica.","D":"Trata-se de uma radiografia simples de abdome que evidencia os sítios de cateteres de\nderivação pielovesical."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-287637","number":"287637","sourceNumber":"287637","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente feminina, 39 anos, procura o consultório do urologista com antecedentes de\nvárias infecções urinárias desde o início da vida sexual. Queixa-se de dor lombar esquerda crônica.\nÉ tabagista e diabética. Realizou uma urotomografia, sem contraste, que evidenciou cálculo de 2,4\ncentímetros em cálice renal inferior, do lado esquerdo, com densidade de 1.200 Unidades\nHounsfield, com distância pele-cálculo de 7 centímetros, sem ureterohidronefrose, com boa\ndiferenciação corticomedular do parênquima renal. A melhor opção terapêutica neste caso é:","options":{"A":"Nefrolitotripsia percutânea.","B":"Nefrectomia esquerda.","C":"Ureterolitotripsia endoscópica flexível com laser.","D":"Litotripsia extracorpórea."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-287638","number":"287638","sourceNumber":"287638","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"São chamados de ?cálculos de infecção? e formados por um complexo de magnésio,\namônia, fosfato e carbonato de cálcio. Algumas\nbactérias como Proteus ssp e Klebsiella ssp deixam\no pH da urina alcalino e favorecem a formação de tais cálculos. Trata-se dos cálculos de:","options":{"A":"Oxalato de cálcio.","B":"Estruvita.","C":"Carbonato de cálcio.","D":"Indinavir"},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-262942","number":"262942","sourceNumber":"262942","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Geralmente não é causa de nefropatia obstrutiva:","options":{"A":"Duplicação congênita do trato urinário.","B":"Tuberculose reno-ureteral.","C":"Tumor renal.","D":"Nefrolitíase."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-260605","number":"260605","sourceNumber":"260605","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Em relação a nefrolitíase e cálculos de cálcio marque a alternativa ERRADA:","options":{"A":"A hipercalciúria e a hipocitraturia são os fatores de risco mais envolvidos.","B":"A restrição da ingestão de cálcio em pacientes formadores de cálculos renais de cálcio deve ser\nestimulada.","C":"Pacientes portadores de hiperparatireoidismo estão sobre risco de desenvolver cálculos de\ncálcio.","D":"O uso de colestiramina e/ou cálcio oral diminui a formação de cálculos de cálcio em pacientes\nportadores de hiperroxalúria."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-239821","number":"239821","sourceNumber":"239821","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente de 80 anos, sexo masculino, comparece a unidade básica de saúde com\nqueixa de lombalgia, que piora ao movimento,\niniciada há cerca de 2 meses. Informa diagnóstico\nrecente de anemia. Não está em uso de medicações. Trouxe resultado de exames solicitados há\numa semana: Hemoglobina = 10,2 g/dL (VR: 11.3 a 16.3); VCM = 85 FL (VR: 77 a 92); HCM = 30\npg (VR: 27 a 32); Global de leucócitos = 6200/ml (VR = 4.000 a 10.000/ml); Neutrófilos = 50% (VR:\n45 a 75%); Linfócitos = 35 % (VR = 22 a 40%); Monócitos = 9% (VR: 3 a 10%); Eosinófilos = 5%\n\n(VR: 1 a 5%); Basófilos = 1% (VR: 0 a 2%); Plaquetas: 150.000/ml (VR: 130.000 a 370.000/ml);\n\nReticulócitos = 0,4% (VR: 0,5 a 2,17%); Ferro sérico = 80 mcg/dl (VR: 60 a 160); Ferritina = 150\n(VR: 13 a 200 ng/ml); Capacidade total de\nligação do ferro (TIBIC) = 300 mcg/dl (VR: 240 a 410);\nCreatinina = 2,6 mg/dL ( VR: 0,6-1,2 mg/dL) e uréia = 50 mg/dL (VR: 16-40 mg/dL). Albumina 3,6\ng/dL (VR: 3,5-4,7 g/dL); Cálcio total = 13,2 (VR: 8,5-10,2 mg/dL). Assinale a alternativa que contém\no diagnóstico mais provável:","options":{"A":"Hiperparatireoidismo primário.","B":"Mieloma múltiplo.","C":"Artrite reumatoide.","D":"Osteoartrose."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-254996","number":"254996","sourceNumber":"254996","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A Osteoartrite (OA), também conhecida como Osteoartrose, representa uma falência\narticular com perda da cartilagem hialina, com\nalta prevalência em idosos e alta taxa de\nincapacitação. Sobre esta patologia, analise as afirmativas a seguir e marque a opção correta. I. O\nparacetamol é a droga de escolha inicial para controle da dor. II. Rigidez matinal maior que 1 hora\ne\nnódulos subcutâneos são critérios diagnósticos. III. Nos quadros de OA grave das mãos surgem\nnódulos de Heberden nas articulações interfalangianas distais e nódulos de Bouchard nas\ninterfalangianas proximais. IV. Aplicações de glicocorticoides intra-articulares são alternativas\npara\nalguns pacientes, sendo eficazes em reduzir a dor, pelo menos temporariamente.","options":{"A":"Estão corretas apenas as afirmativas I e III.","B":"Estão corretas apenas as afirmativas I, III e IV.","C":"Estão corretas apenas as afirmativas III e IV.","D":"Estão corretas apenas as afirmativas II e IV.","E":"Todas as afirmativas estão corretas."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-239828","number":"239828","sourceNumber":"239828","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente F.G.B., sexo masculino, 27 anos, apresenta lombalgia intensa que o acorda\ndurante a noite, piora em repouso e\nmelhora com exercício, além de rigidez matinal de 60 minutos.\nEvoluiu com hiperemia conjuntival e calcaneodinia. Ao exame físico sopro diastólico em foco\naórtico. Lasègue negativo. Proteína C-reativa 27,5 (VR < 10) e VHS (hemossedimentação) 49. Qual\na principal hipótese diagnóstica?","options":{"A":"Nefrolitíase.","B":"Hérnia discal.","C":"Doença de Whipple.","D":"Espondilite anquilosante."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-239896","number":"239896","sourceNumber":"239896","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A dor lombar é uma das queixas mais frequentes da prática do médico generalista.\nSobre este tema, assinale a alternativa correta:","options":{"A":"A radiografia da coluna lombar não está indicada na avaliação inicial da pessoa com suspeita de\nlombalgia mecânica.","B":"As lombalgias decorrentes de causas sistêmicas são mais frequentes que as decorrentes de\ncausas mecânicas.","C":"O uso de corticosteroides injetáveis é indicado nas lombalgias em que não há sinais de\ncompressão de raiz nervosa.","D":"Nas lombalgias mecânicas, o espasmo da musculatura paravertebral é pouco frequente."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-217164","number":"217164","sourceNumber":"217164","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente com dor lombar decorrente de obstrução ureteral e hidronefrose é internada\npara ureterolitotripsia e colocação de duplo-J.\nDurante a internação evolui com sinais de sepse de\nfoco urinário. A respeito do quadro pode-se afirmar que:","options":{"A":"Está contraindicada a cirurgia no momento. Deve-se instituir antibioticoterapia por 72 horas.","B":"A indicação de cirurgia com desobstrução ureteral é precípua, mas está contraindicada a\ncolocação de duplo-J.","C":"A indicação de cirurgia com desobstrução ureteral é precípua, não estando contraindicada a\ncolocação de duplo-J.","D":"A abordagem por nefrostomia é a única indicada."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-217204","number":"217204","sourceNumber":"217204","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Qual é a causa metabólica mais comum de cálculo urinário pediátrico?","options":{"A":"Uso prolongado de diuréticos.","B":"Disfunção tubular renal.","C":"Hipercalciúria.","D":"Excesso de vitamina D."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-182026","number":"182026","sourceNumber":"182026","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A hérnia de disco lombar é uma doença degenerativa que ocorre ao longo da vida,\nlevando a dor e a incapacidade em grande\nparte da população mundial. Sendo uma doença de alta\nprevalência e alta incidência, porém de tratamento conservador em 95% dos casos. O tratamento\ncirúrgico deve ser específico para o disco causador da dor e isso é fácil, devido a correlação\nanatômica. Portanto se um paciente com uma hérnia de disco na localizado entre a vértebras L3\n(terceira vértebra lombar) e L4 ( quarta vértebra lombar) apresentará as seguintes alterações:","options":{"A":"Alteração da raiz se L3, com dores nas regiões da coluna lombar e face medial de coxa. Reflexo\npatelar diminuído ou ausente, atrofia dos adutores do quadril.","B":"Dores nas regiões da coluna lombar, quadril e face anterior de perna. Fraqueza na extensão de\njoelho, atrofia do quadríceps e reflexo patelar ausente ou diminuído.","C":"Dores nas regiões sacroilíaca, quadril, póstero-lateral da coxa e antero-lateral da perna,\nfraqueza na dorsiflexão do hálux e alteração da sensibilidade lateral da perna.","D":"Dores nas regiões da sacroilíaca, quadril e posterior de coxa. Sensibilidade diminuída na região\nposterior da perna e lateral do pé e reflexo Aquileu diminuído ou ausente."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-181970","number":"181970","sourceNumber":"181970","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem de 43 anos de idade dá entrada no setor de emergência com quadro de dor\nlombar súbita a direita, Giordano positivo a\ndireita. Há hipertermia, taquicardia, hipotensão arterial e\nleucocitose com desvio a esquerda, além de PCR de 150. A urotomografia mostra calculo\nimpactado em ureter proximal direito com hidronefrose a montante. A respeito da melhor conduta:","options":{"A":"Antibioticoterapia de largo espectro para tratamento do choque séptico. Operar após controle do\nquadro infeccioso.","B":"Antibioticoterapia concomitante a desobstrução do ureter (ureterolitotripsia + implante de\nduploJ).","C":"Cirurgia imediata (ureterolitotripsia + implante de duploJ) com determinação da necessidade de\nantibioticoterapia após verificação da presença ou não de secreção purulenta em vias urinárias.","D":"Nefrostomia percutânea prescinde de antibioticoterapia."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-184606","number":"184606","sourceNumber":"184606","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um homem de 30 anos teve dor abdominal intermitente nos últimos 3 dias. Começa no\nlado esquerdo e desce até a virilha. Ele também sentiu náuseas e acha que é difícil ficar quieto.\n\nQual a analgesia mais apropriada?","options":{"A":"Codeína 60 mg.","B":"Diclofenaco 100 mg.","C":"Morfina 10mg.","D":"Meperidina 150 mg."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-181291","number":"181291","sourceNumber":"181291","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Na nefrolitíase, cálculos de oxalato de cálcio são os mais comuns. Constitui uma\nmedida potencialmente útil na prevenção desses cálculos:","options":{"A":"dieta restrita em cálcio visando reduzir a calciúria.","B":"diurético de alça para aumentar o fluxo urinário.","C":"suplementação de vitamina C.","D":"restrição de sódio da dieta."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-157990","number":"157990","sourceNumber":"157990","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A associação de anemia, hipercalcemia, insuficiência renal e fraturas patológicas são\ncaracterísticas de:","options":{"A":"Deficiência de vitamina D.","B":"Mieloma múltiplo.","C":"Linfoma de Hodgkin.","D":"Melanoma."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-158240","number":"158240","sourceNumber":"158240","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente 39 anos dá entrada no setor de emergência com dor lombar intensa a direita\nirradiando para região inguinal ipsilateral. Giordano positivo a direita, hematúria, taquicardia e\nsudorese profusa. A respeito da analgesia podemos afirmar:","options":{"A":"A melhor opção inclui meperidina e dexmedetomidina;","B":"Morfina é melhor que meperidina, podendo-se associar antiespasmódicos e anti-inflamatórios;","C":"Antiespasmódico e anti-inflamatório são as melhores opções devendo-se evitar morfina pelo\nrisco de vício;","D":"Deve-se evitar morfina para que se possa avaliar a progressão da dor e com isso a progressão\ndistal do provável cálculo."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-131781","number":"131781","sourceNumber":"131781","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"João, 53 anos, chega ao hospital queixando-se de dor no flanco direito há duas\nsemanas. Ele relata ter notado um pouco de\nhematúria macroscópica e não consegue comer nada\ndevido à náusea e vômitos. Qual das alternativas representa uma indicação para internação\nhospitalar? Assinale a alternativa CORRETA:","options":{"A":"Hematúria macroscópica.","B":"Dor no flanco direito.","C":"Náusea e vômitos, mesmo com o uso de antieméticos.","D":"Idade acima de 50 anos.","E":"Presença de um cálculo renal de 6 mm."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-129519","number":"129519","sourceNumber":"129519","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Na abordagem e tratamento da nefrolitíase, em suas diversas causas, podem ser\nindicadas as seguintes recomendações, EXCETO:","options":{"A":"Suplementação com álcalis.","B":"Uso de diuréticos tiazídicos.","C":"Evitar desidratação e manter ingesta hídrica abundante.","D":"Restrição da ingesta de cálcio na dieta."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-136689","number":"136689","sourceNumber":"136689","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A associação de anemia, hipercalcemia, insufiência renal e fraturas patológicas são\ncaracterísticas de:","options":{"A":"Deficiência de vitamina D.","B":"Mieloma múltiplo.","C":"Linfoma de Hodgkin.","D":"Carcinoma papilífero da tiróide."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-135591","number":"135591","sourceNumber":"135591","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente de 65 anos de idade apresenta esforço miccional, jato urinário fraco e\ninterrompido e esvaziamento incompleto da\nbexiga, mas também urgência urinária e polaciúria,\nalém de nictúria. Não há relato de retenção urinária com necessidade de cateterismo vesical de\nalívio. O toque retal e a ultrassonografia mostram uma próstata aumentada de volume, mas não há\nnódulos. O valor do PSA é discretamente aumentado. A respeito do tratamento adequado para esta\nnosologia, podemos afirmar:","options":{"A":"A finasterida (anti-androgênico) não tem valor e pode piorar a performance erétil.","B":"A doxazocina (alfa-adrenérgico) é mais segura que a finasterida em pacientes com\nantecedentes de coronariopatia, acidente\nvascular encefálico e insuficiência vascular periférica.","C":"O tratamento cirúrgico constitui-se na forma mais eficiente de tratamento.","D":"A braquiterapia apresenta melhores resultados a longo prazo."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-105990","number":"105990","sourceNumber":"105990","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente com litíase ureteral à direita apresentou cólica nefrética intensa, febre,\nleucocitose com desvio à esquerda, frequência\ncardíaca de 110 bpm e frequência respiratória de 28\nirpm. A urotomografia mostrou um cálculo em terço superior de ureter de 1,1 cm, hidronefrose\nconcomitante e borramento da gordura perirrenal. Podemos afirmar que:","options":{"A":"É um cálculo pequeno que ainda se encontra em terço superior e pode descer e ser eliminado.\n\nNão há necessidade de procedimento operatório algum.","B":"Paciente em risco de sepse, há necessidade de desobstruir as vias urinárias para controle do\nquadro infeccioso além da antibioticoterapia.","C":"Apesar de o cálculo ser grande, o tratamento clínico se faz necessário como melhor opção e\nantibioticoterapia venosa por 7 dias para controlar o quadro infeccioso antes do tratamento\noperatório.","D":"Somente há necessidade de tratamento clínico."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-105419","number":"105419","sourceNumber":"105419","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente do sexo masculino, obeso e diabético, com dor lombar esquerda em cólica,\nirradiando para a região genital. Diante da hipótese diagnóstica mais provável, assinale a\nalternativa CORRETA:","options":{"A":"Radiografia simples de abdome e exame de urina são padrão-ouro para o diagnóstico.\n\nUreteroscopia semirrígida para o tratamento dos cálculos de ureter distal.","B":"TC sem contraste é o padrão-ouro no diagnóstico da litíase urinária. A nefrolitotripsia\npercutânea\né o melhor método para o tratamento de\ncálculos renais maiores que 2 cm.","C":"Ultrassonografia é o padrão-ouro no diagnóstico da litíase urinária. A ureteroscopia flexível é\numa alternativa para cálculos de ureter superior\ne renais menores que 1,5 cm que não respondem à\nlitotripsia extracorpórea.","D":"Ressonância magnética é o padrão-ouro para diagnóstico da litíase urinária. A litotripsia\nextracorpórea é o método de eleição em nosso\nmeio para tratamento de cálculos renais menores\nque 2 cm e com densidade < 1.000 UH."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-120737","number":"120737","sourceNumber":"120737","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um homem de 38 anos de idade, saudável, apresenta história de nefrolitíase recorrente\nnos últimos 3 anos. Uma coleta de urina de 24\nhoras recente mostrou os seguintes achados:\ncalciúria de 480 mg (normal até 350 mg); uricosúria de 440 mg (normal até 800 mg) e citratúria de\n643 mg (normal maior que 320 mg). Qual das seguintes opções medicamentosas seria mais eficaz\npara o tratamento de seu distúrbio metabólico urinário causador da nefrolitíase?","options":{"A":"Espironolactona.","B":"Hidroclorotiazida.","C":"Furosemida.","D":"Alopurinol.","E":"Citrato de potássio."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-89143","number":"89143","sourceNumber":"89143","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Dor lombar aguda com irradiação para nádega, região posterior da coxa e perna\nacompanhada de parestesia em planta do pé, após esforço em um indivíduo jovem, sugere:","options":{"A":"Hérnia discal com compressão de L5.","B":"Espondilodiscite.","C":"Síndrome facetária.","D":"Hérnia discal com compressão em S1."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-81099","number":"81099","sourceNumber":"81099","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A hematúria pode ser monossintomática ou estar associada a várias doenças. De\nacordo com seus conhecimentos sobre hematúria,\nassinale a alternativa que contenha a afirmativa\nCORRETA.","options":{"A":"A presença de células G1 no sedimento urinário não tem valor preditivo para determinar se a\nhematúria é glomerular ou não glomerular.","B":"Hematúria associada a coágulos sanguíneos indica lesão do trato urinário inferior.","C":"Hipercalciúria e hiperuricosúria idiopáticas não aparecem como causas de hematúria\nmonossintomática em crianças.","D":"A causa mais comum de hematúria na criança é a glomerulonefrite pós-infecciosa."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-86033","number":"86033","sourceNumber":"86033","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um paciente é internado com quadro de cólica nefrítica severa. O RX simples de\nabdome é normal, mas o ultrassom mostra\ncálculo com 2 cm de diâmetro na pelve renal direita. A\ncomposição mais provável do cálculo é:","options":{"A":"Oxalato de cálcio.","B":"Cistina.","C":"Ácido úrico.","D":"Fosfato amoníaco magnesiano."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-60806","number":"60806","sourceNumber":"60806","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Marque a alternativa CORRETA:","options":{"A":"S. pneumoniae e H. influenzae estão entre os patógenos mais comumente causadores de\npneumonia adquirida na comunidade e em\npacientes internados (ambiente hospitalar), mas não em\npacientes em UTIs (Tratamento Intensivo).","B":"As heparinas de baixo peso molecular têm meia-vida curta e ação completamente reversível\ncom protamina.","C":"Em um estudo espirométrico, o achado de VEF1/CVF% reduzido e VEF1% reduzido sugerem\ndistúrbio ventilatório restritivo.","D":"A cólica renal tipicamente é de forte intensidade e associada à náusea, vômito e hematúria.\n\nQuando o cálculo atinge a junção ureterovesical pode mimetizar quadro de infecção urinária, com\ndisúria e polaciúria."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-59000","number":"59000","sourceNumber":"59000","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente de 32 anos, sexo masculino, mecânico de automóveis, queixa-se de dor em\ncoluna lombar iniciada há alguns anos, com piora progressiva nos últimos seis meses. A dor é pior\nao acordar e melhora com atividade física. Relata rigidez em região lombar pela manhã. O exame\nclínico revelou teste de Schober alterado. Considerando a principal hipótese diagnóstica em relação\na esse caso, espera-se encontrar os seguintes achados, EXCETO:","options":{"A":"Pesquisa do HLA-B27 positiva em mais de 80% dos casos.","B":"FAN e fator reumatoide positivos em até metade dos casos.","C":"Radiografia de articulações sacroilíacas normal em casos iniciais.","D":"Melhora dos sintomas e da mobilidade com anti-inflamatórios não esteroidais."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-44502","number":"44502","sourceNumber":"44502","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A respeito do Mieloma Múltiplo, pode-se afirmar, EXCETO:","options":{"A":"É uma gamopatia policlonal.","B":"O mielograma revela plasmocitose.","C":"A cintilografia óssea é método de investigação da extensão do MM.","D":"Ocorre, especialmente, na sexta década de vida."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-33820","number":"33820","sourceNumber":"33820","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Em relação à fibromialgia é INCORRETO afirmar que:","options":{"A":"Frequentemente os pacientes melhoram nas estações mais quentes e durante as férias.","B":"Dor, rigidez musculoesquelética generalizada e fadiga são sintomas\npresentes na fibromialgia.","C":"A fibromialgia afeta predominantemente as mulheres e é mais prevalente\nnas com menos de 50 anos.","D":"Os exames complementares são normais nos pacientes com fibromialgia."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-33410","number":"33410","sourceNumber":"33410","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente com litíase ureteral à direita apresenta dor intensa em flanco direito, febre,\nleucocitose (15.000) com desvio à esquerda (13% bastões), frequência cardíaca de 120 bpm e\nfrequência respiratória de 30 incursões respiratórias por minuto. A ultrassonografia abdominal\nmostra um cálculo em terço médio de ureter de 0,9 cm e hidronefrose concomitante. Podemos\nafirmar:","options":{"A":"É um cálculo pequeno que ainda se encontra em terço médio e pode descer e ser eliminado.\n\nNão há\n\nnecessidade de procedimento operatório algum.","B":"Paciente em sepse, há necessidade de desobstruir as vias urinárias para controle do quadro\ninfeccioso.","C":"Apesar do cálculo ser grande, o tratamento clínico se impõe como melhor opção e\nantibioticoterapia\n\nvenosa pode controlar o quadro infeccioso.","D":"Somente há necessidade de um procedimento operatório se houver mais de 7 dias de\ntratamento clínico."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-19104","number":"19104","sourceNumber":"19104","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Sobre o câncer de pâncreas, assinale a afirmativa INCORRETA:","options":{"A":"A diarreia incapacitante ocorre frequentemente após realização de pancreatoduodenectomia\nradical estendida.","B":"A perda de peso é a manifestação clínica mais frequente tanto em tumores da cabeça quanto da\ncauda do pâncreas.","C":"A presença de linfonodos peri-pancreáticos macroscopicamente envolvidos contraindica a\nressecção cirúrgica, pois indica um prognóstico sombrio.","D":"Níveis muito elevados de CA 19/9 estão usualmente associados com lesões irressecáveis."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-19106","number":"19106","sourceNumber":"19106","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Sobre os pólipos malignizados do grosso intestino, assinale a afirmativa INCORRETA:","options":{"A":"Tumores indiferenciados e a presença de invasão angiolinfática estão associados com maior\nrisco de metástase mesmo quando as lesões estão limitadas a cabeça do pólipo.","B":"Pólipos pediculados com adenocarcinoma invadindo até a cabeça do pólipo, em geral, são\nadequadamente tratados apenas pela polipectomia colonoscópica.","C":"Tumores que não ultrapassam a muscularis mucosae são considerados displasia de alto grau e\nvirtualmente não têm risco de metástase linfonodal.","D":"Lesões sésseis com acometimento da submucosa devem ser tratadas por ressecção oncológica\ndo segmento intestinal."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-349113","number":"349113","sourceNumber":"349113","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Uma mulher de 59 anos é atendida em unidade de pronto-atendimento, queixando-se\nde dor lombar contínua, de forte intensidade,\nde caráter progressivo e com piora no último mês.\n\nRealizou tratamento prévio com analgésico e com anti-inflamatório, porém os sintomas persistiram.\nEla refere história prévia de tratamento para\ncâncer de mama há 3 anos. No momento, está sem\nqueixas acerca da mama. O exame físico mostra hiperalgesia aos estímulos em coluna lombar.\n\nRadiografia da coluna lombar: lesões líticas. Com base no caso clínico apresentado, a principal\nhipótese diagnóstica é","options":{"A":"metástase.","B":"tuberculose.","C":"hérnia discal.","D":"fratura vertebral."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-349108","number":"349108","sourceNumber":"349108","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um homem de 65 anos, trabalhador rural, procura o atendimento em uma unidade de\natenção primária à saúde por queixa de dor na região lombar esquerda iniciada há 1 mês. A dor\nvem piorando progressivamente e, nos últimos dias, tem impossibilitado o sono reparador do\npaciente. Sua esposa se queixa de que as calças do marido estão com cheiro de urina\nultimamente. Ao exame, o paciente está lúcido, colaborativo e as mucosas estão úmidas e\nhipocoradas. Há retificação da coluna lombar, espasmo muscular localizado e dor à palpação\ndelicada das apófises vertebrais de L2 e L3. As manobras de elevação do membro inferior\nesquerdo estendido (Lasègue) e do membro inferior direito estendido (Lasègue cruzado) não\nreproduzem a dor. Como o paciente se queixa de dor com o decúbito ventral, o sinal de Lasègue\ninvertido (Wasserman) foi pesquisado em pé. A extensão das coxas com o paciente em\nortostatismo também não provocaram dor. Em relação a essa situação, assinale a opção que\nrepresenta, respectivamente, o diagnóstico clínico correto e a conduta médica apropriada.","options":{"A":"Dor lombar musculoesquelética; prescrever anti-inflamatórios.","B":"Dor lombar por radiculopatia; encaminhar paciente para o neurocirurgião.","C":"Dor lombar com comprometimento neurológico; solicitar exame de imagem.","D":"Dor lombar postural relacionada à profissão; recomendar repouso e solicitar fisioterapia."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-349093","number":"349093","sourceNumber":"349093","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um homem de 68 anos retorna do ambulatório de referência devido a dores em coluna\ntorácica e em lombar, de intensidade progressivamente maior nos últimos 3 meses. Os exames\nrealizados apresentaram os seguintes resultados (vide imagem): A radiografia de coluna vertebral\nmostrou lesões osteolíticas e fraturas vertebrais em T11, T12, L1 e L2. Nas últimas 2 semanas, o\npaciente apresenta-se excessivamente sonolento. Considerando essas informações, a hipótese\ndiagnóstica e o exame mais adequado para confirmá-la são, respectivamente,","options":{"A":"anemia falciforme; eletroforese de hemoglobina.","B":"linfoma; biópsia de linfonodos abdominais.","C":"hiperparatireoidismo; paratormônio (PTH).","D":"mieloma múltiplo; mielograma."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-349124","number":"349124","sourceNumber":"349124","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Uma mulher de 46 anos, trabalhadora doméstica, apresenta-se ao médico com queixa\nde lombalgia há 1 semana, com intensidade de 5\nem 10 na escala numérica da dor, de caráter\ncontínuo e não irradiado. Ela já apresentou quadro semelhante antes e possui indicação de uso de\nrelaxante muscular. Diante desse quadro, quais são, respectivamente, a hipótese diagnóstica mais\nprovável e a conduta médica adequada?","options":{"A":"Lombalgia de origem mecânico-postural; iniciar tratamento conservador.","B":"Lombalgia inespecífica; dispensar investigação com exames complementares.","C":"Lombalgia com sinais de alerta; solicitar ressonância magnética da coluna lombossacra.","D":"Lombalgia inespecífica; indicar repouso e prescrever paracetamol ou anti-inflamatório não\nesteroidal."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-318579","number":"318579","sourceNumber":"318579","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Uma paciente com 35 anos de idade vem apresentando dor em região lombar direita,\nassociada a náuseas e vômitos de início súbito há 4 horas. Nesse período, nega febre e refere\nvários episódios semelhantes anteriores. Ao exame físico apresenta apenas sinal de Giordano\npositivo á direita. Realizou tomografia de abdome e pelve que mostrou cálculo de 1,2 cm, localizado\nem junção ureteropiética direita e de densidade de 1.500 UH, Resultado do exame de Elementos\nAnormais e Sedimentos (EAS) na urina mostrou apenas hematúrias mocroscópica discreta. Em\nrelação ao cálculo, entre as condutas a seguir, a mais indicada é","options":{"A":"ureterorrenoscopia.","B":"pielolitotomia cirúrgica.","C":"litotripsía extracorpórea.","D":"terapia expulsora do cálculo com hidratação e alfa-bloqueadores."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-352604","number":"352604","sourceNumber":"352604","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Irinete, 58 anos, vem à consulta na unidade de saúde devido a ?dor nas juntas?. Relata\nque sente dor desde a hora que acorda, principalmente enquanto faz as tarefas domésticas e cuida\ndo neto de 4 anos. Sente rigidez nas articulações ao acordar ou após muito tempo em repouso que\nduram em torno de 20 minutos. Relata que sente o sono não sendo reparador e tem a sensação de\ncabeça vazia. Ao exame físico, o joelho direito apresenta-se aumentado de tamanho e com\ncrepitações, tornozelo direito com leve edema articular. Sem outras articulações com sinais de\nsinovite. Apresenta dor à palpação em vários pontos do corpo. Dentre as hipóteses diagnósticas de\nIrinete estão:","options":{"A":"Artrite reumatoide, contudo, descarta-se pela idade e pelo acometimento apenas de grandes\narticulações.","B":"Fibromialgia é a hipótese mais provável e explica os sintomas da paciente, sem necessidades de\nexames complementares.","C":"Osteoartrite é uma hipótese diagnóstica importante a ser considerada, acometendo joelho e\nsobrecarregando tornozelo.","D":"Hipotiroidismo como causa do distúrbio do sono que pode estar causando o sintoma de cabeça\nvazia e aumentando a sensibilidade à dor e edema articular."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-355217","number":"355217","sourceNumber":"355217","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente sexo masculino, 80 anos, admitido em hospital devido à síndrome\nconsumptiva, dor no corpo, astenia e mal-estar\ngeneralizado. Aos exames laboratoriais, notam-se\ncálcio total 15 mg/dL, hemoglobina 8 g/dL, proteína total 9,8 g/dL, globulina 7,3 g/dL, albumina 2,5\ng/dL e creatinina de 2 mg/dL. Com base nos dados expostos, a melhor hipótese diagnóstica e o\nexame a ser realizado são, respectivamente,","options":{"A":"linfoma e biópsia de linfonodo.","B":"mieloma múltiplo e mielograma.","C":"hiperparatireoidismo primário e dosagem de paratormônio.","D":"sarcoidose e dosagem da ECA.","E":"amiloidose e biópsia de rim."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-355255","number":"355255","sourceNumber":"355255","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Durante a hernioplastia inguinal por via anterior, realizamos a identificação e o\nisolamento do cordão espermático. Com base\nnessa informação, a única estrutura anatômica que\nnão compõe o cordão espermático encontra-se na alternativa","options":{"A":"Fibras do músculo cremastérico.","B":"Ducto deferente.","C":"Nervo femoral.","D":"Ramo genital do nervo genito femoral.","E":"Artéria testicular."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-326278","number":"326278","sourceNumber":"326278","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente mulher 26 anos, chega ao PS com dor lombar D, tipo cólica, de forte\nintensidade e início súbito. Náuseas e\nvômitos presentes, irradiação para grandes lábios e parede\nvaginal ipsilateral. BEG, algo taquicárdica, pouco sudoreica, sem febre, com abdome plano pouco\ndoloroso, sem sinais de peritonismo e com sinal de Giordano positivo à direita. Marque a alternativa\ncorreta em relação à principal hipótese diagnóstica e condutas iniciais recomendadas.","options":{"A":"Trata-se de caso clássico de pielonefrite aguda, o tratamento recomendado é analgesia,\ninternação e antibioticoterapia.","B":"Lombociatalgia com comprometimento radicular, deve ser administrado analgesia + Corticoides\ne realização de RNM de coluna lombo-sacral.","C":"ITU baixa causada por provável infecção ginecológica, recomenda-se analgesia e coleta de\nmaterial ginecológico (PCCU).","D":"Cólica nefrética, realização de analgesia, coleta laboratorial e investigação por imagem."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-326302","number":"326302","sourceNumber":"326302","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Mulher com 57 anos e trabalha como faxineira. Procura atendimento devido queixa de\ndor articular em mãos e joelhos. Relata rigidez matinal que melhora em menos de 20 minutos com\nas atividades da manhã. Ao exame das mãos observa-se deformidade nas articulações\ninterfalangianas, sem sinais de sinovite. Joelho direito com leve edema e calor, com crepitação à\nmovimentação. Joelho esquerdo sem alterações. A condução mais adequada para o caso é:","options":{"A":"Solicitar VHS, PCR e iniciar prednisona.","B":"Fazer um AINE por no máximo 7 dias, analgesia simples e fisioterapia.","C":"Solicitar RX de mãos, joelhos, provas inflamatórias e Fator reumatóide.","D":"Fazer uma dose de corticoide intramuscular e solicitar RX das articulações."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-320172","number":"320172","sourceNumber":"320172","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente 32 anos, apresentando episódios de dor lombar e abdominal associado à\nnáuseas e vômitos. No exame físico\napresenta dor à palpação profunda de flanco esquerdo, com\ndescompressão brusca negativa e com Giordano negativo. Os sinais vitais estão estáveis. Realizou\nTC do abdome sem contraste, representada abaixo. Diante deste quadro e exame de imagem a\nmelhor conduta para resolução do caso é:","options":{"A":"pieloplastia videolaparoscópica.","B":"reimplante vesicoureteral extravesical.","C":"nefroureterectomia radical.","D":"embolização de vasos renais.","E":"nefrolitotripsia percutânea."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-311442","number":"311442","sourceNumber":"311442","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Mulher, 48 anos, dá entrada no pronto-socorro com dor lombar à direita tipo cólica que\nirradia para flanco direito e grandes lábios, com início há 5 dias, associado com episódios de\nhematúria, apresenta péssimo estado geral, estando hipocorada, sudoreica, febril com temperatura\naxilar de 39,50. PA = 110 x 75 mmHg e FC = 110 bbp e leucocitose de 29 mil. TC evidenciou\ncálculo de 8 mm em ureter proximal direito. Além da instituição de antibioticoterapia, hidratação e\nanalgesia, outra conduta que deve ser realizada é:","options":{"A":"Drenagem da via urinária com cateter duplo-J sem a retirada do cálculo ureteral.","B":"Realização da terapia expulsiva medicamentosa com tansulosina.","C":"Realização de litotripsia extracorpórea.","D":"Realização de ureterolitotripsia endoscópica e colocação de duplo-J.","E":"Observação clínica por 72 horas para aguardar melhora clínica e submetê-la a procedimento\ncirúrgico."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-277736","number":"277736","sourceNumber":"277736","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem, 24 anos, com queixa de dor lombar alta à direita há 2 horas, a qual irradia para\nfossa ilíaca direita, forte intensidade e associado a hematúria. Ao exame, presença de sinal de\nGiordano à direita. Foi realizada tomografia de abdome (imagem acima), que evidencia","options":{"A":"cisto renal Bosniak IV e calcificação de artéria ilíaca comum à direita.","B":"necrose de papila renal direita e coágulo intravesical.","C":"cisto renal parapiélico e calcificação de artéria ilíaca comum à direita.","D":"agenesia renal à esquerda e lesão expansiva na bexiga à direita.","E":"dilatação pielocalicial em rim direito e imagem hiperdensa, sugestiva de cálculo, ao nível da\njunção ureterovesical direita."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-269768","number":"269768","sourceNumber":"269768","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente masculino, 35 anos, comerciante, relata histórico de lombalgia que melhora ao\nmovimento e piora quando está em repouso. Procurou um clínico há quatro meses, sendo prescrito\nibuprofeno de horário, diariamente. Durante o período que estava fazendo uso da medicação,\nhouve melhora da dor. Há cerca de dois meses, voltou a apresentar dor lombar mais intensa, em\nespecial no período da manhã, com as mesmas características, porém com irradiação para as\nnádegas. Iniciou, também, quadro de artrite em joelho direito. Em relação ao caso clínico descrito,\nmarque a alternativa CORRETA.","options":{"A":"Nesses casos, a pesquisa do antígeno HLA-B27 é de pouca relevância clínica para o\ndiagnóstico, pois é encontrado em menos de 50% desses pacientes.","B":"Seria também esperado esse paciente evoluir com acometimento inflamatório progressivo de\npequenas articulações, de forma assimétrica e\noligoarticular.","C":"O envolvimento discal e degenerativo vertebral justifica o sintoma lombar e a irradiação da dor\npara as nádegas, podendo simular ciática ou lesão por trauma.","D":"A fisioterapia corresponde ao tratamento padrão-ouro nos estágios iniciais. Não havendo\nmedicações que alterem seu prognóstico, até o momento.","E":"Na investigação diagnóstica, é importante que esse paciente seja questionado sobre o\ncomportamento sexual, sintomas intestinais, oculares e lesões de pele."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-269770","number":"269770","sourceNumber":"269770","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem, 52 anos, casado, queixa de dificuldade de manter a ereção após algum tempo\ndo início da atividade sexual, com início da\nqueixa há um ano e piora importante há um mês, libido\nnormal. Refere ter diabetes mellitus tipo 2, hipertensão arterial sistêmica, dislipidemia,\nobesidade e\nser tabagista. Há 3 meses teve infarto agudo do miocárdio, sem supra de ST, sendo realizada\ncolocação de dois stents em coronária. No momento faz uso dos seguintes medicamentos AAS,\nclopidogrel, monocordil, metoprolol, losartana, metformina e sinvastatina. A melhor conduta para\ntratar a disfunção erétil deste paciente é:","options":{"A":"utilizar tadalafila 5 mg por dia associado a psicoterapia.","B":"utilizar Sildenafil 50 mg sob demanda associado a psicoterapia.","C":"realizar a injeção intracavernosa com prostaglandina associado à psicoterapia.","D":"colocação de próstese peniana associado a psicoterapia.","E":"realizar psicoterapia e não oferecer outra opção de tratamento."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-259999","number":"259999","sourceNumber":"259999","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Mulher de 42 anos, dona de casa, refere dor em articulações das mãos e joelhos há\nmais de 6 meses. Relata que a dor é associada ao uso da articulação, piora com o frio e acorda\ncom rigidez matinal que dura em torno de 15 minutos. Nega febre ou lesões de pele. Relata ganho\nde peso no período e dispneia aos grandes esforços. Não pratica atividade física regularmente há\num ano. Faz uso irregular de diclofenaco e já fez corticoide IM. Ao exame físico: artrite de 2ª, 3ª\ne\n4ª interfalangeanas proximais e distais (foto da mão a seguir). Joelhos com crepitação, mas sem\nsinais de artrite. Ausculta cardiopulmonar normal. PA:140x85mmHg, FC:80bpm, FR:18irpm,\nIMC:31kg/m2. A conduta mais adequada seria:","options":{"A":"Solicitar RM de joelho e Rx de mão e punhos, fazer curso de 14 dias com AINES via oral, manter\nanalgesia com paracetamol ou dipirona.","B":"Solicitar hemograma, VHS, PCR e Fator reumatoide, Rx de mãos e punhos e RM de joelho,\nfazer curso de 7 dias com AINES via oral,\nmanter analgesia com paracetamol, dipirona ou codeína.","C":"Solicitar fisioterapia para o joelho, orientar necessidade de prática de exercício físico\nregular e\nperda de peso, AINE tópico para as mãos e analgesia simples em caso de dor.","D":"Solicitar hemograma, VHS, PCR e Fator reumatoide, Rx de mãos e punhos e RM de joelho,\nfazer infiltração com corticoide intra-articular e fisioterapia, além de analgesia simples."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":["question_bank/media/medcurso/med-cirurgia-med-cir-07/259999.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-254711","number":"254711","sourceNumber":"254711","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"NÃO é indicação de cirurgia em pacientes com HPB (Hiperplasia Prostática Benigna):","options":{"A":"Aumento do volume prostático.","B":"Hematúria refratária.","C":"Infecção urinária de repetição.","D":"Retenção urinária com uso de SVD (Sonda Vesical de Demora).","E":"Dor testicular crônica."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-230898","number":"230898","sourceNumber":"230898","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Mulher, 52 anos, empregada doméstica. Refere dor em joelho direito e nas articulações\ndas mãos. Relata rigidez matinal em torno de\n20minutos. Refere que as dores pioravam com o frio\ne com o esforço físico e melhoravam com o repouso. Atualmente vem fazendo uso de diclofenaco\ncom melhora; contudo, refere epigastralgia. Ao exame articular notam-se nas mãos nódulos de\nHeberden e Bouchard e no joelho há crepitação. No momento, nenhuma articulação com sinal de\nsinovite. Qual a conduta mais adequada para o tratamento paciente?","options":{"A":"Manter diclofenaco e associar com IBP.","B":"Prescrever analgesia simples e fisioterapia.","C":"Iniciar Metotrexato associado a ácido fólico.","D":"Iniciar corticoide em dose imunossupressora."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-254712","number":"254712","sourceNumber":"254712","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Sobre a Tomografia (TC) e suas implicações no tratamento da litíase renal, é\nCORRETO afirmar:","options":{"A":"A tomografia computadorizada tem alta sensibilidade para detecção da litíase, por ter baixa\nespecificidade.","B":"Densidades, dimensões e distância, cálculo-pelo são informações que a tomografia fornece,\nporém são fatores produtores para sucesso do\ntratamento com LECO.","C":"A URO-TC não é utilizada para programação de tática cirúrgica para NPC (Nefrolitotripsia\nPercutânea).","D":"Não se deve utilizar tomografia, em nenhuma hipótese, em pacientes grávidas ou na população\npediátrica.","E":"A urografia excretora possui sensibilidade e especificidade semelhantes em relação à tomografia\nsem contraste na detecção da litíase."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-216235","number":"216235","sourceNumber":"216235","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Disfunção erétil é definida como incapacidade persistente de obter e manter uma\nereção suficiente para uma função sexual\nsatisfatória (Sociedade Brasileira de Urologia). Nesse\nsentido é correto afirmar que:","options":{"A":"geralmente está associado a ginecomastia e diminuição do volume testicular.","B":"drogas diuréticas como tiazídicos podem se associar e contribuir ao mecanismo de disfunção\nerétil.","C":"a terapia hormonal é indicada para pacientes com níveis normais de testosterona e deficit de\nlibido.","D":"em caso de hiperplasia benigna de próstata com sintomas obstrutivos deve ser indicado a\nterapia hormonal.","E":"o uso de medicamentos antidepressivos inibidores da MAO não interferem na evolução do\nprocesso de disfunção erétil."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-203689","number":"203689","sourceNumber":"203689","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente de 32 anos, sexo masculino, vem à consulta por queixa de lombalgia há 6\nmeses. Relata dor tipo pontada e rigidez matinal de cerca de 2h. Refere melhora à medida que se\nmovimenta. Realizou radiografia da coluna lombar com sinais de osteófitos incipientes. O\ntratamento com nimesulida ou diclofenaco leva à melhora temporária dos sintomas, necessitando\nfazer uso diário desses medicamentos para manter-se em suas atividades laborais (engenheiro\ncivil). Neste momento, a conduta adequada é:","options":{"A":"Manter uso de anti-inflamatórios e encaminhar para fisioterapia.","B":"Solicitar VHS, PCR e ressonância magnética de sacroilíacas.","C":"Solicitar ressonância magnética lombar.","D":"Encaminhar para ortopedia, devido aos osteófitos.","E":"Fornecer atestado médico para repouso absoluto por 7 dias."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-216193","number":"216193","sourceNumber":"216193","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Sobre a Espondilite Anquilosante é correto afirmar que: I. Homens entre 20 e 40 anos\nsão o principal grupo acometido pela\ndoença. II. O antígeno leucocitário humano, ou HLA-B27 pode\nocorrer em até 90% dos pacientes portadores da doença. III. A sacroileíte, colite, inflamações nos\nolhos e tendinites são sintomas da Espondilite Anquilosante. IV. O sintoma mais clássico da\nEspondilite Anquilosante é o acometimento da coluna vertebral, caracterizando por dores e rigidez\nmatinal. A alternativa que contám todas as afirmativas corretas é:","options":{"A":"I e II","B":"I e III","C":"I, II e III","D":"I, III e IV","E":"I, II, III e IV"},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-216266","number":"216266","sourceNumber":"216266","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente do sexo feminino, 35 anos, atendida em hospital de urgência de alta\ncomplexidade, refere dor lombar intensa e hematúria, com cólica nefrética direita há 3 dias,\nassociada a quadro de disúria e polaciúria, sem melhora com analgésicos. Em exame de\nultrassonografia, evidenciou-se a presença de um cálculo de 10 mm. Portanto, a depender da\nforma e tamanho do cálculo urinário, os pontos de MAIOR resistência na passagem pelo trajeto\nureteral, e que provocam cólica, obstrução e hidronefrose são:","options":{"A":"Pelve renal, trajeto do músculo iliopsoas e junção ureterovesical.","B":"Pelve renal, cruzamento com os vasos ilíacos e músculo psoas.","C":"Cálice renal, trajeto sobre o músculo psoas e junção ureterovesical.","D":"Cálice renal, cruzamento com vasos ilíacos e junção ureterovesical.","E":"Junção ureteropélvica, cruzamento com os vasos ilíacos e junção ureterovesical."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-181929","number":"181929","sourceNumber":"181929","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A.V.S., sexo masculino, 30 anos de idade, solteiro, comparece pela primeira vez à\nUnidade Básica de Saúde (UBS) de seu bairro\npor conta de dor nas costas há 2 dias. Ao ser\natendido pelo médico, inicia a conversa dizendo que gostaria que lhe fosse pedido um raio X da\ncoluna ou uma ressonância. O médico pediu detalhes do ocorrido e ficou sabendo que A.V.S\ntrabalha como carregador em uma embarcação e que sentiu ?a coluna travar?, enquanto tentava\norganizar sacos de cimento no chão. Já havia tomado, por conta própria, diclofenaco 50 mg, 2\ncomprimidos ao dia, sem melhora do quadro. Estava preocupado, pois seu tio de 60 anos tinha\nmorrido recentemente de câncer cuja investigação se iniciou por quadro de dor nas costas. Sobre a\nqueixa trazida pelo paciente, do caso clínico acima, é correto afirmar que:","options":{"A":"na maioria dos quadros de lombalgia é possível identificar a causa específica.","B":"é prudente a solicitação de exames de imagem dado ao risco para neoplasia ou doença grave.","C":"se houver piora da dor no período noturno, neoplasia precisa ser considerada.","D":"o uso de diclofenaco não faz parte do arsenal terapêutico da dor lombar.","E":"o desejo de ser aposentado precocemente não é diagnóstico diferencial."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-192600","number":"192600","sourceNumber":"192600","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Causa mais comum de litíase urinária em adultos jovens é:","options":{"A":"Hipercalciúria","B":"Hiperuricemia","C":"Abuso de diuréticos","D":"Hipocitratúria","E":"Hipomagnesiúria"},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-181923","number":"181923","sourceNumber":"181923","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Durante uma investigação laboratorial de um paciente, a presença da proteína de\nBence Jones, indica que o paciente apresenta:","options":{"A":"Tuberculose óssea.","B":"Sífilis com envolvimento ósseo.","C":"Osteomielite crônica.","D":"Mieloma múltiplo.","E":"Osteocondromatose."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-181931","number":"181931","sourceNumber":"181931","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente do sexo feminino, 48 anos, refere dor lombar a direita há 01 semana\nintermitente em cólica com irradiação para flanco\ndireito e febre não aferida. Antecedente de\nnefrolitíase. Exame físico com punho percussão dolorosa a direita. PA: 160X100 mmHg, FC: 98\nbpm e temperatura axilar: 36,9ºC. A melhor conduta para o caso é:","options":{"A":"Analgesia, hemograma, função renal, urina tipo I, urocultura, USG de rins e vias urinárias e raio\nX de abdome.","B":"Analgesia, hemograma, função renal, urina tipo I, urocultura e USG de rins e vias urinárias.","C":"Analgesia, urina tipo I, antibioticoterapia e alta com encaminhamento para urologista.","D":"Analgesia, urina tipo I, hemograma, função renal e raio X de abdome.","E":"Analgesia, hemograma, função renal, urina tipo I, urocultura e TC helicoidal de abdome total."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-159851","number":"159851","sourceNumber":"159851","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente de 35 anos de idade com história de resfriado prévio e procura a urgência do\nHospital Municipal com quadro de dor lombar, dificuldade para deambular, constipação intestinal e\nretenção urinária. Nega caso semelhantes na família ou episódios anteriores. A doença que melhor\nexplicaria o caso clínico acima é:","options":{"A":"Mielite Transversa","B":"Hérnia discal","C":"Polineuropatia periférica","D":"Síndrome de Guillain Barre","E":"Acidente Vascular Encefálico"},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-134472","number":"134472","sourceNumber":"134472","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem, 51 anos, com dor lombar há 24 horas, acompanhado de náuseas, vômitos e\nhematúria macroscópica. Tem antecedente de hipertensão arterial, usa losartana 50 mg/dia e nega\ndiabetes. O diagnóstico mais provável é:","options":{"A":"Pielonefrite aguda.","B":"Insuficiência renal aguda.","C":"Lumbago.","D":"Litíase renal.","E":"Síndrome nefrítica."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-134514","number":"134514","sourceNumber":"134514","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Sobre a Urolitíase é correto afirmar que:","options":{"A":"a complicação mais frequente da Litotripsia Extraxorpórea por Onda de Choque (LEOC) é o\nhematoma renal.","B":"Indica-se tratamento ureteroscópico para cálculos ureterais obstrutivos com diâmetro acima de 6\nmm.","C":"A LEOC pode ser realizada em gestantes.","D":"A LEOC é a melhor conduta para cálculos calicinais inferiores com diâmetro superior a 20 mm.","E":"A Nefrolitotripsia Percutânea não é indicada para cálculos piélicos com diâmetros superior a 20\nmm."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-86501","number":"86501","sourceNumber":"86501","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem de 30 anos, previamente hígido, refere dor em região lombar de início agudo\napós movimentar um sofá há 3 dias. Nega febre,\nemagrecimento ou qualquer outra queixa, e o\nexame neurológico é normal. A conduta imediata é:","options":{"A":"Solicitar que o paciente se mantenha ativo conforme tolerância, evitando períodos prolongados\nem repouso na cama e prescrever analgesia\nfarmacológica.","B":"Repouso no leito por tempo prolongado e analgesia farmacológica.","C":"Ressonância nuclear magnética com urgência para diagnóstico de possível hérnia discal,\nrepouso absoluto no leito e analgesia farmacológica.","D":"Anti-inflamatórios não hormonais e raio X de\n\ncoluna lombar, bem como exames de atividade inflamatória para afastar espondiloartrite.","E":"Usar o corticosteroide, pois as evidências mostram que é superior ao placebo e, portanto, deve\nser a droga de escolha nessa situação."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-86517","number":"86517","sourceNumber":"86517","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"O componente mais frequente do cálculo renal é:","options":{"A":"Ácido úrico.","B":"Cistina.","C":"Oxalato de cálcio.","D":"Fosfato de cálcio.","E":"Fosfato de amônia-magnesiano."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-70297","number":"70297","sourceNumber":"70297","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente apresentando cólica nefrética típica à esquerda relata dois episódios\nanteriores de litíase urinária.\nUltrassonografia mostrou cálculo de 0,4 cm de diâmetro em pelve\nrenal esquerda, na junção ureteropiélica, com hidronefrose moderada. Após analgesia, os sintomas\nmelhoraram. Nesse caso:","options":{"A":"A causa mais provável da litíase é a hiperuricemia.","B":"A melhor conduta terapêutica para o tipo de cálculo é a litotripsia.","C":"A hidronefrose indica presença concomitante de infecção do trato urinário.","D":"O uso de anti-inflamatório não hormonal pode auxiliar a expelir o cálculo.","E":"A retirada imediata do cálculo é necessária para evitar a esclerose renal."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-50130","number":"50130","sourceNumber":"50130","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Na abordagem ao paciente com queixas neurológicas, como parestesias, dor e\nfraqueza, utilizamos diversas manobras durante o\nexame físico para auxiliar na nossa investigação.\nConsidere, a esse respeito, as apresentadas no quadro a seguir: Manobras semiológicas: 1.\n\nPhalen; 2. Laségue; 3. Mingazzini/Enfermidades: a. Lombociatalgia; b. Síndrome do túnel do carpo;\n\nc. Miopatia inflamatória. Assinale a alternativa em que se correlaciona corretamente as manobras\nsemiológicas com as enfermidades a elas relacionadas.","options":{"A":"1-c; 2-a; 3-b.","B":"1-b; 2-a; 3-c.","C":"1-a; 2-c; 3-b.","D":"1-b; 2-c; 3-a.","E":"1-c; 3-b; 2-a."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-55276","number":"55276","sourceNumber":"55276","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"No PSF, pacientes idosos masculinos frequentemente apresentam jato urinário fino e\nnoctúria. Nesse caso,","options":{"A":"após confirmada hiperplasia prostática benigna devem ser tratados no PSF com bloqueadores\nA2, antiandrogênicos e acompanhamento.","B":"frequentemente têm PSA muito aumentado.","C":"devem ser logo referenciados para atenção secundária e terciária.","D":"têm ao toque nodularidade na zona periférica.","E":"não há referência para urologia por inexistência da especialidade na rede."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-352698","number":"352698","sourceNumber":"352698","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente masculino, 45 anos, branco, diabetes mellitus tipo II há um ano. Há seis\nmeses com dor e cianose de 1o pododáctilo à\nesquerda, sem alterações vasculares em USG\nDoppler e perda de > 10% do peso corporal. Dor em queimação e perda de força em membros\ninferiores (MMII) há cinco meses, com piora progressiva e dificuldade para deambular. Ao exame\nfísico: taquicárdico, hipotrofia generalizada, força grau dois e hipoestesia simétrica em MMII,\nhiperpigmentação de pele em superfícies articulares nas mãos. Eletroneuromiografia: neuropatia\nperiférica mista sensitivo-motora (axonal e desmielinizante), simétrica e de grave intensidade em\nMMII. Tomografia de tórax e PET CT: lesão lítica hipermetabólica no 4o arco costal esquerdo.\n\nAnatomopatológico e imuno-histoquímico de lesão: neoplasia com morfologia plasmocitoide CD138,\nCD56, MUM1 e Lambda positivos. Biópsia de medula óssea 5% de plasmócitos, hipocelular para a\nidade. Eletroforese de proteínas séricas com componente monoclonal de 0,53 g/dL e imunofixação\nIgG Lambda. Hemoglobina glicada 11%. Fator de crescimento do endotélio vascular (VEGF) 1000\npg/n. Qual a principal hipótese diagnóstica para o caso?","options":{"A":"Amiloidose.","B":"Gamopatia de significado indeterminado.","C":"Polineuropatia desmielinizante crônica.","D":"Síndrome POEMS.","E":"Kikuchi-Fujimoto."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-352688","number":"352688","sourceNumber":"352688","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um homem de 60 anos de idade, acompanhado da esposa, chega à clínica com queixa\nde disfunção erétil. Relata histórico de 10\nanos de diabetes mellitus em uso de antidiabéticos orais.\nAo longo do último ano, ele afirma que apesar da libido preservada, não consegue ter ereções\nmantidas com a esposa e nem ereções espontâneas no decorrer das noites. A glicemia de jejum é\n100 mg /dl, hemoglobina glicosilada é 5,9 %, testosterona, hormônios tireoidianos e prolactina\nestão dentro da normalidade. Qual possível terapêutica poderá ajudar a alcançar e manter sua\nereção?","options":{"A":"Inibidor da 5?-redutase.","B":"Androgênio.","C":"Agonista dopaminérgico.","D":"Inibidor da 5 fosfodiesterase.","E":"Inibidor de recaptação de serotonina."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-341108","number":"341108","sourceNumber":"341108","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Sobre a Macroglobulinemia de Walderstrom (MW), podemos afirmar, exceto:","options":{"A":"No geral tem bom prognóstico, sendo mais frequentes em homens com idade mediana de 40\nanos.","B":"O tratamento da MW está reservado à presença de sintomas e complicações. A plamaférese,\ncom redução dos níveis circulantes de IgM, e a\nquimioterapia, com inibição do crescimento tumoral,\nsão indicados na MW sintomática.","C":"Trata-se de um linfoma linfoplasmocítico, ou seja, tem características tanto de mieloma múltiplo\nquanto de linfoma não Hodgkin.","D":"A combinação da morfologia da medula óssea, histologia e imunofenotipagem distingue a MW\nde outras doenças das células B, como:\nleucemia linfocítica crônica, linfoma das células do manto,\nlinfoma folicular, linfoma difuso de grandes células B e linfoma de zona marginal extranodal, que\npodem estar associadas com paraproteína IgM.","E":"Pacientes com sintomas de hiperviscosidade devem ser tratados com plasmaférese.19 O\ntratamento deve ser feito concomitantemente com a quimioterapia para a redução da produção\nanormal de proteína IgM monoclonal."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-308530","number":"308530","sourceNumber":"308530","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente masculino, 42 anos, bancário, natural e procedente de Patos-PB, procura\natendimento médico no PSF Rita Palmeira com quadro de fraqueza do extensor longo do hálux\ndireito. De acordo com este único achado confirmado pelo exame físico, você sugere se tratar de\nradiculopatia de nível de:","options":{"A":"L5","B":"L3","C":"S1","D":"L2","E":"L4"},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-292028","number":"292028","sourceNumber":"292028","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente de 34 anos, masculino, chega ao pronto-socorro com queixa de dor lombar\nesquerda de intensidade 10/10 iniciada há 8 horas que vem apresentando piora progressiva e\nirradiou-se para região escrotal e face interna da coxas ipsilaterais. Apresentou dois episódios de\nvômitos e hematúria macroscópica. Nega febre. A dor permanece apesar do uso de analgesia\nopioide. Ao exame, apresenta temperatura 36,5°C, PA = 120 x 80 mmHg, pulso 80 bpm, FR = 15\nirpm, abdômen plano, flácido, indolor, Giordano negativo. Realizou exames laboratoriais:\nhemograma normal, creatinina 0,8 mg/dl, PCR 31 mg/L, sumário de urina com incontáveis\nhemácias. Realizou tomografia computadorizada de abdômen que mostrou cálculo ureteral à\nesquerda medindo 0,4 cm, causando moderada uretero hidronefrose amontante. Diante deste\nquadro, qual a melhor conduta?","options":{"A":"Passagem de cateter duplo J à esquerda, em caráter de urgência.","B":"Ureterorrenolitotripsia rígida a laser.","C":"Inicialmente, terapia medicamentosa expulsiva.","D":"Internação e antibioticoterapia de amplo espectro.","E":"Nenhuma das anteriores."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-308601","number":"308601","sourceNumber":"308601","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Qual principal fator prognóstico relacionado ao Mieloma Múltiplo?","options":{"A":"Função renal.","B":"Grau de anemia.","C":"Nível sérico de beta-2-microglobulina.","D":"Nível de cálcio sérico.","E":"Presença de proteína de Bence Jones na urina."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-221068","number":"221068","sourceNumber":"221068","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A manifestação extra-articular mais frequente da Espondilite Anquilosante é:","options":{"A":"Uvelte anterior.","B":"Pericardite.","C":"Fibrose pulmonar.","D":"Esplenomegalia."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-208038","number":"208038","sourceNumber":"208038","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"P.A.S.B tem 45 anos e trabalha como pedreiro numa construtora. Chega à Unidade de\nSaúde com dor lombar há dois dias de\nmoderada intensidade, sem irradiação para outras partes do\ncorpo. Refere que já teve quadro semelhante há cinco meses. Nega outros sintomas ou traumas no\ndorso. Ao exame físico, apresenta pressão arterial de 130 x 90 mmHg com ausculta cardíaca e\npulmonar normais. Abdome e membros sem alterações e manobra de lasègue negativa.\n\nConsiderando a abordagem de dor lombar apresentada no Tratado de Medicina de Família e\ncomunidade, avalie as alternativas abaixo e assinale a afirmativa que apresenta a conduta mais\nadequada ao caso:","options":{"A":"Neste caso, deve-se prescrever anti-inflamatório ou paracetamol, podendo-se associar um\nrelaxante muscular. A idade superior a 40 anos torna necessária a solicitação de radiografia da\ncoluna lombar. Por fim, deve ser emitido atestado para que o paciente fique em repouso no leito\npara melhor recuperação.","B":"Neste caso, deve-se prescrever anti-inflamatório ou paracetamol, podendo-se associar um\nrelaxante muscular. A idade superior a 40 anos torna necessária a solicitação de radiografia da\ncoluna lombar. Por fim, deve ser emitido atestado para que o paciente fique afastado de suas\natividades laborais para evitar sobrecarga na coluna lombar. Não é necessária restrição ao leito.","C":"Neste caso, deve-se prescrever anti-inflamatório ou paracetamol, podendo-se associar\namitriptilina. Não é necessário solicitar\nradiografia neste momento. Por fim, deve ser emitido\natestado para que o paciente fique afastado de suas atividades laborais para evitar sobrecarga na\ncoluna lombar. Não é necessária restrição ao leito.","D":"Neste caso, deve-se prescrever anti-inflamatório ou paracetamol, podendo-se associar um\nrelaxante muscular. Não é necessário solicitar\nradiografia neste momento. Por fim, deve ser emitido\natestado para que o paciente fique afastado de suas atividades laborais para evitar sobrecarga na\ncoluna lombar. Não é necessária restrição ao leito.","E":"Neste caso, deve-se prescrever um relaxante muscular, restringindo o uso de anti-inflamatório\napenas nos casos refratários.Não é necessário\nsolicitar radiografia neste momento. Por fim, deve\n\nser emitido atestado para que o paciente fique em repouso no leito ara melhor recuperação."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-221098","number":"221098","sourceNumber":"221098","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Dos itens abaixo, qual o marcador prognóstico mais importante para um paciente com\nmieloma múltiplo?","options":{"A":"Proteína de Bence-Jones.","B":"Dosagem sérica de IgA.","C":"PCR.","D":"B2 microglobulina."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-160571","number":"160571","sourceNumber":"160571","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Sobre a litíase renal/ureteral, considere as assertivas abaixo, utilizando V para\nVerdadeiro e F para Falso: ( ) Os episódios\nagudos relacionados à urolitíase geralmente refletem\nobstrução, infecção ou ambos.; ( ) Quando o ureter é obstruído por um cálculo, a pressão no\nsistema coletor proximal sobe e, com distensão progressiva, o paciente experimenta dor\nsignificativa e sintomas viscerais, incluindo náuseas, vômitos e íleo paralítico.; ( ) Se o doente\nestiver livre de sinais de infecção (com base no exame de urina e ausência de calafrios, febre e\nleucocitose), pode ser tratado ambulatorialmente, desde que possa hidratar oralmente, a dor é\nadequadamente controlada por analgésicos orais. A sequência CORRETA é:","options":{"A":"V, V, V.","B":"V, F, V.","C":"V, F, F.","D":"F, V, V.","E":"F, F, F."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-138997","number":"138997","sourceNumber":"138997","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Jovem com história familiar de nefrolitíase, branco, solteiro, tem cálculo de ácido úrico\ndocumentado após episódio de cólica nefrética. Na investigação do perfil metabólico, as alterações\nmais prováveis de se documentar são:","options":{"A":"Hiperuricosúria, baixo volume urinário e pH urinário < 5,5.","B":"Hipercalciúria, hiperuricemia e pH urinário < 5,5.","C":"Hipocitratúria, hiperuricosúria e pH Urinário > 6.","D":"Hiperuricemia, hipocitratúria e hiperoxaluria.","E":"Hiperuricosúria, hipercalciúria e pH urinário < 5,5."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-138453","number":"138453","sourceNumber":"138453","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Mulher, 34 anos, portadora de litíase renal de repetição, com quadro há dois dias de\nfebre alta, dor lombar à direita, náuseas,\nvômitos e decaimento do estado geral. PA: 80 x 45 mmHg;\nFC: 120 bpm; FR: 24 irpm; T = 39,8°C; SatPO2 em ar ambiente = 99%. USG realizada no setor de\npronto atendimento mostrou dilatação pielocalicial à direita, com cálculo medindo cerca de 8 mm,\nencravado na Junção Ureteropiélica (JUP). A paciente foi submetida à expansão volêmica, coleta\nde amostras para hemoculturas e urinocultura e início de antibioticoterapia parenteral com\ncefotaxima 2 g a cada 8 horas. Após expansão volêmica, a PA ficou em 108 x 80 mmHg. A conduta\npara esta paciente deverá ser melhorada através:","options":{"A":"Da realização de TC não contrastada de vias urinárias.","B":"De substituição do antibiótico utilizado por metronidazol.","C":"Da passagem de cateter ureteral tipo duplo J.","D":"Do início de noradrenalina em BIC (Bomba de Infusão Contínua).","E":"Da adição de ciprofloxacino ao antibiótico utilizado."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-141817","number":"141817","sourceNumber":"141817","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente, do sexo feminino, 60 anos, deu entrada neste hospital com quadro de\nanemia, desidratação, poliúria e dores na coluna\n(SIC). Não faz uso de medicamentos. Relata ainda\nconstipação e apatia. Ao exame, encontra-se consciente, desidratada, hipocorada (++/4+). Há dois\nmeses sofreu fratura de fêmur ao escorregar no banheiro. Resultados de exames iniciais:\nhematimetria: 3 milhões de hemácias por mm³; hemoglobina de 7,5 mg%; com hemácias\nempilhadas à hematoscopia (Rouleaux); VHS = 95 mm na 1ª hora; glicemia = 98 mg/dl; creatinina =\n3,5 mg/dl e K+ = 4,5.","options":{"A":"Osteoporose.","B":"Hiperparatireoidismo primário.","C":"Granuloma Eosinofílico.","D":"Mieloma Múltiplo.","E":"Artrite reumatoide e Síndrome de Felty."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-110407","number":"110407","sourceNumber":"110407","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"\"Doutor (a), eu vim aqui pra o (a) senhor (a) pedir um ultrassom transvaginal pra mim\",\ndisse dona Alzira, 40 anos, quando sentou-se a sua frente para se consultar, na USF \"Beleza\nPura\". Ao ser indagada sobre o porquê de tal demanda, ela refere uma dor em fossa ilíaca direita,\nque ela diz ser \"nos ovário\" (sic). A dor começou há mais ou menos 6 meses, e vem piorando\nlentamente. Refere menstruações regulares, sem atraso menstrual. Ao exame físico, apresenta\npalpação abdominal indolor, sem massas palpáveis, toque vaginal bimanual sem massas palpáveis\ne sem dor à palpação. Manobra de Patrick-Fabere positiva à direita. Sem outras alterações. Dentre\nas abaixo, marque a alternativa que representa a conduta mais adequada:","options":{"A":"Solicitar ultrassom transvaginal.","B":"Solicitar colposcopia.","C":"Solicitar radiografia do quadril.","D":"Solicitar histerossalpingografia.","E":"Encaminhar ao ginecologista."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-110417","number":"110417","sourceNumber":"110417","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Não é sinal de alerta para dor lombar:","options":{"A":"Trauma recente importante.","B":"Perda de peso involuntária.","C":"Postura antálgica.","D":"Idade acima de 70 anos.","E":"Dor refratária ao tratamento, após 6 semanas."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-110421","number":"110421","sourceNumber":"110421","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Adolescente de 15 anos deu entrada na madrugada passada no Hospital de\nEmergência, referindo dor súbita no testiculo\ndireito, que o despertou do sono e persistiu por 02\nhoras, quando então procurou o serviço hospitalar. Sua mãe refere quadro clínico semelhante há\n01 ano, mas que se resolveu espontaneamente. Ele refere que já iniciou atividade sexual e\nalgumas vezes sem proteção. Ao exame, o testículo esquerdo apresentava-se normal, enquanto o\ndireito estava edemaciado, elevado, muito sensível e observou-se que o reflexo cremastérico\nestava ausente. Diante dessa situação qual possível diagnóstico?","options":{"A":"Orquiepididimite","B":"Tumor de testículo","C":"Torção testicular","D":"Hidrocele infectada","E":"Hérnia inguinal estrangulada."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-65914","number":"65914","sourceNumber":"65914","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A literatura demonstra que a litíase urinária afeta a população em uma proporção de\ntrês homens para cada mulher na faixa etária de 20 a 50 anos de idade. Acerca da litíase renal,\nassinale a assertiva correta:","options":{"A":"A hipercalciúria idiopática é a causa mais comum para a formação dos cálculos de oxalato de\ncálcio.","B":"Os mecanismos envolvidos na hipercalciúria estão relacionados a um aumento na absorção\nintestinal principalmente de ferro, enxofre e em pequenas quantidades de cálcio.","C":"Os cálculos de ácido úrico são causados pelo pH urinário alto, pouca ingestão de líquidos e\nhiperuricemia.","D":"A dor tipo cólica é o sintoma mais frequente de litíase urinária e está diretamente associada à\ndesobstrução aguda do sistema coletor.","E":"A forma mais eficiente de tratamento da cólica renal é o uso de analgésicos esteroides,\ninibidores das proteases sanguíneas."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-65930","number":"65930","sourceNumber":"65930","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Dadas as afirmativas abaixo. I- Os adenocarcinomas renais tendem a ocorrer na faixa\netária de 50 a 70 anos de idade, sendo raros antes dos 20 anos; II- Em uma apendicectomia o\ncirurgião deve atenção à artéria apendicular junto ao mesoapêndice; III- Os vólvulos são mais\ncomuns no colo sigmoide, sendo caracterizados pela torção axial de um segmento do intestino\ngrosso sobre o seu mesocolo; IV- A hidrocefalia tem uma incidência de 1-3 por 1000 nascimentos.\nEstá (ão) correta (s):","options":{"A":"Apenas I.","B":"Apenas II e III.","C":"Apenas I, III e IV.","D":"Apenas II, III e IV.","E":"Apenas I, II, III e IV."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-65859","number":"65859","sourceNumber":"65859","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A obstrução é uma das anormalidades importantes do trato urinário. Sobre as uropatias\nobstrutivas, analise as proposições abaixo: I- O primeiro objetivo da terapia é o alívio da\nobstrução;\nII- Os cálculos ureterais podem ser removidos ou contornados por um cateter; III- O prognóstico\ndepende da causa, local e duração da obstrução, grau de dano renal, e descompensação renal.\n\nEstá (ão) correta (s):","options":{"A":"Apenas I e II.","B":"Apenas II e III.","C":"Apenas I.","D":"Apenas III.","E":"I, II e III."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-50027","number":"50027","sourceNumber":"50027","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Qual é o componente mais frequente do cálculo renal?","options":{"A":"Ácido úrico.","B":"Cistina.","C":"Oxalato de cálcio.","D":"Fosfato de cálcio.","E":"Fosfato de amônia-magnesiano."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-351019","number":"351019","sourceNumber":"351019","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Joana, 55 anos, vem em consulta queixando-se de dor lombar há 7 dias. A dor se\niniciou após um dia agitado, em que ajudou na\norganização da festa de aniversário do seu neto,\ntendo erguido bastante peso e brincado com as crianças. Já teve dores semelhantes anteriormente,\nmas sempre tomava um ibuprofeno e a dor resolvia em pouco tempo, mas desta vez não resolveu.\nSobre a abordagem da dor lombar na Atenção Primária à Saúde, assinale a alternativa correta.","options":{"A":"Se houver descrição pela paciente de dor que irradia até a região glútea, já é possível confirmar\nque há associação com radiculopatia.","B":"Quando a dor piora com a movimentação, além da orientação do uso de antiinflamatórios, a\nrecomendação de repouso absoluto é fundamental.","C":"Como é uma lombalgia de início recente, a coleta de alguns dados como a presença de febre, o\nuso crônico de corticóides ou uma história de\ncâncer não é relevante, pois não mudaria a conduta.","D":"A presença de ideias catastróficas em relação à dor e sintomas de depressão ou pessimismo\nsão chamados de ?sinais de alerta amarelos?, sendo\nfatores de risco para recorrência ou\ncronicidade que devem ser abordados pelo médico.","E":"Por ser uma dor de início recente, orientações em relação à mudança de estilo de vida, como\nperda de peso, atividade física ou o uso de\npráticas integrativas e complementares (como\nacupuntura ou yoga) não estão indicadas por não trazerem benefício."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-322042","number":"322042","sourceNumber":"322042","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem de 37 anos é admitido no pronto atendimento com vômitos, dor na região\nlombar e flanco direito e diaforese. Os\nsintomas começaram há 20 minutos e ele não aguenta mais\na dor, não há posição que melhore, está agitado pedindo por ajuda. A enfermeira consegue fazer\numa triagem rápida: taquicárdico (FC = 103 bpm), afebril, oximetria de pulso normal (> 95%), PA =\n134 x 89. Sobre este caso, analise as assertivas abaixo. I) A prescrição de antiespasmódico com\nanalgésico simples é a primeira opção de tratamento medicamentoso pela alta eficácia analgésica.\n\nII) A tomografia computadorizada de abdome permite a visualização de fatores obstrutivos ou\ncálculos na topografia do ureter médio e é\numa opção mais indicada que a ultrassonografia. III) O\ntratamento deve ser realizado com antibioticoterapia endovenosa por 7 dias, inicialmente com\nantibióticos direcionados para germes Gram-negativos e depois escalonados a partir da urocultura,\nse necessário. IV) A presença de dor em flanco direito e taquicardia levam a hipótese diagnóstica\nde apendicite aguda, devendo ser realizada uma laparoscopia diagnóstica para confirmação e\nposterior tratamento. Estão CORRETAS as assertivas:","options":{"A":"Apenas a II.","B":"Apenas a I e III.","C":"Apenas as II e IV.","D":"Apenas as I, II e III.","E":"Todas estão corretas."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-295724","number":"295724","sourceNumber":"295724","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Maria Aparecida, 36 anos, previamente hígida, há 2 horas com dores em flanco direito\ne cólicas, com irradiação para região\ninguinal. Certa de que se tratava de cólica nefrótica, procurou\npronto atendimento. Resolução com analgesia simples parenteral. Já familiarizada com a situação,\npermaneceu em jejum e tomou laxativo, para realização de exames de imagem. RX simples de\nabdome não evidenciou sinais de litíase. Ultrassonografia de aparelho urinário mostrando cálculo\nem ureter distal e múltiplos cálculos renais bilateralmente. Qual a mais provável composição\nmineral destes cálculos e qual a alteração de bioquímica urinária compatível, entre as opções a\nseguir?","options":{"A":"Cistina ? hipocitratúria.","B":"Ácido úrico ? hiperuricosúria.","C":"Oxalato de cálcio ? hiperoxalúria.","D":"Fosfato de cálcio ? hipercalciúria.","E":"Oxalato de cálcio ? hipercalciúria."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-295739","number":"295739","sourceNumber":"295739","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem de 43 anos procura o pronto atendimento referindo dor intensa no escroto\nesquerdo há 6 horas, associada a náuseas e vômitos. Sobre este quadro clinico e o provável\ndiagnóstico, assinale a assertiva que representa a melhor conduta.","options":{"A":"Deve ser encaminhado ao centro cirúrgico.","B":"Deve-se solicitar exames laboratoriais de urina.","C":"Deve-se solicitar ultrassonografia das vias urinárias.","D":"Deve-se solicitar uma urotomografia da bolsa escrotal.","E":"Deve-se solicitar uma ultrassonografia com doppler do escroto."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-257452","number":"257452","sourceNumber":"257452","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Adolescente de 13 anos com hematúria macroscópica, acompanhada de dor lombar\nintermitente, disúria e urgência miccional. Em radiografia simples de abdome visualiza-se imagem\nradiopaca em flanco direito, confirmada por ultrassonografia. Considerando esta situação, analise\nas asserções abaixo e a relação proposta entre elas. I ? Na prevenção de novos episódios está\nindicado uma dieta restritiva de cálcio. PORQUE II ? A principal alteração metabólica responsável\npela gênese desta situação é a presença de hipercalciúria. A respeito destas asserções, assinale a\nopção correta.","options":{"A":"As asserções I e II são proposições verdadeiras, e a II é uma justificativa da I.","B":"As asserções I e II são proposições verdadeiras, mas a II não é uma justificativa da I.","C":"A asserção I é uma proposição verdadeira, e a II é uma proposição falsa.","D":"A asserção I é uma proposição falsa, e a II é uma proposição verdadeira.","E":"As asserções I e II são proposições falsas."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-148998","number":"148998","sourceNumber":"148998","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Em relação à osteoartrite, assinale qual o grupo de articulações mais afetadas:","options":{"A":"Interfalangianas distais, primeira metacarpofalangiana, punhos e joelhos.","B":"Interfalangianas próximais, interfalangianas distais, joelhos e tornozelos.","C":"Primeira metacarpo falangiana, coxofemorais e joelhos.","D":"Interfalangianas proximais, coxofemorais, cotovelos.","E":"Punhos, tornozelos e cotovelos."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-148988","number":"148988","sourceNumber":"148988","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Você atende no pronto-socorro um homem de 32 anos, com rim único e história de 3\ndias de lombalgia irradiada para abdome\ninferior. Refere ainda náuseas e vômitos associados à\ndor, principalmente nas últimas 24h. No primeiro dia do quadro foi atendido na unidade municipal\nde saúde do bairro e, com diagnóstico presumido de infecção de trato urinário, prescrito\namoxicilina. Fez uso de todas as doses do antibiótico, conforme prescrição. Por conta das dores,\ntomou nestes 3 dias 5 comprimidos de paracetamol e 4 comprimidos de anti-inflamatório. Devido ao\nrim único, dosa a creatinina sérica a cada 6 meses. Última dosagem havia sido 15 dias antes com\ncreatinina 0,8 mg/dl. Você repete o exame no pronto-socorro e assusta-se com o atual valor:\ncreatinina 3,1 mg/dl. Enquanto aguarda os demais exames que solicitou, você avalia as possíveis\netiologias para a insuficiência renal aguda do paciente. Em tomografia de abdome e pelve,\nevidenciou-se um cálculo em topografia de bexiga. Ciente do risco de nova formação de cálculos no\nfuturo, você solicita uma pesquisa bioquímica na urina de 24h, para aferir provável causa da\nlitíase.\nQual dos seguintes elementos tem característica inibitória na formação de cálculos, sendo sugerida\nsua reposição dietética ou medicamentosa, caso valor abaixo da referência na urina de 24h em\npacientes com urolitíase?","options":{"A":"Sódio.","B":"Cálcio.","C":"Citrato.","D":"Oxalato.","E":"Ácido úrico."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-126762","number":"126762","sourceNumber":"126762","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Assinale o mapa de envolvimento articular clássico para um paciente com osteoartrite\nde mãos:","options":{"A":"Interfalangianas proximais, distais e metacarpofalangianas.","B":"Interfalangianas distais, primeira carpometacarpiana e punhos.","C":"Interfalangianas proximais, interfalangianas distais e punhos.","D":"Interfalangianas proximais, primeira carpometacarpiana e punho.","E":"Interfalangianas proximais, interfalangianas distais e primeira carpometacarpiana."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-78495","number":"78495","sourceNumber":"78495","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Uma mulher de 68 anos, costureira, refere um quadro álgico em joelho esquerdo.\nRefere que a dor é variável, de leve a\nmoderada intensidade, com início há cerca de 9 meses.\nNega febre, calafrios, eritema, distúrbio de marcha, quedas ou outros traumas. No exame físico não\napresenta sinais significativos de natureza flogística. Você está suspeitando de Osteoartrose (OA).\nNa abordagem do quadro álgico, qual fármaco/via mais apropriado?","options":{"A":"Corticosteroides intra-articulares.","B":"Anti-inflamatórios tópicos.","C":"Analgésicos opioides via oral.","D":"Analgésicos opioides intramusculares.","E":"Corticosteroides intramusculares."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-78498","number":"78498","sourceNumber":"78498","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente masculino, 35 anos, com história de nefrolitíase frequente, vem à consulta\npara orientações sobre a profilaxia desta patologia.\nSobre essa prevenção temos as seguintes\nalternativas: I) Aumentar a ingesta diária de líquidos. II) Restringir a ingesta de proteínas. III)\nDiminuir a ingesta de cálcio. IV) Restringir a ingesta de sódio. Estão CORRETAS as afirmativas:","options":{"A":"I e II.","B":"I, II e IV.","C":"I, III e IV.","D":"II, III e IV.","E":"Todas as afirmativas estão CORRETAS."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-58489","number":"58489","sourceNumber":"58489","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um marco anatômico importante para a identificação fácil dos ureteres durante os\nprocedimentos cirúrgicos pélvicos é:","options":{"A":"Cruzamento com o canal deferente no homem.","B":"Cruzamento com as artérias uterinas na mulher.","C":"Cruzamento pela face anterior dos vasos ilíacos.","D":"Cruzamento com o ligamento redondo da mulher.","E":"Sua proximidade com o anel inguinal interno."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-35062","number":"35062","sourceNumber":"35062","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Levando-se em conta a fisiopatologia da dor ? os mecanismos de transmissão,\nmodulação e da neuroplasticidade e o desafio da\nterapêutica, assinale a alternativa CORRETA:","options":{"A":"Na dor neuropática (neuralgia pós-herpética p.ex.) as drogas de primeira linha são os\nanalgésicos não opioides, AINE e na segunda\nescolha os antidepressivos tricíclicos ou opioides\nfracos","B":"Nas dores nociceptivas de moderada intensidade (dor pós-operatória p.ex.) deveremos\nempregar sempre analgésicos opioides como a\nmorfina e a meperidina e eventualmente o fentanil","C":"Em dores neuropáticas revisões sistemáticas sugerem que tem efetividade similar o uso de\nopioides, antidepressivos tricíclicos, gabapentina ou seu análogo a pregabalina","D":"Nas dores provenientes de câncer são ineficazes o uso de corticoides, pamidronato e os\nbloqueios de nervos","E":"Nos transtornos dolorosos multissomatiformes os antidepressivos dopaminérgicos ou\nantagonistas da COX 2 são as drogas de primeira escolha."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-8454","number":"8454","sourceNumber":"8454","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente do sexo masculino, 55 anos, tabagista, com massa em região cervical. Ao\nexame físico, presença de tumoração cervical\nde 4 cm de diâmetro, firme, de mobilidade reduzida\nem cadeia jugulo-digástrica esquerda. Qual o próximo passo na elucidação diagnóstica?","options":{"A":"Tomografia computadorizada de região cervical, estudando da base do crânio à fúrcula esternal.","B":"Biópsia excisional da massa cervical.","C":"Exame acurado da cavidade oral, faringe e laringe.","D":"Ultrassonografia da massa cervical, orientando punção aspirativa por agulha fina da mesma.","E":"Ressonância magnética de crânio e pescoço para adequado estadiamento."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-360947","number":"360947","sourceNumber":"360947","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Uma história clínica bem coletada e um exame físico minuncioso são as etapas mais\nimportantes no diagnóstico diferencial das desordens reumatológicas. Qual das alternativas abaixo\nrepresenta a manifestação comum às várias colagenoses, porém, sem correlação importante com\nas espondiloartrites?","options":{"A":"Fenômeno de Raynaud.","B":"Entesite.","C":"Psoríase.","D":"Doença inflamatória intestinal.","E":"Dactilite."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-349390","number":"349390","sourceNumber":"349390","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Assinale a alternativa que apresenta, corretamente, o tipo de cálculo urinário mais\ncomum, mundialmente.","options":{"A":"Cálcio mono-hidratado","B":"Estruvita","C":"Fosfato de cálcio","D":"Oxalato de cálcio","E":"Urato"},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-360948","number":"360948","sourceNumber":"360948","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Mulher de 50 anos apresentando dor, deformidade e edema das articulações\ninterfalangianas distais das mãos. Ao exame\nfísico notam-se nódulos duros, típicos nódulos de\nHeberden. Há relato de histórico materno da mesma doença. Qual o diagnóstico e qual a outra\ndoença que acomete com frequência esse mesmo grupo articular, mas com predomínio de sinovite\ne consistência elástica?","options":{"A":"Osteoartrite, Artrite gotosa.","B":"Osteoartrite, Artrite psoriásica.","C":"Artrite reumatoide, Artrite psoriásica.","D":"Artrite reumatoide, Osteoartrite.","E":"Lúpus, artrite reumatoide."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-349412","number":"349412","sourceNumber":"349412","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Quanto à característica do cálculo urinário mais favorável para o tratamento com\nlitotripsia extracorpórea, assinale a alternativa correta.","options":{"A":"Composição de cistina.","B":"Densidade 1000 ? 1300 unidades Hounsfield.","C":"Localização em cálice inferior.","D":"Localização em ureter médio.","E":"5-10 mm de diâmetro."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-349397","number":"349397","sourceNumber":"349397","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Em relação aos conhecimentos sobre litíase renal, assinale a alternativa correta.","options":{"A":"Cirurgias bariátricas disabsortivas reduzem a absorção intestinal e, por consequência, a\nexcreção urinária de oxalato, o que cursa com resolução das hiperoxalúrias.","B":"Dietas hiperproteicas têm efeito protetor quanto à nefrolitíase, por aumentarem a excreção de\ncitrato urinário, o que impede a formação de cálculos de oxalato de cálcio.","C":"A acidificação urinária e agentes uricosúricos, como a probenecida, têm benefício na profilaxia\nde formação de cálculos de urato.","D":"A hidroclorotiazida pode aumentar a calciúria, sendo contraindicada em pacientes com cálculos\nurinários de cálcio.","E":"A suplementação inadvertida de vitamina C está relacionada com o aumento da excreção\nurinária de oxalato, o que pode contribuir para a formação de cálculos urinários."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-349334","number":"349334","sourceNumber":"349334","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem, 50 anos, previamente hígido, sem comorbidades, há 4 meses teve início\ninsidioso de lombalgia, às vezes com\nirradiação para a nádega direita. A dor é pior pela manhã, ao\nacordar. Ficar em pé por mais de 30 minutos causa exacerbação da dor, que é aliviada quando\ndeita. Nega febre ou perda de peso. Exame físico: Lasegue negativo, exame neurológico normal,\nquadris com mobilidade normal e sem dor às rotações interna e externa. O paciente sente dor à\nextensão da coluna lombar e à palpação da coluna vertebral, em topografia de L3 e L4. Com base\nnesses dados semiológicos, assinale a alternativa que apresenta, corretamente, o diagnóstico mais\nprovável.","options":{"A":"Hérnia discal","B":"Fratura vertebral","C":"Espondiloartrite","D":"Espondilose","E":"Síndrome do piriforme"},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-341625","number":"341625","sourceNumber":"341625","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente feminina, 25 anos, internada devido a quadro de pielonefrite. Possui histórico\nde cálculo coraliforme, além de antecedentes\nde infecção de trato urinário (ITU). Na admissão no\nserviço de emergência recebeu infusão de 2000 ml de soro fisiológico, iniciada noradrenalina a 0,05\nmcg/kg/min e ceftriaxona, além de ter sido coletado hemocultura e urocultura. Realizou\nultrassonografia de abdome que mostrou hidronefrose à direita. Após 48 horas na Unidade de\nTerapia Intensiva (UTI), a paciente apresentou piora clínica, com rebaixamento do nível de\nconsciência, oligúria, piora da instabilidade hemodinâmica, com necessidade de aumento de\nnoradrenalina e associação com vasopressina. Coletados exames laboratoriais ? gasometria com\nacidose metabólica, lactato= 25 mmol/l (nl < 2 mmol/l), PCR= 15. Qual a conduta adequada neste\nmomento?","options":{"A":"Avaliação da urologia para nefrostomia.","B":"Novas culturas e troca de antibioticoterapia.","C":"Dobutamina devido a evolução com quadro de miocardiopatia pela sepse.","D":"Anticoagulação para quadro de tromboembolismo pulmonar."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-334198","number":"334198","sourceNumber":"334198","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Qual é o fator isolado mais importante quando da escolha entre litotripsia extracorpórea\npor ondas de choque, ureterorrenolitotripsia e\nnefrolitotripsia percutânea no tratamento de cálculos\nrenais?","options":{"A":"Volume da massa calculosa.","B":"Composição química do cálculo.","C":"Localização do cálculo.","D":"Anormalidades anatômicas.","E":"Biotipo do paciente."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-337897","number":"337897","sourceNumber":"337897","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Os cálculos renais são um dos problemas urológicos mais comuns, cerca de 13% dos\nhomens e 7% das mulheres desenvolverão\ncálculos renais no decorrer de suas vidas e a\nprevalência está aumentando em todo o mundo industrializado. Assinale a alternativa correta: I.\nQuando os cálculos crescem sobre a superfície das papilas renais ou no sistema coletor, sempre\nproduzirão sintomas. II. Os cálculos de estruvita, cistina e ácido úrico geralmente não atigem\ngrandes dimensões, sendo os que mais frequentemente passam pelo ureter sem sintomas. III.\nAlgumas infecções do trato urinário constituem consequências diretas de doenças calculosas. IV.\nAs radiografias sequenciais são necessárias para documentar o crescimento ou o aparecimento de\nnovos cálculos e para se ter certeza que os cálculos eliminados são de fato recém-formados e não\npreexistentes. (Asplin, JR., Coe, FL., Favus, M. Nefrolitíase. EM: Fauci AS. et al. Harrison :\nMedicina Interna. Mc Graw Hill. 17ª Edição. Página 1815 2008.)","options":{"A":"Todas as assertivas estão corretas","B":"Somente as assertivas I e III estão incorretas","C":"Somente as assertivas III e IV estão corretas","D":"Somente a assertiva II está incorreta","E":"Somente a assertiva IV está correta"},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-334213","number":"334213","sourceNumber":"334213","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Uma senhora de 54 anos, portadora de infecção urinária há 2 anos, vem à consulta\nmédica portando um radiografia de abdome, no qual se evidencia um cálculo medindo 3cm, com\nbaixa densidade e formato da pelve e cálices renais, em topografia do rim direito. A urinálise\napresenta pH 7 e piúria, e a urocultura apresentava Proteus mirabilis. Qual é a hipótese mais\nprovável para a composição da urolitíase?","options":{"A":"Oxalato de cálcio.","B":"Ácido úrico.","C":"Estruvita.","D":"Fosfato de cálcio.","E":"Cistina."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-334230","number":"334230","sourceNumber":"334230","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Qual das afirmativas abaixo está correta?","options":{"A":"Síndrome de Horner, com náuseas ou tonturas é ocasionada por lesão de gânglios simpáticos\napós colisões automobilísticas com hiperflexão\nda coluna cervical.","B":"Compressão da raiz L5 desencadeia dor na região anterior da coxa e medial da perna com\nperda do reflexo patelar.","C":"Compressão da raiz C6 é responsável pela perda sensitiva nos 3º e 4º dedos e do reflexo\ntricipital com dor na face externa do braço até o dedo médio.","D":"Ressonância Magnética e VHS devem ser incluídos na investigação inicial de pacientes com\nmenos de 50 anos de idade com dor mecânica de\nforte intensidade em coluna vertebral.","E":"Dor lombosacra que se irradiada para as pernas após caminhada de 50 a 100 metros, e melhora\nao ficar sentado ou flexionar a coluna pode\nser caracterizada estenose do canal vertebral."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-341672","number":"341672","sourceNumber":"341672","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Com relação ao manejo da cólica nefrética e cálculos urinários selecione a sentença\nINCORRETA:","options":{"A":"Em pacientes com obstrução urinaria, infectados, com piora da função renal há necessidade de\nintervenção urológica precoce para desobstrução.","B":"Existe benefício no uso da tansulosina 0,4 mg uma vez ao dia, na terapia expulsiva para cálculos\nde 5 mm a 10 mm de diâmetro ureteral.","C":"Pacientes com quadro doloroso e cálculos maiores de 10 mm ureteral em geral tem indicação de\nanalgesia e tratamento clínico.","D":"As opções para intervenção urológica e retirada de cálculos incluem ureteroscopia e litotripsia\nextracorpórea."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-320967","number":"320967","sourceNumber":"320967","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Assinale a alternativa que apresenta, corretamente, a anormalidade mais comum\nidentificada em pacientes com cálculos de ácido úrico.","options":{"A":"Acidose tubular renal distal.","B":"Alta concentração de ácido úrico sérico.","C":"Baixa concentração de ácido úrico urinário.","D":"Urina ácida.","E":"Urina alcalina."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-320968","number":"320968","sourceNumber":"320968","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Assinale a alternativa que apresenta, corretamente, o tratamento clínico de litíase\nurinária mais apropriado para um paciente com diátese gotosa.","options":{"A":"Alopurinol.","B":"Citrato de potássio.","C":"Fluidos aumentados.","D":"Restrição de cálcio na dieta.","E":"Tiazidas."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-292105","number":"292105","sourceNumber":"292105","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Assinale a alternativa que apresenta, CORRETAMENTE, o teste laboratorial inicial que\npromove a pista diagnóstica mais importante em pacientes com cálculo urinário de ácido úrico.","options":{"A":"pH da urina.","B":"Cálcio na urina.","C":"Sódio na urina.","D":"Níveis séricos de ácido úrico.","E":"Níveis urinários de ácido úrico."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-314817","number":"314817","sourceNumber":"314817","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Uma paciente faxineira de hotel obesa com 38 anos tem lombalgia há uma semana. A\nhistória e o exame físico não apresentam ?bandeiras vermelhas?, e o exame físico é normal,\nexceto pela obesidade. Qual das seguintes afirmações é o melhor próximo passo?","options":{"A":"Doses regulares de analgésicos não-narcóticos.","B":"Seis semanas de repouso no leito.","C":"Ressonância magnética da coluna lombar.","D":"Radiografia simples de coluna lombossacra."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-314818","number":"314818","sourceNumber":"314818","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Uma mulher de 72 anos tem história de quatro semanas de lombalgia, fraqueza\ngeneralizada e perda de 7,5 kg de peso nos\núltimos dois meses. Sua história médica não tem nada\ndigno de nota, e o exame físico é normal, exceto pela fraqueza geral. Os exames iniciais mostram\naumento da velocidade de hemossedimentação, anemia leve, creatinina sérica de 1,8 mg/dL e nível\nsérico de cálcio de 11,2 mg/dL. Qual é o diagnóstico mais provável?","options":{"A":"Osteoporose com fraturas por compressão.","B":"Insuficiência renal crônica com osteodistrofia.","C":"Mieloma múltiplo.","D":"Osteomielite."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-314819","number":"314819","sourceNumber":"314819","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Uma mulher de 62 anos tem mieloma múltiplo e aumento de nível de cálcio. Qual dos\nseguintes tratamentos é útil na hipercalcemia?","options":{"A":"Bifosfofonatos.","B":"Eritropoetina.","C":"Melfalan.","D":"Interferon Alfa."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-312059","number":"312059","sourceNumber":"312059","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente com cólica nefrótica direita há três dias, hoje inicia com febre, calafrios,\ntaquicardia e piora do estado geral. Exames\nlaboratoriais apresentam leucocitose importante com\ndesvio a esquerda, fez um Raio X de abdôme que não apresentou alterações, assinale a alternativa\ncorreta.","options":{"A":"a ressonância magnética seria o exame de escolha para esse paciente","B":"a conduta correta seria prescrição de analgésicos e alta se melhora da dor","C":"o raio X tem sensibilidade diminuída para cálculos de ácido úrico","D":"a tomografia não se aplica nesse caso, já que a principal suspeita é cólica nefrética e a\ncreatinina pode estar alterada","E":"caso os exames de imagem apresente diagnóstico de ureterolitíase à direita a primeira escolha\nseria ureterolititotomia aberta"},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-313012","number":"313012","sourceNumber":"313012","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"As lombalgias são queixas comuns na prática clínica, apresentando etilogias diversas.\nSão considerados sinais de alerta para lombalgias,\nexceto","options":{"A":"Déficit neurológico associado, incluindo bexiga neurogênica e síndrome da cauda equina.","B":"Febre e perda ponderal inexplicados.","C":"Imunossupressão.","D":"Agravo da dor a noite/ repouso.","E":"Dor com características mecânicas, agravo ao esforço."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-297171","number":"297171","sourceNumber":"297171","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Em relação ao cálculo renal assinale a alternativa CORRETA:","options":{"A":"Ph urinário < 5 facilita a formação de cálculos de ácido úrico e cistina; Ph > 6 facilita\nformação de\ncálculos de estruvita e hidroxiapatita.","B":"A nefrolitíase é até três vezes mais frequente em mulheres do que em homens e seu pico de\nincidência é entre 40 e 50 anos sobretudo em mulheres com sobrepeso.","C":"Aproximadamente todos os pacientes com cálculo nas vias urinárias são sintomáticos, tendo\npiora do quadro clínico quando o cálculo obstrui as vias urinárias.","D":"Em relação aos exames complementares o parcial de urina é um exame diagnóstico. A presença\nde hematúria e cristalúria garante a presença de\ncálculo."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-313037","number":"313037","sourceNumber":"313037","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente assintomático de 54 anos faz a primeira consulta com seu urologista e detecta\ncálculo de 1,8cm no cálice inferior do rim direito. O histórico clínico e características do cálculo\nsugerem tratar-se de litíase úrica. Qual é o tratamento mais adequado neste momento?","options":{"A":"Tratamento clínico visando alcalinização da urina.","B":"Cirurgia renal percutânea.","C":"Tratamento medicamentoso expulsivo.","D":"Litotripsia extracorpórea por ondas de choque.","E":"Uretero-endolitotripsia flexível."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-297202","number":"297202","sourceNumber":"297202","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Marcela, 57 anos, reclama de dor nos joelhos. A dor iniciou há 4 meses, piora com os\nmovimentos e melhora com longos períodos de repouso, sem irradiação e sem evidências de sinais\ninflamatórios nesta ou em qualquer outra articulação. Tem índice de massa corporal (IMC) de 32\nkg/m². Conta que a dor iniciou após iniciar algumas caminhadas para controlar o peso e que não há\nlimitação de suas atividades diárias. Ao exame físico, apresenta leve aumento de partes moles nos\njoelhos e crepitações. Sobre a conduta diagnóstica (considerando o diagnóstico mais provável) e\nterapêutica marque a alternativa CORRETA:","options":{"A":"o médico deve prontamente contraindicar atividade física e aguardar a melhora do quadro para\nretorno das caminhadas.","B":"A intervenção focada na perda de peso, com envolvimento multiprofissional deve ser um dos\npilares do tratamento.","C":"Caso sejam solicitadas radiografias das articulações afetadas, apresentam boa sensibilidade\ndiagnóstica para quadros iniciais, como o de Marcela.","D":"Antiinflamatório não esteroidal tópico não deve ser usado, tendo pouca eficácia no controle da\ndor."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-261572","number":"261572","sourceNumber":"261572","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Até 90% das pessoas terão dor lombar em algum momento da vida. É uma das cinco\ncausas mais comuns de atendimento de\nurgência/emergência e é a principal causa de absenteísmo\ne aposentadoria por invalidez antes dos 45 anos de idade. Sendo assim, é considerada um\nproblema de saúde pública. Sobre dor lombar, assinale a alternativa CORRETA:","options":{"A":"Existem indicações precisas para realização de exames de imagem para investigação de dor\nlombar, um exemplo são as red flags. Exames mal indicados podem levar a procedimentos\ndiagnósticos e tratamentos fúteis.","B":"Deve sempre ser avaliada por um ortopedista especialista em coluna, para excluir causas\ngraves.","C":"Tratar a dor lombar crônica com anti-inflamatórios não esteroidais é uma prática médica\nconsiderada adequada, já que seus efeitos\ncolaterais (lesão de mucosa gástrica, insuficiência renal)\nsão facilmente manejados por um bom clínico.","D":"A causa mais comum de dor lombar é a hérnia de disco, com sintomas de irradiação nervosa\npara membros inferiores, e o tratamento padrão\nouro é a laminectomia.","E":"Retenção urinária, febre, perda ponderal, histórico de câncer e anemia não são considerados\nred flags para investigação de dor lombar."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-284005","number":"284005","sourceNumber":"284005","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente masculino, 38 anos, chega à Emergência de hospital de nível terciário com\nquadro de intensa dor intermitente em\nflanco direito com irradiação para testículo do mesmo lado,\niniciada há cerca de 30 minutos, acompanhada de vômitos, e urina escura. Com este quadro\nclínico, qual o diagnóstico e o exame complementar de primeira escolha para o caso:","options":{"A":"Torção de testículo direito - Ultrassom de testículo.","B":"Cálculo em ureter direito - Tomografia computadorizada de abdome total sem contraste.","C":"Cálculo em ureter esquerdo - Ultrassom de Aparelho e vias urinárias.","D":"Cálculo vesical - Tomografia computadorizada de abdome inferior com contraste."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-262875","number":"262875","sourceNumber":"262875","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente masculino, 38 anos, chegou ao Pronto Socorro com dor de início súbito,\nintermitente e de muito forte intensidade em\nregião de fossa ilíaca esquerda e flanco esquerdo.\nConsiderando-se o diagnóstico de cálculo do trato urinário, impactado no ureter, de\naproximadamente 1,5cm, e composto de oxalato de cálcio, assinale a alternativa correta em relação\nao que se espera observar nos exames de imagem:","options":{"A":"A ultrassonografia de abdome pode mostrar a localização do cálculo e presença ou não de\nrefluxo vesico-ureteral associado.","B":"A radiografia simples de abdome pode mostrar o tamanho do cálculo e possível dilatação\nureteral.","C":"A urografia excretora pode mostrar a localização do cálculo e possível dilatação ureteral\nassociada.","D":"A uretrocistografia miccional mostra alterações da filtração glomerular e o local de obstrução\npelo cálculo."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-265438","number":"265438","sourceNumber":"265438","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A investigação de um paciente com litíase renal detectou infecção bacteriana, o\npaciente referiu que apresentou inúmeros episódios anteriores de infecção. Qual a composição\nquímica mais provável do cálculo?","options":{"A":"Acido úrico.","B":"Cistina.","C":"Fosfato amoníaco-magnesiano.","D":"Fosfato de cálcio.","E":"Oxalato de cálcio."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-269568","number":"269568","sourceNumber":"269568","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Uma senhora de 60 anos vem à consulta relatando que há mais de 1 ano notou\naumento de volume e dor em articulações\ninterfalangianas distais e proximais em ambas as mãos,\nde forma assimétrica, com dificuldade de mobilizar a articulação por poucos minutos no início do\ndia, especialmente nos dias mais frios. Relata que as dores melhoram parcialmente com o uso de\nanalgésicos simples, como paracetamol e dipirona. Não há evidência de acometimento de outras\narticulações, perda ponderal ou relato de febre. Diante do quadro clínico exposto, o diagnóstico\nprovável é de:","options":{"A":"Osteoartrite, podendo haver algum benefício com o uso de anti-inflamatórios tópicos para\ncontrole dos sintomas.","B":"Artrite reumatoide, sendo indicado início de tratamento com prednisona em dose baixa e\nmetotrexato.","C":"Osteoartrose, indicando o uso crônico de corticoide em doses moderadas para melhor controle\ndos sintomas.","D":"Artrite reumatoide, sendo indicado o uso de medicações com ação anti-TNF, como o infliximabe.","E":"Artrite paraneoplásica, sendo indicado o tratamento da doença de base, o que fará melhorar o\nquadro atual."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-265482","number":"265482","sourceNumber":"265482","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Das alternativas abaixo, qual é a correta?","options":{"A":"Dor irradiada para as pernas que aparece após caminhada e melhora flexionando a coluna ou\nna posição sentada caracteriza estenose do\ncanal vertebral.","B":"Dor na região anterior da coxa e medial da perna com perda do reflexo patelar ocorre na\ncompressão da raiz L5.","C":"Perda sensitiva nos 3º e 4º dedos e perda do reflexo tricipital com dor na face externa do braço\naté o dedo médio ocorre por compressão da\nraiz C6.","D":"Ressonância Magnética e VHS devem ser incluídos na investigação inicial de pacientes com\nmenos de 50 anos de idade com dor mecânica de\nforte intensidade em coluna vertebral.","E":"Síndrome de Horner, com náuseas ou tonturas é ocasionada por lesão de gânglios simpáticos\napós colisões automobilísticas com hiperflexão\nda coluna cervical."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-269605","number":"269605","sourceNumber":"269605","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Rogério, 62 anos, peso 105 kg, altura 165 cm, queixa-se de dor nas costas há 2 meses;\napontando para a região dorsal esquerda e dizendo que a dor piora ao se movimentar e melhora\nem repouso. Tem feito algumas caminhadas e pedaladas, mas com dificuldade por conta de uma\nartrose no joelho esquerdo. Em relação a esse caso, assinale a alternativa correta.","options":{"A":"Na consulta médica é preciso investigar os sinais de alerta vermelhos (red flags), como trauma\nrecente, febre e fatores psicossociais.","B":"O exame físico para lombalgia passou a ter menor valor diagnóstico com o crescente uso de\nexames de imagem.","C":"Apesar de ser uma queixa muito prevalente na atenção primária, a maioria dos casos precisará\nde avaliação em ambulatório especializado.","D":"A história ocupacional e recreacional pode fornecer informações valiosas para o diagnóstico e\ntratamento.","E":"As ideias e expectativas do paciente em relação aos seus sintomas não contribuem para o\nmanejo na atenção primária nesses casos."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-284066","number":"284066","sourceNumber":"284066","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A artéria Testicular é ramo da:","options":{"A":"Artéria Íliaca interna.","B":"Artéria Femoral.","C":"Artéria Ilíaca externa.","D":"Artéria Aorta."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-261191","number":"261191","sourceNumber":"261191","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Qual a avaliação necessária para melhor diagnóstico e planejamento de pacientes com\nlitíase renal complexa que deverão ser submetidos a tratamento cirúrgico como nefrolitotripsia\npercutânea? Assinale a alternativa correta:","options":{"A":"Tomografia computadorizada.","B":"Urografia excretora.","C":"Ultrassonografia.","D":"Ressonância magnética."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-266198","number":"266198","sourceNumber":"266198","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Rouleaux eritrocitário, anemia, pico de gamaglobulina em eletroforese de proteínas\nséricas, proteinúria, o diagnóstico mais provável:\nCURRENT 2019 ? CAPÍTULO 13 PÁG 547.","options":{"A":"Crioglobulinemia;","B":"Leucemia Linfocitica Crônica","C":"Cirrose biliar primária;","D":"Mieloma Múltiplo;","E":"Insuficiência renal Crônica"},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-239109","number":"239109","sourceNumber":"239109","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem de 35 anos está em sua primeira crise de cólica renal. TC abdome e pelve\nevidencia cálculo uretral proximal de 5 mm, sem sinais obstrutivos. A conduta inicial mais\napropriada é:","options":{"A":"Ureterolitotripsia com laser.","B":"Colocação de stent ureteral (duplo-J).","C":"Litotripsia extracorpórea.","D":"Conduta expectante."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-251013","number":"251013","sourceNumber":"251013","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Considere paciente masculino, 62 anos, em investigação de astenia, perda ponderal e\ndores ósseas. Retorna a consulta com os seguintes exames laboratoriais (em parênteses os\nvalores de referência): Creatinina 2,0 mg/dl (1,2mg/dl), Cálcio 12,5 mg/dl (10,5mg/dl), Hemoglobina\n8,5g/dl (12,5g/dl), fósforo inorgânico 1,2mg/dl (2,5 a 4,5mg/dl), pH 7,2, bicarbonato 12 mEq/L (22 a\n26 mEq/L), potássio 2,8 mEq/L (3,5 a 5 mEq/L). pH urinário 5 (5.5 a 7) Baseado nas hipóteses\ndiagnósticas para os dados acima, assinale a melhor alternativa:","options":{"A":"A nefropatia do mieloma múltiplo acontece por formação de cilindros de cadeia leve (rim de\nmieloma) e pela hipercalcemia. A\ndisfunção tubular proximal, incluindo acidose tubular renal tipo 2 e\nsíndrome de Fanconi podem estar presentes, porém o laboratório do paciente acima não é\ncompatível com o diagnóstico por haver hipofosfatemia.","B":"A nefropatia do mieloma múltiplo acontece por formação de cilindros de cadeia leve (rim de\nmieloma) e pela hipercalcemia. A\ndisfunção tubular proximal, incluindo acidose tubular renal tipo 2 e\nsíndrome de Fanconi podem estar presentes, porém o laboratório do paciente acima não é\ncompatível com o diagnóstico por haver hipocalemia.","C":"A nefropatia do mieloma múltiplo acontece por formação de cilindros de cadeia leve (rim de\nmieloma) e pela hipercalcemia. A\ndisfunção tubular proximal, incluindo acidose tubular renal tipo 2 e\nsíndrome de Fanconi podem estar presentes, porém o laboratório do paciente acima não é\ncompatível com o diagnóstico por haver acidificação da urina.","D":"A nefropatia do mieloma múltiplo acontece por formação de cilindros de cadeia leve (rim de\nmieloma) e pela hipercalcemia. A\ndisfunção tubular proximal, incluindo acidose tubular renal tipo 2 e\nsíndrome de Fanconi podem estar presentes, quadro compatível com o laboratório do paciente\napresentado."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-242002","number":"242002","sourceNumber":"242002","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Qual agente único preferido para expulsão medicamentosa de cálculo ureteral distal?","options":{"A":"Nifedipina.","B":"Solu-medrol.","C":"Tansulosina.","D":"Ibuprofeno.","E":"Terazosina."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-238449","number":"238449","sourceNumber":"238449","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Uma paciente de 72 anos queixa-se em consulta ambulatorial de dor nas mãos de\ninício há 2 anos, com rigidez matinal de aproximadamente 20 minutos. Refere que a dor é\npredominantemente em dedos, nega dor em punhos e que piora quando trabalha muito. Abaixo\nestá uma foto do exame físico da paciente. Qual o provável diagnóstico da paciente?","options":{"A":"Osteoartrite","B":"Artrite Reumatoide","C":"Artrite Psoriasica","D":"Espondilite anquilosante","E":"Artrite gotosa"},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":["question_bank/media/medcurso/med-cirurgia-med-cir-07/238449.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-238479","number":"238479","sourceNumber":"238479","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A litíase urinária na vigência de obstrução pode ter alta morbidade e mortalidade,\nespecialmente com infecção concomitante. Um\npaciente com cálculo urinário obstrutivo com febre e\nurina infectada necessita de drenagem de emergência com stent ureteral tipo duplo J.\nOcasionalmente tais cateteres são incapazes de ultrapassar o calculo agressor. Nestes casos:","options":{"A":"Deve- se realizar ureterorrenolitotipsia endoscópica com retirada dos fragmentos de cálculo.","B":"Realiza-se nefroscopia percutânea com retirada retrógrada do cálculo.","C":"Coloca-se apenas uma sonda Foley vesical para diminuir a pressão hidrostática do trato urinário.","D":"Coloca-se uma sonda de nefrostomia percutânea para drenagem e melhora do quadro.","E":"Realiza-se cirurgia aberta para retirada do cálculo e reconstrução do trato urinário."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-239179","number":"239179","sourceNumber":"239179","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Homem de 55 anos, com doença degenerativa da coluna vertebral, apresenta quadro\nrecorrente de dor lombar intensa,\nincapacitante, com irradiação para região posterolateral da coxa e\nperna direita, associado a déficits sensitivos no hálux e dorso do pé direito, e fraqueza motora\nenvolvendo os músculos tibial anterior e extensor longo do hálux. Foi solicitado exame de imagem\nda coluna vertebral para estudo diagnóstico. Diante da história e apresentação clínica, qual a opção\nterapêutica mais apropriada para este paciente?","options":{"A":"Instrumentação e artrodese da coluna lombar.","B":"Fisioterapia, analgésicos e esteroides por via oral.","C":"Repouso por 4 a 8 semanas, analgésicos e relaxante muscular.","D":"Repouso por 4 semanas, analgésicos e injeção epidural de esteroides."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-200185","number":"200185","sourceNumber":"200185","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Mulher, 29 anos de idade, com história prévia de litíase renal, sem outras\ncomorbidades, iniciou há 5 dias com disúria,\npolaciúria, febre e dor em flanco esquerdo, procura o\npronto-socorro e recebe o diagnóstico de pielonefrite. Após realizar a ressuscitação volêmica\nadequada, a paciente mantém-se hipotensa e não apresenta melhora do quadro geral apesar de\nterapia antimicrobiana adequada. Foi realizada investigação com exames de imagem e detectada\nobstrução do ureter esquerdo por litíase renal. Considerando esse caso, assinale a alternativa que\napresenta, corretamente, a conduta mais adequada para essa paciente.","options":{"A":"Inserir stent ureteral por cistoscopia.","B":"Manter a terapia instituída e aguardar de 48 a 72 horas.","C":"Realizar laparotomia exploradora por hipótese de apendicite.","D":"Solicitar coleta de líquido cefalorraquidiano.","E":"Suspender antibiótico, já que a causa da dor é unicamente pela obstrução ureteral."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-219283","number":"219283","sourceNumber":"219283","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Mulher, 56 anos, apresenta-se com infecções urinárias de repetição e dor lombar\nesquerda há 3 meses. Antecedentes Pessoais:\nHipertensão arterial sistêmica, diabetes melito tipo\n\n2. Ultrassonografia de abdome total: cálculo único de 2,5 cm de diâmetro no polo inferior do rim\nesquerdo, sem hidronefrose, Tomografia computadorizada de abdome: cálculo no cálice inferior\nposterior de rim esquerdo, de alta intensidade, sem hidronefrose, parênquíma renal preservado,\ndistância da pele ao cálculo de 8 cm. A conduta mais adequada é:","options":{"A":"Nefrolitotrispsia percutânea.","B":"Litotripsia extracorpórea por ondas de choque.","C":"Ureteroscopia flexível e fragmentação com laser.","D":"Nefrolitotomia radial por laparoscopia.","E":"Nefrectomia esquerda."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-209025","number":"209025","sourceNumber":"209025","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A composição química dos cálculos renais conhecidos como \"cálculos de infecção\" é:","options":{"A":"Ácido úrico","B":"Cistina","C":"Fosfato amoníaco-magnesiano","D":"Fosfato de cálcio","E":"Oxalato de cálcio"},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-209997","number":"209997","sourceNumber":"209997","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Na torção do cordão espermático é correto afirmar que: (MOSCONI A, CLARO JFA,\n\nANDRADE E, FVICENTINI F, PARANHOS MLS. Escroto agudo. Rev Med (São Paulo). 2008\n\njul.-set.;87(3):178-83. KOFF WJ. Doenças comuns em urologia. Em: DUNCAN BB, SCHMIDT MI,\nGIUGLIANI ERJ. Medicina ambulatorial: condutas de atenção primária baseadas em evidência.\n\nArtmed. 2006.)","options":{"A":"Não se constitui um quadro emergencial, pois a viabilidade do testículo com torção do cordão\nespermático é de 24 a 48 horas.","B":"O diagnóstico pode ser feito pela ecografia testicular.","C":"O Ecodoppler poderá demonstrar a ausência de fluxo sanguíneo testicular.","D":"O sinal de Prehn, frequentemente presente na epididimite e ausente na torção testicular, fornece\ninformação para o diagnóstico diferencial entre ambos os quadros.","E":"A torção extravaginal do testículo é a forma mais comum de torção e ocorre em recém-nascidos,\nnos primeiros dias de vida, na fase final da\nfixação dos destes."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-210047","number":"210047","sourceNumber":"210047","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A lombalgia ocupacional apresenta etiologia multifatorial, elevada prevalência e\nincidência. Caracterizada por quadro de dor de variada duração e intensidade, a dor lombar pode\nlevar à incapacidade laborativa e à invalidez. A lombalgia acarreta sofrimento aos trabalhadores,\ncustos às empresas, aos sistemas previdenciário e assistencial de saúde. Avalie o caso a seguir:\n\n?Funcionária de um restaurante, obesa, 35 anos, relata lombalgia há uma semana. A história e o\nexame físico não sugeriram nenhuma doença,\nexceto a obesidade. Qual das alternativas abaixo é a\nmelhor opção para esse caso ? (TOY, PATLAN. Casos clínicos em medicina interna. Mc Graw Hill.\nTerceira Edição. 2011; JUNIOR MH et al. Lombalgia ocupacional. Rev Assoc Med Bras 2010; 56(5):\n583-9).","options":{"A":"Prescrever analgésicos não narcóticos e manter as atividades que não exacerbem a dor.","B":"Prescrever repouso no leito por seis semanas.","C":"Solicitar ressonância magnética da coluna lombar.","D":"Solicitar radiografia simples da coluna lombossacral.","E":"Nenhuma das alternativas acima é a melhor opção para o caso."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-202557","number":"202557","sourceNumber":"202557","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"No caso de hérnia de disco lombar, a alternativa que correlaciona corretamente a raiz\nlesada com a alteração clínica produzida é:","options":{"A":"L4 ? alteração do reflexo aquileu.","B":"L4 ? alteração motora do músculo gastrocnêmio.","C":"L4 ? alteração da sensibilidade na face lateral do pé.","D":"L5 ? alteração do reflexo patelar.","E":"L5 ? alteração motora do músculo glúteo médio."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-179018","number":"179018","sourceNumber":"179018","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Litíase renal é uma doença frequentemente diagnosticada em Unidades de Pronto\nAtendimento, com recorrência de\naproximadamente 50% dos pacientes se não forem submetidos a\nnenhum tipo de tratamento. A dor associada a cálculo ureteral é resultado de: ( Glenn S. Gerber\nand Charles B. Brendler. Evaluation of urologic patient: History, Physical Examination and\nUrinalysis. Campbell Walsh Elsevier 2012.)","options":{"A":"Obstrução e distensão da pelve renal","B":"Irritação da mucosa ureteral pelo cálculo","C":"Peristaltismo excessivo em resposta a obstrução","D":"Irritação intramural do ureter","E":"Extravasamento urinário por rompimento de cálice renal"},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-173913","number":"173913","sourceNumber":"173913","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"D. Sophia tem 55 anos, é mãe de 2 filhos adultos e casados, tem 5 netos e é frentista.\nIniciou com dor lombar localizada há 5\nmeses. Veio à unidade de saúde e foi tratada com\nIbuprofeno em dose adequada e fisioterapia. Retorna hoje com persistência e piora da dor que a\nacorda de madrugada. Sente também parestesias em região perineal. Sobre o caso, assinale a\nalternativa CORRETA quanto à conduta na Atenção Primária à Saúde.","options":{"A":"O quadro é de lombalgia mecânica e deve ser prescrito analgésico opioide por via oral, além de\nterapias complementares como acupuntura.","B":"O quadro decorre de hérnia discal e deve ser prescrito anti-inflamatório hormonal intramuscular\nassociado à fisioterapia.","C":"O quadro é de lombalgia mecânica, o tratamento precisa de otimização e pode ser radiografada\na coluna, sem a necessidade de outras\navaliações.","D":"Deve-se tranquilizar D. Sophia quanto a benignidade do quadro, embora de difícil tratamento, e\notimizar o tratamento conservador na unidade de saúde.","E":"Deve-se solicitar a radiografia de coluna e referenciar a paciente para investigação\ncomplementar."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-172629","number":"172629","sourceNumber":"172629","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente do sexo feminino de 24 anos vem à consulta urológica com um histórico prévio\nde dor lombar esquerda há cerca de 1 ano.\nRefere quadros de infecção urinária de repetição, os\nquais ?nunca curaram com antibiótico? (sic). Relata que apresenta pelo menos 4 episódios de\ninfecção urinária por ano desde os 16 anos de idade. No exame físico, apresenta discreto\ndesconforto à palpação da loja renal esquerda. Traz consigo uma tomografia computadorizada de\num mês atrás que mostra um cálculo coraliforme parcial (envolvendo a pelve renal e os cálices\ninferior e médio) do lado esquerdo, com 3,2 cm no maior eixo, com discreta hidronefrose. Rim\ndireito normal, bexiga normal. Não se evidenciam cálculos no ureter. Considerando que atualmente\na paciente não apresenta infecção urinária e seus exames laboratoriais são normais, qual é a\nmelhor opção de tratamento?","options":{"A":"Tratamento clínico com alcalinização da urina com citrato de potássio.","B":"Litotripsia extracorpórea.","C":"Ureterorrenolitotripsia flexível.","D":"Observação somente, pois não há sinais de hidronefrose acentuada.","E":"Nefrolitotripsia percutânea."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-183536","number":"183536","sourceNumber":"183536","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"O principal fator responsável pela dor típica associada a presença de cálculo ureteral\nè:","options":{"A":"Irritação da mucosa uretral causada pelo processo inflamatório local desencadeado pela\npresença do cálculo","B":"Espasmo uretral excessivo em resposta a presença do cálculo","C":"Irritação da porção intramural do ureter causada pela liberação de mediadores inflamatórios\nlocais","D":"Obstrução do fluxo urinário com consequente distensão da cápsula renal"},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-178453","number":"178453","sourceNumber":"178453","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Que composição tem a maior parte dos cálculos coraliformes?","options":{"A":"Ácido úrico","B":"Fosfato amoníaco magnesiano","C":"Carbonato de cálcio","D":"Oxalato de cálcio","E":"Fosfato de cálcio"},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-178458","number":"178458","sourceNumber":"178458","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente de 26 anos de idade, gestante na 21ª semana de gravidez. Vem ao hgospital\ncom cólica renal à direita iniciada há 7 dias.\nInvestigação detectou cálculo em ureter proximal à\nesquerda de 7 milímetros localizado há 2 centímetros abaixo da junção ureteropiélica. Apresenta-se\nem regular estado geral, porpem com febre. Parcial de urina revelou uma leucocitúria (maior que\n500.000 leucócitos/mm³) e bacilos gram negativos +++. O leucograma apresenta uma leucocitose\ncom desvio dos neutrófilos à esquerda. Qual deve ser o procedimento urológico imediato?","options":{"A":"Litotripsia extra corpórea.","B":"Nefrectomia Esquerda.","C":"Ureterolitotomia.","D":"Ureterorrenolitopripsia flexível.","E":"Cateter duplo J."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-173109","number":"173109","sourceNumber":"173109","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"O termo espondiloartrite abrange um grupo de doenças com características clínicas,\nepidemiológicas, anatomopatológicas, radiológicas e imunogenéticas em comum. Em relação às\nespondiloartrites, atribua V (Verdadeiro) ou F (Falso) às afirmativas a seguir: ( ) Balanite\ncircinada,\nqueratodermia blenorrágica e úlceras orais são manifestações da artrite reativa; ( ) Sacroileíte\nassimétrica e sindesmófitos não marginais são os achados radiográficos típicos da espondilite\nanquilosante; ( ) HLA-B27 é o principal fator de susceptibilidade para espondilite anquilosante e\nestá diretamente relacionado à patogênese da doença; ( ) HLA-B27 é responsável por cerca de\n30% do risco genético total de ter espondilite anquilosante; ( ) Fibrose pulmonar bibasal e estenose\naórtica são manifestações extra-articulares da espondilite anquilosante. Assinale a alternativa que\ncontém, de cima para baixo, a sequência CORRETA.","options":{"A":"V, V, V, F, F.","B":"V, V, F, F, F.","C":"V, F, V, V, F.","D":"F, V, F, F, V.","E":"F, F, V, V, V."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-154851","number":"154851","sourceNumber":"154851","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"No tratamento da dor, associe as colunas e escolha a alternativa com a sequência\nCORRETA: (Conforme imagem do caderno de\nquestões) (ADELMAN AM. DALY MP. 20 problemas\ncomuns - Geriatria. Editora Revinter. Capítulo 2. 2004.)","options":{"A":"I-II-III.","B":"II-I-II.","C":"III-III-I.","D":"III-II-I.","E":"II-I-I."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":["question_bank/media/medcurso/med-cirurgia-med-cir-07/154851.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-160051","number":"160051","sourceNumber":"160051","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente da entrada na UBS com queixa de dor abdominal iniciada em epigástrio há\n12h e agora localizada em fossa ilíaca\ndireita, relata ainda febre e anorexia desde o início da dor.\nAo exame físico apresenta abdome doloroso a palpação da fossa ilíaca direita com os sinais de\nRovsing, Blomberg e Lenander positivos. O médico de família e comunidade que o recebe na\nUnidade formula a hipótese diagnóstica de apendicite aguda:","options":{"A":"O diagnóstico da apendicite aguda é baseado principalmente na história clínica e nos achados\nde exame físico.","B":"Nas crianças em idade escolar a gastroenterite aguda é um dos principais diagnósticos\ndiferenciais.","C":"Estudos de medicina nuclear com leucócitos marcados podem ser usados para a avaliação de\npacientes com suspeita de apendicite aguda.","D":"O tratamento da apendicite agudo não complicado é a cirurgia de urgência.","E":"Todas estão corretas."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-149998","number":"149998","sourceNumber":"149998","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A macroglobulinemia de Waldenström é uma neoplasia linfoplasmocitária que secreta\ncaracteristicamente qual imunoglobulina?","options":{"A":"IgA.","B":"IgD.","C":"IgE.","D":"IgG.","E":"IgM."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-154896","number":"154896","sourceNumber":"154896","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A dor lombar ou lombalgia é uma queixa ambulatorial comum e acompanha o ser\nhumano desde que este assumiu a postura\nereta. Relacione os principais achados neurológicos\ndecorrentes de radiculopatias, com as raízes nervosas L4, L5, S1 e S2-S5 comprometidas,\nconforme a distribuição nos quadros abaixo, e assinale a alternativa CORRETA: (SOIBELMAN M,\nSCHENATTO CB, RESTELLI VG. Dor lombar. Em: DUNCAN BB, SCHMIDT MI, GIUGLIANI ERJ.\n\nMedicina Ambulatorial ? Condutas de atenção primária baseadas em evidências. Artmed. Terceira\nEdição 2004.)","options":{"A":"CONFORME IMAGEM DO CADERNO DE QUESTÕES.","B":"CONFORME IMAGEM DO CADERNO DE QUESTÕES.","C":"CONFORME IMAGEM DO CADERNO DE QUESTÕES.","D":"CONFORME IMAGEM DO CADERNO DE QUESTÕES.","E":"Nenhuma das alternativas acima está correta."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":["question_bank/media/medcurso/med-cirurgia-med-cir-07/154896.png"],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-149431","number":"149431","sourceNumber":"149431","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Sobre as disfunções do trato urinário inferior, assinale a alternativa correta.","options":{"A":"No período peri e pós-menopausa em pacientes sem sintomas de LUTS, 95% das mulheres têm\nresíduo pós-miccional menor que 100 mL.","B":"No estudo urodinâmico, a medida da pressão de fechamento uretral define claramente o grau de\nseveridade da incontinência urinária","C":"O diário miccional é um método qualitativo objetivo de sintomas, porém não deve ser utilizado\nem estudos clínicos, à exceção daqueles sobre\nbexiga hiperativa.","D":"O chamado pad test e a uretrocistografia miccional representam, atualmente, exames essenciais\npara o diagnóstico e a quantificação da\nincontinência urinária de esforço.","E":"A maioria dos parâmetros avaliados na urodinâmica não mostram variações dentro do mesmo\nexame ou ao longo do tempo, o que torna esse\nexame ideal para avaliações clínicas."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-149432","number":"149432","sourceNumber":"149432","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Em relação à litíase renal, atribua V (verdadeiro) ou F (falso) às afirmativas a seguir.\n( )\nO composto mais comumente encontrado nos cálculos é o fosfato de cálcio.; ( ) Atinge mais\nfrequentemente homens do que mulheres, em uma proporção de 2:1.; ( ) A taxa de recorrência de\nlitíase em pacientes sem tratamento é de cerca de 10% em 10 anos.; ( ) Alta ingesta de sódio induz\nhipercalciúria, o que pode aumentar o risco de formação de cálculos.; ( ) O citrato e o magnésio são\nconsiderados inibidores da cristalização urinária. Assinale a alternativa que contém, de cima para\nbaixo, a sequência correta.","options":{"A":"V, V, F, F, V.","B":"V, F, V, V, F.","C":"F, V, V, F, F.","D":"F, V, F, V, V.","E":"F, F, V, V, F."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-149479","number":"149479","sourceNumber":"149479","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A osteoartrite, antes denominada osteoartrose, artrose, doença articular degenerativa,\nentre outras, é a doença articular mais\nprevalente. Em relação à osteoartrite, assinale a alternativa\nCORRETA:","options":{"A":"A destruição cartilaginosa, com diminuição da sua espessura, traduz-se radiograficamente como\nesclerose subcondral.","B":"Anti-inflamatórios não hormonais não devem ser utilizados no tratamento da osteoartrite, pois\nnão há evidência de sua eficácia.","C":"Até os 50 anos de idade, a osteoartrite de quadris é mais prevalente no sexo feminino.","D":"Dor, rigidez pós-repouso menor que 30 minutos, parestesias e derrame articular são sinais ou\nsintomas da osteoartrite.","E":"Nódulos de Heberden são nódulos articulares ósseos localizados nas interfalangianas proximais."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-140100","number":"140100","sourceNumber":"140100","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"O componente mais frequente do cálculo renal é:","options":{"A":"Ácido úrico.","B":"Cistina.","C":"Oxalato de cálcio.","D":"Fosfato de cálcio.","E":"Fosfato de amônia magnesiano."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-126198","number":"126198","sourceNumber":"126198","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"O fator mais significante que contribui para a formação de cálculo renal de estruvita\n(fosfato amoníaco magnesiano), é:","options":{"A":"Gota úrica.","B":"História familiar.","C":"Infecções do trato urinário.","D":"Hipercalciúria.","E":"Hipocitratúria."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-126441","number":"126441","sourceNumber":"126441","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A Osteoartrite (OA) tem sido considerada uma condição degenerativa da articulação,\nconsequência quase inevitável do envelhecimento. Com relação à osteoartrite é correto afirmar:","options":{"A":"Algumas formas de osteoartrite estão fortemente vinculadas à transmissão genética como a\nosteoartrite cervical e a osteoartrite acrômio-clavicular.","B":"A rizartrose engloba o envolvimento do semilunar com o primeiro metacarpal e em menor\nfrequência do semilunar com o escafoide.","C":"O alargamento de consistência rígida nas articulações interfalangianas distais e próximas são\ndenominados nódulos de Bouchard e Heberden respectivamente.","D":"O quadril é uma articulação frequentemente acometida pela osteoartrite sendo mais frequentes\nem mulheres com envolvimento unilateral.","E":"Na mulher a osteoartrite inicia basicamente após os 40 anos e sua incidência aumenta\nsignificativamente após a menopausa."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-128974","number":"128974","sourceNumber":"128974","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Com relação à nefrolitíase, assinale a alternativa INCORRETA.","options":{"A":"Distúrbios metabólicos mais frequentes em pacientes litiásicos são a hipercalciúria,\nhipocitratúria\ne a hiperexcreção de ácido úrico.","B":"No manejo da hipercalciúria podemos incluir a dieta hipoprotéica e hipossódica, diuréticos\ntiazídicos es e farelo de arroz.","C":"A ingestão de altas doses de vitamina C aumenta a produção endógena de oxalato que pode ter\nimplicação na formação de cálculos renais.","D":"Na cistinúria podemos encontrar cristais hexagonais no sedimento urinário e o tratamento\nenvolve acidificação urinária para prevenir a\nrecorrência da nefrolitíase.","E":"Hiperexcreção de ácido úrico pode ser tratada com dieta pobre em purinas, alopurinol e\nalcalinização urinária com citrato de potássio."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-126376","number":"126376","sourceNumber":"126376","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente feminino, 46 anos, procura a Unidade de Saúde em consulta médica\nagendada, referindo dor nas costas há um ano,\niniciada após ter dado \"mau jeito\" ao levantar um\nbalde com água. Não está em uso de nenhuma medicação atualmente e atribui, em escala verbal\nnumérica, nota 6 para dor no momento da consulta, localizada em região lombar baixa. Com\nrelação aos principais medicamentos utilizados na abordagem da dor crônica, pode-se afirmar que:","options":{"A":"A dipirona é um analgésico comum que deve ser usado com parcimônia pelo alto risco de efeitos\nadversos hematopoiéticos.","B":"A literatura descreve o ibuprofeno como anti-inflamatório não esteróide com melhor perfil com\nrelação à ocorrência de efeitos adversos.","C":"A morfina é um opióide para tratamento de dor moderada a intensa que tem seu uso suspenso\nna presença de efeitos gastrintestinais.","D":"Os antidepressivos tricíclicos tem efeito analgésico em doses inferiores às antidepressivas e\ncom mesmo período de latência.","E":"Os anticonvulsivantes tem protagonismo no tratamento da dor neuropática com uso restrito nos\npacientes com doença renal crônica."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-126709","number":"126709","sourceNumber":"126709","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"A litíase urinária é uma condição patológica bastante frequente. Em relação às medidas\nnão medicamentosas que podem ser orientadas como\nprevenção da formação de novos cálculos,\nconsidere as afirmativas a seguir: I. Aumento de alimentos ricos em potássio e citrato; II.\nHidratação\ne atividades físicas adequadas; III. Redução de purinas, especialmente de proteínas de origem\nanimal; IV. Redução de sal, pimenta e gorduras. Assinale a alternativa CORRETA:","options":{"A":"Somente as afirmativas I e II são corretas.","B":"Somente as afirmativas I e IV são corretas.","C":"Somente as afirmativas III e IV são corretas.","D":"Somente as afirmativas I, II e III são corretas.","E":"Somente as afirmativas II, III e IV são corretas."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-101096","number":"101096","sourceNumber":"101096","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Em relação ao Antígeno Prostático Específico (PSA), que tem relevante importância na\navaliação da próstata humana, é correto afirmar:","options":{"A":"O PSA é um antígeno câncer de próstata específico.","B":"Encontra-se aumentado em aproximadamente 50% nos homens que utilizam finasterida.","C":"O tempo de duplicação do PSA menor que 6 meses indica doença de prognóstico muito\nfavorável.","D":"Na prostatite aguda, o PSA habitualmente está elevado com a relação entre PSA total e livre\nsempre menor que 10%.","E":"PSA maior que 0,200 ng/ml após a prostatectomia radical indica recaída bioquímica da doença."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-101104","number":"101104","sourceNumber":"101104","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Uma senhora de 48 anos, portadora de infecção urinária há 1 ano, vem à consulta\nmédica portando um RX de abdome onde se evidencia\num cálculo medindo 3 cm, com baixa\ndensidade e formato da pelve e cálices renais, em topografia de rim direito. A urinálise apresenta\npH 7 e piúria e a urocultura apresenta Proteus mirabilis. Qual a hipótese mais provável para a\ncomposição da urolitíase?","options":{"A":"Oxalato de cálcio.","B":"Estruvita.","C":"Ácido úrico.","D":"Fosfato de cálcio.","E":"Cistina."},"answer":"B","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-86321","number":"86321","sourceNumber":"86321","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Paciente do sexo masculino, 45 anos, trabalhador da construção civil, com carteira\nassinada, previamente hígido. Há mais ou menos 6\nmeses iniciou com dor nas costas, como\nqueimação, com piora aos esforços, sem irradiação. Tem feito uso regularmente de injeções de\nanti-inflamatórios, com melhora apenas temporária. Nega história de trauma, perda de peso, febre,\nincontinência urinária ou fecal. Ao exame apresenta dor e espasmo à palpação da musculatura\nparavertebral lombar bilateralmente. Laségue negativo e exame neurológico sem alterações de\nforça ou reflexos profundos nos membros inferiores. Assinale a alternativa CORRETA, que indica o\nmanejo inicial mais adequado para o caso apresentado.","options":{"A":"Solicitar ressonância de coluna lombossacra.","B":"Solicitar raio X de coluna lombossacra.","C":"Paracetamol 750 mg de 6 em 6 horas e reavaliar entre 2 a 4 semanas.","D":"Prescrever anti-inflamatórios e encaminhar à ortopedia.","E":"Afastar do trabalho por 15 dias e oferecer atestado para benefício junto ao INSS."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-81406","number":"81406","sourceNumber":"81406","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Qual a constituição mais comum dos cálculos em vias urinárias?","options":{"A":"Ácido úrico.","B":"Cistina.","C":"Indinavir.","D":"Oxalato de cálcio.","E":"Bicarbonato de cálcio."},"answer":"D","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-78048","number":"78048","sourceNumber":"78048","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Um homem de 34 anos de idade apresentou, há duas semanas, dor em flanco direito,\npor várias horas, associada à hematúria.\nDesde então, tem tido vários episódios de hematúria sem\ndor. Não apresentou febre, calafrios, disúria ou perda de peso. O exame físico é normal, exceto por\ndor à percussão em região lombar direita. Realizou RX simples de abdome e pelve, por duas vezes,\ndepois de adequado preparo intestinal, cujo laudo foi normal. Uma ecografia abdominal superior\nrevelou imagem com sombra acústica posterior em pelve renal direita, de dois centímetros de\ndiâmetro. Qual dos seguintes diagnósticos é mais provável?","options":{"A":"Cálculo de ácido úrico na pelve renal direita.","B":"Nefrocalcinose medular à direita.","C":"Cálculo de oxalato de cálcio na pelve renal direita.","D":"Rim espongiomedular unilateral na pelve renal direita.","E":"Carcinoma de células transicionais em pelve direita."},"answer":"A","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-78028","number":"78028","sourceNumber":"78028","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Sobre a litíase urinária, considere as seguintes alternativas: 1. A composição da litíase\nurinária coraliforme geralmente é estruvita e na maioria das vezes está associada à infecção\nurinária por germe produtor de urease. 2. A nefrolitotripsia percutânea é um tratamento eficaz para\nos cálculos renais maiores que 3 cm. 3. A ureterolitotripsia apresenta excelentes resultados para o\ntratamento dos cálculos de ureter inferior não infectados, na falha do tratamento clínico. 4. A\nlitotripsia extracorpórea por ondas de choque pode ser utilizada como primeira escolha de\ntratamento para todos os cálculos renais, mesmo que na vigência de infecção urinária. 5. Os\ncálculos de bexiga geralmente são secundários. Assinale a alternativa CORRETA:","options":{"A":"Somente as afirmativas 1 e 2 são verdadeiras.","B":"Somente as afirmativas 3 e 5 são verdadeiras.","C":"Somente as afirmativas 1, 2, 3 e 5 são verdadeiras.","D":"Somente as afirmativas 2, 3 e 4 são verdadeiras.","E":"As afirmativas 1, 2, 3, 4 e 5 são verdadeiras."},"answer":"C","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-cirurgia-med-cir-07-81336","number":"81336","sourceNumber":"81336","collectionBlock":"med:med-cirurgia-med-cir-07","collectionLabel":"MED · MED CIR 07","documentBlock":"","area":"Cirurgia","specialty":"Cirurgia","topic":"MED CIR 07","subtopic":"","stem":"Mulher, 70 anos, hipertensa, obesa, história pregressa de artrite reumatoide, refere\ndispneia progressiva há 2 meses. Refere\nortopneia, paroxística noturna, edema de MMII e\nformigamento em membros inferiores há 20 dias. Ao Ex. físico apresentava-se hipocorada,\nhidratada, taquipneica, (FR: 32), acianótica, PA: 120/70 mmHg, RCR-3T (B4), estertores crepitantes\nem bases de ambos os hemitóraces, hepatoesplenomegalia discreta e hipoestesia distal em MMII e\nhiporreflexia aquiliana. Laboratório: Hb: 10; VG: 31%; 6500 leuc. Ur: 105; creatinina: 3,0; AST: 45;\nALT: 36; TAP: 60. RX de tórax com aumento moderado da área cardíaca com congestão pulmonar\ne ecocardiograma transtorácico com espessamento simétrico da parede do VE e do septo\nintraventricular, além de disfunção predominantemente diastólica. Qual dos exames abaixo tem a\nmaior chance de confirmar o diagnóstico desse caso?","options":{"A":"Dosagem de hormônios tireoidianos.","B":"C-ANCA.","C":"Dosagem sérica de vitamina B12.","D":"Prova terapêutica com tiamina.","E":"Biópsia de mucosa retal."},"answer":"E","source":"Cirurgia/MED CIR 07/MED CIR 07.txt","sourceLabel":"MED · MED CIR 07","images":[],"optionImages":{},"commentImages":[],"tags":["Cirurgia","MED CIR 07","MED"],"answerSource":"explicit","commentDeferred":true}]};
